["mrb_rvd1_01_01"] = "NE OLUYOR LAN? BİR OROSPU ÇOCUĞU BİZİ SATTI.",
["mrb_rvd1_01_02"] = "SİZ DENGELİ ADAMLARSINIZ SANIYORDUM. ORADA NE OLDU LAN?",
["mrb_rvd1_02a_01"] = "BEKLERKEN ŞU KÜÇÜK CİYAKLAYAN OYUNCAĞIMIZLA OYNASAK YA?",
["mrb_rvd1_03b_01"] = "TAMAM DONUT OĞLANI. BUNU ÇIKARACAĞIM, SEN DE KONUŞACAKSIN, CAPİSCİ? BİZİ KİM TUZAĞA DÜŞÜRDÜ?",
["mrb_rvd1_03c_01"] = "NEDEN SANA İNANMIYORUM ACABA? BELKİ ŞU ADAMI VURMALIYIM.",
["mrb_rvd1_03c_02"] = "DÜRÜST OLDUĞUNU SANMIYORUM KÜÇÜK DOMUZCUK. BELKİ DE SENİ VURURUM.",
["mrb_rvd1_03c_03"] = "KONUŞMAYACAKSAN SENİ VURACAĞIM ARTIK.",
["mrb_rvd1_03c_04"] = "BEN DE BURADA NEZAKET GÖSTERİYORDUM. AĞZINA BİRAZ KURŞUN TIKSAM NASIL OLUR?",
["mrb_rvd1_03c_05"] = "TEK BİR ŞANSINIZ VARDI, ONU DA MAHVETTİNİZ. HOŞÇA KAL DE KÜÇÜK POLİS.",
["mrb_rvd1_04_01"] = "SİZ ONUNLA İLGİLENİN, BEN BURADAKİ KÜÇÜK OĞLUMUZLA UĞRAŞAYIM...",
["mrb_rvd1_04_02"] = "SİZ DOMUZLARLA İLGİLENİRKEN BU ADAMI GÖZDEN UZAKLAŞTIRACAĞIM.",
["mrb_rvd1_05_01"] = "HEYECANLI ŞEY ŞU İHANET İŞİ. SİZİN BAŞINIZA ÇOK GELİR Mİ?",
["mrb_rvd1_05_02"] = "PATRONUNU KAYBETMEK İYİ DEĞİLDİR. UMARIM İŞİ ÇÖZERSİNİZ.",
["mrb_rvd1_05_03"] = "ELMAS UĞURSUZLUK GETİRİYOR DOSTUM.",
["mrb_rvd1_05_04"] = "KEYFİN YERİNDE Mİ, ÇÖREKÇİ ÇOCUK?",
["mrb_rvd1_05_05"] = "ŞU İHANET BOKLARI YÜZÜNDEN NEREDEYSE HAPSE GERİ DÖNESİM GELİYOR.",
["mrb_rvd1_05_06"] = "SANIRIM ÖĞLEN YEDİĞİM HAMBURGER MİDEME OTURDU.",
["mrb_rvd1_05_07"] = "DUYDUĞUMA GÖRE BAIN HEP DÜZGÜN BİR ADAMMIŞ. UMARIM İŞİ ÇÖZERSİNİZ.",
["mrb_rvd1_05_08"] = "SİZİN LOCKE İŞİ HALLETMEZSE CABOT ÇÖZER.",
["mrb_rvd1_05_09"] = "SİNATRA SEVER MİSİNİZ? İŞİN HEMEN ARDINDAN DİNLEYİN. İNSANI GÜZEL SAKİNLEŞTİRİR. AMA İŞLER KÖTÜ GİDERSE ELVİS DİNLEYİN. ÇÜNKÜ O BOKU YALNIZ ELVİS DÜZELTİR.",
["mrb_rvd1_05_10"] = "SOYGUNLARDA BİLGİSAYAR GEREKMEDİĞİ ESKİ GÜNLERİ HATIRLIYORUM. O ZAMANLAR KİME GÜVENECEĞİNİ BİLİRDİN.",
["mrb_rvd1_06_01"] = "YOK, BU ADAMLAR DÜZGÜN GÖRÜNÜYOR.",
["mrb_rvd1_06_02"] = "OLABİLİR AMA İÇİMDEN BİR SES BU ADAMLAR DEĞİL DİYOR.",
["mrb_rvd1_07_01"] = "EE MİLLET. GANİMETİMİZE NE OLDUĞUNU MERAK EDİYOR OLABİLİRSİNİZ. ARABAYI BIRAKMAM GEREKTİ AMA BİR KISMINI YAKINDAKİ BİR DEPOYA SAKLAYABİLDİM.",
["mrb_rvd1_07_02"] = "DURUM ŞU. ARABAM BOZULDU AMA BİRAZ ELMASI KAÇIRABİLDİM. YAKINDAKİ BİR DEPOYA ZULALADIM.",
["mrb_rvd1_07_03"] = "İYİ HABERİM DE VAR, KÖTÜ HABERİM DE. KÖTÜ HABER, ARABAM ÖLDÜ. İYİ HABER, BAGAJDAN BİRKAÇ ELMAS ALMAYA VAKTİM OLDU. YAKINLARDAKİ BİR DEPODALAR.",
["mrb_rvd1_07b_01"] = "SOKAĞIN KARŞISINDAKİ DEPONUN YANINDA. AMA AÇMAK İÇİN TESTERE GEREKECEK, ÇÜNKÜ KARGAŞADA ANAHTARI KAYBETTİM. ARKADA BİR TANE VAR.",
["mrb_rvd1_07c_01"] = "DIŞARIDA, OTOPARKIN YANINDA. AMA TESTERE OLMADAN AÇILMAZ. BURALARDA BİR YERDE VAR.",
["mrb_rvd1_07d_01"] = "TA ORADA, OTOPARKIN ARKASINDA. DEPONUN KAPISI EPEY KALIN, ANAHTARI DA BENDE YOK. KESEREK AÇMAMIZ GEREKECEK. BURALARDA BİR TESTERE OLMALI.",
["mrb_rvd1_08_01"] = "HARİKA, BÜTÜN BUNLAR BİTİNCE BUNLAR CABOT'U MUTLU EDECEK.",
["mrb_rvd1_08_02"] = "HARİKA, EN AZINDAN BU FİYASKO TÜMÜYLE ZARAR OLMADI.",
["mrb_rvd1_08_03"] = "BUGÜN YAŞANAN ONCA BOKTAN SONRA BİLE FENA DEĞİL.",
["mrb_rvd1_09_01"] = "HEY, AZ ÖNCE HABER ALDIM. CABOT BİZİ ALMAYA BİRİNİ GÖNDERİYOR AMA GELMEDEN SIVIŞSANIZ İYİ OLUR. ŞU AN PEK MUTLU DEĞİL.",
["mrb_rvd1_09_02"] = "PATRONDAN AZ ÖNCE HABER ALDIM. BİZİ ALMAYA GELİYOR AMA EPEY KIZGIN. O GELMEDEN SIVIŞMAK İSTEYEBİLİRSİNİZ.",
["mrb_rvd1_09_03"] = "PATRON AZ ÖNCE ARADI, KIZGIN. BİZİ ALMAYA BİRİ GELİYOR AMA SİZ KAÇSANIZ İYİ OLUR. PAYINIZI ALMANIZI SAĞLARIM.",
["mrb_rvd1_10a_01"] = "VAY, BİZİ EKİP BİR GÖSTERİYE Mİ GİTTİNİZ DİYE DÜŞÜNÜYORDUM.",
["mrb_rvd1_10a_02"] = "HEY. NEREDEYSE KAYBOLDUNUZ FALAN SANMIŞTIM.",
["mrb_rvd1_10a_03"] = "DEMEK MEŞHUR PAYDAY GANG SİZSİNİZ. KOCAMAN, MUTLU BİR AİLE OLACAĞIZ GALİBA.",
["mrb_rvd1_10b_01"] = "PEKÂLÂ, GİDİP ŞU İŞİ YAPALIM DA AKŞAM YEMEĞİ YİYEBİLEYİM.",
["mrb_rvd1_10b_02"] = "ŞU İŞİ HALLEDELİM. GİTMEM GEREKEN BİR YER VAR.",
["mrb_rvd1_10b_03"] = "HADİ BAŞLAYALIM. PATRON TAŞLARINI BEKLİYOR.",
