["mrb_rvd1_13_02"] = "MALLARIN BAGAJDAN ÇALINMAMASINI SAĞLAYACAK BİRİNİ BULDUM.",
["mrb_rvd1_14_01"] = "ŞUNU DÜŞÜRMEYİN.",
