["mrb_rvd1_14_04"] = "YARDIM EDERDİM AMA ARABA BENSİZ YALNIZ KALIYOR.",
["mrb_rvd1_14_05"] = "HEY, BİR DAHAKİ GELİŞİNDE BANA HAMBURGER GETİR.",
