["mrb_rvd1_24_02"] = "SEKİZ",
["mrb_rvd1_25_01"] = "DOKUZ BEŞ MESAİSİ... GEÇİNMEK İÇİN NE BERBAT YOL.",
["mrb_rvd1_25_02"] = "DOKUZU TAMAM.",
["mrb_rvd1_26_01"] = "DEVAM ETMEK İSTEMİYORSANIZ SİHİRLİ SAYIMIZ ON MİLLET.",
["mrb_rvd1_26_02"] = "DAHA FAZLASINI DENEMEK İSTEMİYORSANIZ ASGARİ MİKTARIMIZ BU.",
["mrb_rvd1_27_01"] = "BAGAJDA BİR TANE DAHA VAR.",
["mrb_rvd1_27_02"] = "İYİ Kİ AMERİKAN ARABASI ALMIŞIM. ŞU YABANCILARIN BAGAJI HİÇ YETERİNCE BÜYÜK OLMAZ.",
["mrb_rvd1_27_03"] = "BİRİLERİ BU GECE EĞLENECEK. BURADAN ÇIKABİLİRSEK TABİİ.",
["mrb_rvd1_27_04"] = "DAHA MI VAR? NEREDEYSE AÇGÖZLÜLÜK GİBİ GELİYOR.",
["mrb_rvd1_27_05"] = " BUNUNLA GÜZEL BİR EMEKLİLİK FONU KURULUR.",
["mrb_rvd1_28_01"] = "MİLLET, BU ŞEYLERLE BURADAN ÇIKMAK İÇİN BİRAZ YARDIMA İHTİYACIM OLACAK.",
["mrb_rvd1_28_02"] = "HEY, BİRAZ YARDIM OLMADAN BURADAN ÇIKAMAYACAĞIM.",
["mrb_rvd1_28_03"] = "ARABAYLA ÖYLECE KAÇMAM İÇİN ATEŞ ÇOK YOĞUN. YARDIM GEREKECEK MİLLET.",
["mrb_rvd1_29_01"] = "ÇOK SAĞ OLUN BEYLER! DEPODA GÖRÜŞÜRÜZ!",
["mrb_rvd1_29_02"] = "İYİ İŞ MİLLET! ELİNİZ DEĞMİŞKEN BANA BİR HAMBURGER ALIN. DEPODA GÖRÜŞÜRÜZ!",
["mrb_rvd1_29_03"] = "DOMUZLARI ATLATTIM MİLLET, SAĞ OLUN! BİRAZDAN GÖRÜŞÜRÜZ. BİR DE BANA HAMBURGER GETİRİN!",
["mrb_rvd1_30_01"] = "EVET, O MESELE. BURADA DIŞARIDA. ARABAMDA.",
["mrb_rvd1_30_02"] = "İÇERİ GETİRMEDİM. DIŞARIDA, BAGAJIMDA.",
["mrb_rvd1_30_03"] = "ŞÖYLE BİR ŞEY VAR. BURADA, YANIMDA... ARABAMDA.",
["mrp_rvd_01_01"] = "HEY, BENİ DUYAN VAR MI? NE OLUYOR LAN? HIZLA GELİYORUM... YAN TARAFIMDAN KURŞUN YEDİM.",
["mrp_rvd_01_02"] = "NEREDESİNİZ LAN? GELECEĞİMİZİ NEREDEN BİLİYORLARDI? DEPOYA GELİYORUM... VURULDUM.",
["mrp_rvd_01_03"] = "HEY PİÇLER, POLİS KIÇIMDA. VURULDUM. ORADA NE OLDU LAN?",
["mrp_rvd_02_01"] = "HEY, GELDİM... DIŞARIDAYIM... SOKAKTAN UZAK DEĞİL! BOKTAN ARABA!",
["mrp_rvd_02_02"] = "SİKTİİİİR. MİLLET, GELİP BENİ OTOPARKTAN ALIN!",
["mrp_rvd_02_03"] = "SİKTİĞİMİN BOKTAN ARABASI! BURADA YARDIMA İHTİYACIM VAR, MİLLET!",
["mrp_rvd_02_04"] = "TANRIM MİLLET, POLİS GELMEDEN GELİP BENİ ALIN. EN ARKADAYIM!",
["mrp_rvd_02_05"] = "BEN NEREDEYİM LAN? GÖRDÜĞÜM... DEPOLAR MI?",
["mrp_rvd_03_01"] = "ACELE EDİN LANET OLSUN!",
["mrp_rvd_03_02"] = "NE BU KADAR UZUN SÜRÜYOR LAN?",
["mrp_rvd_03_03"] = "ÇABUK DOSTUM, POLİSLER ÇİM BİÇME MAKİNESİYLE GELMİŞ GİBİ GÖTÜMÜ BİÇECEKLER!",
["mrp_rvd_03_04"] = "PARMAKLARINIZI GÖTÜNÜZDEN ÇIKARIN DA GELİP BENİ ALIN!",
["mrp_rvd_03_05"] = "NE SİKİME BU KADAR UZUN SÜRÜYOR? BURADA KAN KAYBEDİYORUM!",
["mrp_rvd_03_06"] = "HASSİKTİR MİLLET, BENİ PESTİLE ÇEVİRECEKLER.",
["mrp_rvd_03_07"] = "HADİ DOSTUM, YA BENİ ALIN YA DA TAKSİ YOLLAYIN.",
["mrp_rvd_03_08"] = "TEPEMDELER MİLLET, DAHA FAZLA DAYANAMAM AMINA KOYAYIM!",
["mrp_rvd_04_01"] = "NİYE BU KADAR UZUN SÜRDÜ LAN?",
["mrp_rvd_04_02"] = "TANRIM, NE KADAR UZUN SÜRDÜ LAN!",
["mrp_rvd_04_03"] = "SİKTİR DOSTUM, BURADA ÖLÜYORUM. NE YAPTINIZ, SOSİSLİ MOLASI MI VERDİNİZ?",
