["mrp_rvd_06_01"] = "ORADA NE SİKİM OLDU? POLİS BURADA OLDUĞUMUZU O KADAR ÇABUK ÖĞRENMİŞ OLAMAZ.",
["mrp_rvd_06_02"] = "YEMİN EDERİM BİR SÜRE TAKİP EDİLDİM. ÜSTELİK POLİS DE DEĞİLDİ.",
