["mrp_rvd_07_05"] = "D.C.'DE HAYAT NASIL? MAAŞA BAĞLADIĞINIZ O PİSLİK SİYASETÇİLER POLİSLERİ KIÇINIZDAN UZAK TUTUYOR MU?",
["mrp_rvd_07_06"] = "ELMAS İŞLERİ HEP SİKTİĞİMİN KAN BANYOSUNA DÖNÜYOR. BİR SEFERİNDE KAN KURUDUĞU İÇİN BİR ADAMI YERDEN KÜREKLE KAZIMALARI GEREKMİŞ DİYE DUYDUM.",
