["mrp_rvd_07_08"] = "KEŞKE ŞU AN KIZ ARKADAŞIMLA BİR HAMBURGERCİDE OLSAYDIM.",
["mrp_rvd_08_01"] = "PEKİ, ŞU PAYDAY ELEMANLARI HAKKINDA GERÇEKTEN NE BİLİYORSUN? BU BOKUN BİZİM YÜZÜMÜZDEN ÇIKTIĞINI SANMIYORUM.",
["mrp_rvd_08_02"] = "CABOT'UN GETİRDİĞİ ŞU PAYDAY GANG... BUNUN ONLARIN BOKU OLMADIĞINDAN EMİN MİYİZ?",
