["mutator_birthday"] = "YIL DÖNÜMÜ ETKİNLİĞİ",
["mutator_birthday_desc"] = "ÖZEL BİRİMLERİ ÖLDÜRDÜĞÜNDE BALONLAR ORTAYA ÇIKAR. BALONLARI VURARAK TÜM EKİBE GÜÇLENDİRME VEREBİLİRSİN. ÖLDÜRÜLEN BİRİME GÖRE BU, DOĞRUDAN BONUS VEYA SÜRELİ BİR ETKİ OLABİLİR. BAZI BİRİMLER DAHA SIK BALON ÇIKARIR. AYNI ANDA BİRDEN FAZLA GÜÇLENDİRME ETKİN OLABİLİR.",
