["mutator_enemy_damage_longdesc"] = "OYUNCULAR DÜŞMANLARIN SALDIRILARINDAN NORMALDEN DAHA FAZLA HASAR ALIR.",
["mutator_enemy_health"] = "EĞİTİM SAYESİNDE",
["mutator_enemy_health_desc"] = "DÜŞMANLARIN BAŞLANGIÇ SAĞLIĞINI DEĞİŞTİR.",
["mutator_enemy_health_longdesc"] = "DÜŞMANLAR NORMALDEN DAHA FAZLA SAĞLIKLA ORTAYA ÇIKAR; BU DA ÖLDÜRÜLMELERİNİ KOLAYLAŞTIRIR VEYA ZORLAŞTIRIR.",
