["mutator_hydra"] = "HİDRALAR",
["mutator_hydra_desc"] = "ÖLDÜRÜLEN DÜŞMAN 2 DAHA GÜÇSÜZ DÜŞMANA BÖLÜNÜR.",
["mutator_hydra_longdesc"] = "ÖLDÜRÜLEN DÜŞMAN, BULUNDUĞU YERDE DAHA GÜÇSÜZ 2 DÜŞMANA BÖLÜNÜR. BU BÖLÜNME, ORTAYA ÇIKAN DÜŞMANLAR DAHA DA GÜÇSÜZLERİNE BÖLÜNEMEYENE KADAR SÜRER.",
["mutator_hydra_split_num"] = "$splits; BÖLÜNME",
["mutator_medidozer"] = "SIKI DOSTLAR",
["mutator_medidozer_desc"] = "TÜM NORMAL DÜŞMANLAR MEDIC, TÜM ÖZEL BİRİMLER İSE BULLDOZER İLE DEĞİŞTİRİLİR.",
["mutator_medidozer_longdesc"] = "SALDIRI DALGALARI SIRASINDA TÜM NORMAL DÜŞMANLAR MEDIC, TÜM ÖZEL BİRİMLER İSE BULLDOZER İLE DEĞİŞTİRİLİR.",
["mutator_piggybank"] = "YIL DÖNÜMÜ ETKİNLİĞİ",
["mutator_piggybank_desc"] = "PİGGY BUCKS ÇANTALARI KAZANMAK İÇİN DÜŞMANLARI KAFADAN VURUŞLARLA VEYA CASH BLASTER İLE ÖLDÜR. SONRA BÜYÜTMEK İÇİN ÇANTALARI KUMBARAYA YATIR!",
["mutator_shield_dozers"] = "AŞIRI DOZER",
["mutator_shield_dozers_desc"] = "BULLDOZER BİRİMLERİ KALKAN TAŞIR.",
["mutator_shield_dozers_longdesc"] = "TÜM BULLDOZER BİRİMLERİ KORUNMAK İÇİN KALKAN TAŞIR.",
["mutator_shotgun_tweak"] = "DÜNYA DIŞI SOYGUNCULAR",
["mutator_shotgun_tweak_desc"] = "POMPALIYLA ÖLDÜRÜLEN DÜŞMANLAR HAVAYA UÇAR.",
["mutator_shotgun_tweak_longdesc"] = "BAIN SONUNDA GERÇEK KİMLİĞİ THE MOTHER-BAIN’İ AÇIKLADI. POMPALILARIN, ANA GEMİYE GERİ GÖTÜREBİLMEN İÇİN DÜŞMANLARI KAÇIRACAK. THE MOTHER-BAIN’İ HAYAL KIRIKLIĞINA UĞRATMA.",
["mutator_shotgun_tweak_mothership"] = "ANA GEMİYE!",
["mutator_specials_override"] = "KLON ORDUSU",
["mutator_specials_override_desc"] = "DİĞER TÜM DÜŞMANLARIN YERİNE HANGİ ÖZEL BİRİMİN ORTAYA ÇIKACAĞINI BELİRLE.",
["mutator_specials_override_longdesc"] = "SALDIRI EVRELERİNDE ORTAYA ÇIKAN TÜM DÜŞMANLAR, SEÇTİĞİN ÖZEL BİRİMLE AYNI SAYIDA OLACAK ŞEKİLDE DEĞİŞTİRİLİR.",
["mutator_specials_override_medic"] = "MEDIC BİRİMLERİ",
["mutator_specials_override_select"] = "ÖZEL BİRİM",
["mutator_specials_override_shield"] = "SHIELD BİRİMLERİ",
["mutator_specials_override_spooc"] = "CLOAKER BİRİMLERİ",
["mutator_specials_override_tank"] = "BULLDOZER BİRİMLERİ",
["mutator_specials_override_taser"] = "TASER BİRİMLERİ",
["mutator_titandozers"] = "UYANIK KÂBUS",
["mutator_titandozers_desc"] = "BAŞSIZ TİTAN BULLDOZER, WOLF’UN KÂBUSLARINDAN KAÇTI!",
["mutator_titandozers_longdesc"] = "BAŞSIZ TİTAN BULLDOZER, WOLF’UN KÂBUSLARINDAN KAÇIP GERÇEĞE DÖNÜŞTÜ! ARTIK TÜM NORMAL BULLDOZER BİRİMLERİ KORKUNÇ BAŞSIZ TİTAN BULLDOZER OLACAK!",
["myh_desc"] = "UYRUĞU: KUZEY AMERİKALI$NL;YAŞI: 50’Lİ YAŞLARINDA$NL;$NL;BİR ZAMANLAR AUGUST LİNDENHURST TAKMA ADINI KULLANAN DUKE, PAYDAY GANG EKİBİNE KATILIRKEN BU ADI BIRAKIP YALNIZCA \"DUKE\" ADINI BENİMSEDİ. SON BİRKAÇ YILDIR SUÇ DÜNYASININ DERİNLİKLERİNDEKİ ÖRÜNTÜLERİ VE SÖYLENTİLERİ ARAŞTIRIYOR. GEÇMİŞİN ÜNLÜ SOYGUNCULARIYLA BİRLİKTE TARİH KİTAPLARINA GEÇMESİNİ SAĞLAYACAK DESTANSI BİR SOYGUN GERÇEKLEŞTİRMEYE DOĞUŞTAN BİR İHTİYAÇ, HATTA SAPLANTI DUYUYOR. BAIN’İN ÇETESİNİN BU AMACINA ULAŞMASINA YARDIM EDEBİLECEĞİNE İNANIYOR.",
["neg_skm_01_01"] = "PEKÂLÂ, İÇERİ GİRİP SİZİ ALMAKTAN BAŞKA SEÇENEK BIRAKMADINIZ. BU İŞİ ZOR YOLDAN YAPACAĞIZ.",
["neg_skm_01_02"] = "SÜRENİZ DOLMAK ÜZERE PİSLİKLER. SİZİ DURDURMAK İÇİN GEREKEN HER ŞEYİ YAPMAYA GELİYORUZ.",
["neg_skm_01_03"] = "DİKKAT, BİZE DAHA FAZLA GÜÇ KULLANMAKTAN BAŞKA SEÇENEK BIRAKMIYORSUNUZ. BU SON UYARINIZ.",
["neg_skm_01_04"] = "TESLİM OLMADIĞINIZ İÇİN SİZİ GEREKLİ HER TÜRLÜ YÖNTEME BAŞVURARAK YAKALAMAK ZORUNDAYIZ.",
["neg_skm_01_05"] = "TAMAM PİSLİKLER, ŞANSINIZI KULLANDINIZ. SİZİ ALMAYA GELİYORUZ.",
["neg_skm_01_06"] = "TAMAM, TESLİM OLMA FIRSATINIZ VARDI. ARTIK EN AĞIR BASKIYI UYGULAMAK ZORUNDAYIZ.",
["neg_skm_01_07"] = "TAMAM PİSLİKLER, BURAYA KADAR. ÖLÜ YA DA DİRİ, BİZİMLE GELİYORSUNUZ.",
["neg_skm_02_01"] = "YENİ KELEPÇELİ CLOAKER'LARIMIZLA TANIŞIN. EMİNİM BAYILACAKSINIZ...",
["neg_skm_02_02"] = "BAKALIM YENİ KELEPÇELEYEN CLOAKER'LARIMIZLA NASIL BAŞ EDECEKSİNİZ...",
["neg_skm_03_01"] = "TERFİ ETMİŞ CLOAKER'LARIMIZLA TANIŞIN! KELEPÇELERİNE BAYILACAĞINIZDAN EMİNİM...",
["neg_skm_03_02"] = "SİZE GÜZEL BİR SÜRPRİZ VAR. CLOAKER'LARIMIZ ARTIK KELEPÇE TAŞIYOR!",
["neg_skm_04_01"] = "...ŞİMDİ DE YENİ HAFİF MAKİNELİ TÜFEKLİ BULLDOZER'LARIMIZLA BOĞUŞACAKSINIZ...",
["neg_skm_04_02"] = "YENİ HAFİF MAKİNELİ TÜFEKLİ BULLDOZER'LARIMIZA MERHABA DEYİN...",
["neg_skm_05_01"] = "YENİ ZEAL NİŞANCILARIMIZ KARŞISINDA NEFESİNİZ KESİLİRKEN HARİKA VAKİT GEÇİRECEĞİNİZE EMİNİM...",
["neg_skm_05_02"] = "ZEAL NİŞANCILARIMIZLA KARŞILAŞTIĞINIZDA YAPTIKLARINIZA PİŞMAN OLACAKSINIZ...",
["neg_skm_07_01"] = "YENİ MEDIC BULLDOZER'LARIMIZ SİZE ALÇAKGÖNÜLLÜLÜĞÜ ÖĞRETECEK...",
["neg_skm_07_02"] = "BELKİ YENİ MEDIC DOZER'LARIMIZ FİKRİNİZİ DEĞİŞTİRİR...",
["neg_skm_08_01"] = "MİNİGUN BULLDOZER'LARIMIZ SİZİ YOLA YAPIŞTIRACAK PALYAÇOLAR...",
["neg_skm_08_02"] = "BELKİ BİRKAÇ MİNİGUN BULLDOZER SİZİ SUSTURUR...",
["neg_skm_09_01"] = "DİKKAT, REHİNE GÜVENCEYE ALINIYOR VE ÖDEMENİZİ SERBEST BIRAKIYORUZ.",
["neg_skm_09_02"] = "PAYDAY GANG, REHİNEYİ TESLİM ALDIK, ÖDEMENİN AKTARILMASINA İZİN VERDİK.",
["neg_skm_09_03"] = "TAMAM PALYAÇOLAR, SÖZÜNÜZÜ TUTTUNUZ. REHİNE GÜVENDE, FİDYEYİ DE AKTARDIK.",
["neg_skm_10_01"] = "ŞAHIS GÜVENDE VE PARAYI HESABINIZA AKTARDIK. BU SEFER SİZ KAZANDINIZ PALYAÇOLAR.",
["neg_skm_10_02"] = "PARA ARTIK HESABINIZA AKTARILDI, BİZ DE HEDEFİ TESLİM ALDIK. BU SEFER ÜSTÜNLÜK SİZDEYDİ.",
["neg_skm_10_03"] = "TAMAM PALYAÇOLAR, İSTEDİĞİNİZİ ALDINIZ. PARA SERBEST BIRAKILDI, REHİNENİN GERİ ALINDIĞI DOĞRULANDI.",
["neg_skm_11_01"] = "BURASI POLİS. REHİNE İÇİN TAKASA HAZIRIZ, FİDYE TEKLİFİMİZİ DE ARTIRMAYA HAZIRIZ.",
["neg_skm_11_02"] = "POLİS! REHİNEYİ SERBEST BIRAKIN, TALEBİNİZİ KARŞILAMAYA ÇALIŞACAĞIZ!",
["neg_skm_11_03"] = "REHİNENİN SERBEST BIRAKILMASI İÇİN YENİDEN PAZARLIĞA HAZIRIZ. DAHA YÜKSEK BİR TEKLİF SUNMA YETKİMİZ VAR!",
["neg_skm_11_04"] = "ATEŞİ KESİN! REHİNE ZARAR GÖRMEDİYSE TEKLİFİMİZİ TALEBİNİZE KADAR YÜKSELTME YETKİM VAR.",
["neg_skm_11_05"] = "REHİNEYE ZARAR VERMEYİN! DAHA YÜKSEK BİR TUTAR İÇİN YENİDEN PAZARLIĞA HAZIRIZ!",
["neg_skm_12_01"] = "POLİS KONUŞUYOR. VARLIK KARŞILIĞINDA TAKASA HAZIRIZ, TEKLİFİMİZİ DE ARTIRABİLİRİZ.",
["neg_skm_12_02"] = "DİKKAT! REHİNE ZARAR GÖRMEDİYSE TEKLİFİMİZİ ARTIRMA YETKİMİZ VAR!",
["neg_skm_12_03"] = "ATEŞİ KESMENİZ KOŞULUYLA ŞAHSIN İADESİNİ YENİDEN MÜZAKERE ETMEYE HAZIRIZ!",
["neg_skm_12_04"] = "VARLIĞA ZARAR VERMEYİN! PAZARLIĞA VE TEKLİFİMİZİ ARTIRMAYA HAZIRIZ!",
["neg_skm_12_05"] = "ATEŞİ KESİN! REHİNE ZARAR GÖRMEDİYSE SERBEST BIRAKILMASI KARŞILIĞINDA TEKLİFİMİZİ ARTIRMA YETKİM VAR.",
["neg_skm_13_01"] = "SİZ İSTEDİNİZ PİSLİKLER. ÖLÜ YA DA DİRİ, BİZİMLE GELİYORSUNUZ.",
["neg_skm_13_02"] = "UYARILDINIZ. TESLİM OLUN, YOKSA ÖLDÜRMEK İÇİN ATEŞ EDECEĞİZ.",
["neg_skm_13_03"] = "BU BİR UYARIDIR. ÖLDÜRME YETKİMİZ VAR VE SÜRENİZ DOLDU. SIRA SİZDE PİSLİKLER.",
["neg_skm_14_01"] = "ŞAHIS KURTARILDI. SOYGUNCULAR KAYBETTİ, BUGÜN PARA ALAMAYACAKLAR, TAMAM.",
["neg_skm_14_02"] = "ŞAHIS ALINDI. BU, MAVİLİLERİN ZAFERİ, TAMAM.",
["neg_skm_14_03"] = "ŞAHIS GÜVENCEYE ALINDI. FAİLLER İÇİN OYUN BİTTİ, TAMAM.",
["neg_skm_15_01"] = "REHİNE KURTARILDI. PALYAÇOLAR BUGÜN KAYBETTİ, TAMAM.",
["neg_skm_15_02"] = "REHİNE ALINDI. PALYAÇOLAR BUNU BIRAKIP KUYRUKLARINI KISTIRARAK EVLERİNE DÖNMEK ZORUNDA KALACAK, TAMAM.",
["neg_skm_15_03"] = "REHİNE GÜVENDE. PALYAÇOLAR AVUÇLARINI YALADI, ELLERİ BOŞ DÖNECEKLER. TAMAM.",
["neg_skm_16_01"] = "BU SEFER İSTEDİĞİNİZ HER ŞEYİ ALMIŞ OLABİLİRSİNİZ PALYAÇOLAR. AMA SİZİN DE GÜNÜNÜZ GELECEK.",
["neg_skm_16_02"] = "TAMAM PALYAÇOLAR, İSTEDİĞİNİZ HER ŞEYİ ALDINIZ. AMA BİR GÜN BUNUN HESABINI VERECEKSİNİZ!",
["neg_skm_16_03"] = "BU SEFER BİZİ ALT ETMİŞ OLABİLİRSİNİZ PİSLİKLER AMA SONUNDA SİZİ YAKALAYACAĞIZ!",
["neg_skm_17_01"] = "ŞÜPHELİ GÖZALTINDA, TAMAM.",
["neg_skm_17_02"] = "BİR FAİL YAKALANDI, TAMAM.",
["neg_skm_17_03"] = "BİR ŞÜPHELİ GÖZALTINDA, TAMAM.",
["nmh_intro_01_01"] = "BEYLER, HAVADA BİR ŞEYLER VAR SANKİ... PARA!",
["nmh_intro_01_02"] = "SESİN KESİLİYOR... BENİ DUYABİLİYOR MUSUN?",
["nmh_intro_01_03"] = "EVET, EVET, EVET... PLANI UYGULAYIN!",
["nmh_intro_01_04"] = "TAMAM!",
["nmh_intro_01_05"] = "HEY, KAPIYI TUT!",
["nmh_intro_01_06"] = "LÜTFEN DIŞARI ÇIKIP SİGARA İÇİN, BURADA İÇEMEZSİNİZ EFENDİM... SAÇMALIK!",
["nmh_intro_01_07"] = "İYİ GÜNLER EFENDİM.",
["nmh_intro_01_08"] = "AMELİYATHANEDE SİGARA İÇEBİLDİĞİMİZ GÜNLERİ HATIRLIYORUM. O LANET ÖNLÜĞÜ BİR GİYDİM Mİ, SİZE SÖYLEYEYİM...",
["nmh_intro_01_09"] = "İSTEDİĞİM YERDE SİGARA İÇERİM!",
["nmh_intro_01_10"] = "BAIN, BURADAKİ GEVEZE KONUŞUP DURDUĞU İÇİN PEK DUYAMADIM AMA HADİ GİDELİM.",
["nmh_intro_02_01"] = "BEYLER, HAVADA BİR ŞEYLER VAR SANKİ... PARA!",
["nmh_intro_02_02"] = "SESİN KESİLİYOR... BENİ DUYABİLİYOR MUSUN?",
["nmh_intro_02_03"] = "EVET, EVET, EVET... PLANI UYGULAYIN!",
["nmh_intro_02_04"] = "TAMAM!",
["nmh_intro_02_05"] = "GİDELİM! GİDELİM! HEPİMİZ ASANSÖRE SIĞARIZ.",
["nmh_intro_02_06"] = "SEN! KIPIRDA!",
["nmh_intro_02_07"] = "YOKSA NE?! SİZ İKİNİZ YAŞLI BİR ADAMI BİR SONRAKİNİ BEKLEMEYE Mİ ZORLAYACAKSINIZ?",
["nmh_intro_02_08"] = "BAIN, HİÇBİR ŞEY DUYMADIM... ASANSÖRDEKİ BU HERİF SÜREKLİ İŞİ BOZUYOR! NEYSE, YAPALIM!",
["nmh_intro_03_01"] = "BEYLER, HAVADA BİR ŞEYLER VAR SANKİ... PARA!",
["nmh_intro_03_02"] = "SESİN KESİLİYOR... BENİ DUYABİLİYOR MUSUN?",
["nmh_intro_03_03"] = "EVET, EVET, EVET... PLANI UYGULAYIN!",
["nmh_intro_03_04"] = "TAMAM!",
["nmh_intro_03_05"] = "HEY, KAPIYI TUTUN!",
["nmh_intro_03_06"] = "SİZ İKİNİZ NE DİYE BÖYLE GİYİNDİNİZ LAN, CADILAR BAYRAMI MI?",
["nmh_intro_03_07"] = "HEY BAIN, HARİKA BRİFİNG... HİÇBİR BOK DUYMADIM! NEYSE, DURUMA GÖRE OYNAYALIM.",
["nmh_intro_04_01"] = "BEYLER, HAVADA BİR ŞEYLER VAR SANKİ... PARA!",
["nmh_intro_04_02"] = "SESİN KESİLİYOR... BENİ DUYABİLİYOR MUSUN?",
["nmh_intro_04_03"] = "EVET, EVET, EVET... PLANI UYGULAYIN!",
["nmh_intro_04_04"] = "TAMAM!",
["nmh_intro_04_05"] = "KAPIYI TUT!",
["nmh_intro_04_06"] = "EVET, BUYUR GEL.",
["nmh_intro_04_07"] = "AH, TEŞEKKÜR EDERİM. SÖYLEMELİYİM Kİ HASTANENİN EN ŞIK GİYİMLİ HEMŞİRELERİ SİZ İKİNİZSİNİZ.",
["nmh_intro_04_08"] = "AH... SENİ MORUK. ÖNCE ONU ÖLDÜRECEĞİM.",
["nmh_intro_05_01"] = "BEYLER, HAVADA BİR ŞEYLER VAR SANKİ... PARA!",
["nmh_intro_05_02"] = "SESİN KESİLİYOR... BENİ DUYABİLİYOR MUSUN?",
["nmh_intro_05_03"] = "EVET, EVET, EVET... PLANI UYGULAYIN!",
["nmh_intro_05_04"] = "TAMAM!",
["nmh_intro_05_05"] = "KAPIYI TUT!",
["nmh_intro_05_06"] = "HAY TANRIM, SİZ İKİNİZ POLİS MİSİNİZ?",
["nmh_intro_05_07"] = "BİR SİGARA YAKACAKTIM. BENİ TUTUKLAMAYACAKSINIZ, DEĞİL Mİ?",
["nmh_intro_05_08"] = "YAHU, BU ADAM DA HİÇ SUSMUYOR. ÖNCE ONU ÖLDÜRECEĞİM.",
["nmh_intro_06_01"] = "DOĞRU KATA MI BASTIN? DOĞRU KATA BAS!",
["nmh_intro_06_02"] = "NEDEN ŞU ANDA BURADA OLMAMAM GEREKİYORMUŞ GİBİ HİSSEDİYORUM?",
["nmh_intro_06_03"] = "SİKTİR ET, BURADASIN YA?",
["nmh_intro_06_04"] = "TAM DA OLMAN GEREKEN YERDESİN DUKE.",
["nmh_intro_06_05"] = "BU İŞTE BİR TERSLİK VAR. BİR... BİR ŞEY...",
["nmh_intro_06_06"] = "UNUTMAYIN MİLLET, BU İŞİN GETİRİSİ ÖNEMLİ.",
["nmh_intro_06_07"] = "TAMAM DOSTUM, NE YAPTIĞINI BİLİYORSUN. SADECE BU BOK SONRA DÖNÜP GÖTÜMÜZÜ ISIRMASIN İSTİYORUM.",
["nmh_intro_08_01"] = "BU BOKU BİR KİTAP İÇİN Mİ YAPIYORUZ LAN?",
["nmh_intro_08_02"] = "GÜZEL VE SAKİN MİLLET. BU ÖNEMLİ.",
["nmh_intro_08_03"] = "ÇOK ÖNEMLİ BİR KİTAP OLSA İYİ OLUR LAN.",
["nmh_intro_08_04"] = "HASTANELERDEN NEFRET EDERİM AMINA KOYAYIM. BİR GÜN BİTKİSEL HAYATA GİRERSEM İŞİMİ BİTİRİN. ",
["nmh_intro_08_05"] = "PEKÂLÂ DALLAMALAR, BUNA HAZIR MISINIZ?",
["nmh_intro_08_06"] = "DOKTOR MCCOY ARANIYOR... DOKTOR MCCOY?",
["npc_tag_poi_01_01"] = "ŞİMDİ, SORUŞTURMA İŞLEMLERİ VE YÖNERGELERİ EL KİTABINIZIN YÜZ OTUZ İKİNCİ SAYFASINI AÇARSANIZ BÖLÜM SIRALAMASININ ÖNCEKİ SÜRÜME GÖRE DEĞİŞTİĞİNİ GÖRECEKSİNİZ. BU TAMAMEN KASITLIDIR. METNİN ÖNCEKİ SÜRÜMLERİNİN GEREKSİZ DERECEDE KARMAŞIK OLDUĞU VE BU YÜZDEN BELİRLİ PASAJLARIN BULUNMASINI GEREKSİZ YERE ZORLAŞTIRDIĞI DEĞERLENDİRİLMİŞTİR. EL KİTABININ AYRINTILARINI VE İLGİLİ YÖNETMELİKLERİ DAHA DERİNLEMESİNE İNCELEMEYE DEVAM EDERKEN YAPILAN DEĞİŞİKLİKLERİN ÇOKLUĞUNU KUŞKUSUZ FARK EDECEKSİNİZ.",
["npc_tag_poi_01_02"] = "PEKİ, ŞU ANDA BU ODADA BULUNAN HERHANGİ BİRİ BANA BİRLEŞİK DEVLETLER'E KARŞI VATANA İHANET EYLEMLERİNE İLİŞKİN BİR ANAYASA HÜKMÜ SÖYLEYEBİLİR Mİ? KİMSE VAR MI? ANAYASA'NIN 3. MADDESİNİN 3. BÖLÜMÜ ŞÖYLE DER: \"BİRLEŞİK DEVLETLER'E İHANET, ANCAK ONLARA KARŞI SAVAŞ AÇMAK VEYA DÜŞMANLARININ TARAFINI TUTUP ONLARA YARDIM VE DESTEK SAĞLAMAKLA GERÇEKLEŞİR. HİÇ KİMSE, AYNI AÇIK EYLEME İLİŞKİN İKİ TANIĞIN İFADESİ VEYA...? ...VEYA...? TAMAMLAMAK İSTEYEN VAR MI? KİMSE?... BUELLER?",
["npc_tag_poi_01_03"] = "EVET, YENİ GÜVENLİK SİSTEMİNİN KAPSAMLI BİÇİMDE TEST EDİLDİĞİNE İNANIYORUM.",
["npc_tag_poi_01_04"] = "GELECEK HAFTANIN GÖREV ÇİZELGESİNDEKİ DEĞİŞİKLİKLERLE İLGİLİ SORULARINIZ İÇİN LÜTFEN 47B-5A FORMUNA BAKIN.",
["npc_tag_poi_01_05"] = "TÜM AJANLAR, HER CUMA, HER VARDİYA DÖNGÜSÜNDE BİR DİLİM TURTA ALMAYA HAK KAZANACAKTIR. KAHVE BEDAVA OLMAYA DEVAM EDECEK AMA FRANSIZ'IN DEDİĞİ GİBİ, ÇAYINIZI KENDİNİZ GETİRECEKSİNİZ.",
["npc_tag_poi_01_06"] = "BUGÜNKÜ GÜNDEMİMİZİN SIRADAKİ MADDESİ, ERKEKLER TUVALETİNE YENİ KAPI MENTEŞELERİ TAKILACAK OLMASI. LÜTFEN GELECEKTE MENTEŞELERE GEREKSİZ YÜK BİNDİRMEKTEN KAÇININ. AJAN JOHNSON'IN KAPILARIN YERE KADAR UZATILMASI YÖNÜNDEKİ DİLEKÇESİ GELECEK BÜTÇE DÖNEMİMİZ İÇİN DEĞERLENDİRİLİYOR.",
