["nx64_reset_skills_msg"] = "BECERİ AĞAÇLARINDAN BİRİNİ VEYA TÜMÜNÜ SIFIRLAMAK ÜZERESİN.$NL;$NL;AĞACI SIFIRLA SEÇENEĞİ, SEÇİLİ BECERİ AĞACINDAKİ BECERİ PUANLARINI KALDIRIP SANA İADE EDER.$NL;$NL;TÜM AĞAÇLARI SIFIRLA SEÇENEĞİ, TÜM BECERİ AĞAÇLARINDAKİ BECERİ PUANLARINI KALDIRIP SANA İADE EDER.",
