["oading_gameplay_117"] = "SUSTURUCULU TESTERELER BİLE BİRAZ SES ÇIKARIR. YAKINDAKİ İNSANLARA DİKKAT ET.",
["old_hoxton_desc"] = "UYRUĞU: İNGİLİZ$NL;YAŞI: 32$NL;$NL;HOXTON ADINI, ESKİ ÇETESİYLE BİRLİKTE LONDRA’NIN EAST END BÖLGESİNDE YAKALANMASINDAN ALDI. HMYOI’DA CEZASINI ÇEKTİKTEN SONRA YİRMİLİ YAŞLARINDA BİRKAÇ SUÇ ÖRGÜTÜYLE ÇALIŞTI VE SONUNDA PAYDAY GANG EKİBİNE KATILDI. 2011’E KADAR SÜREN BAŞARILI BÜYÜK SOYGUNLARIN ARDINDAN HOXTON, FBI TARAFINDAN YAKALANIP HAPSE GÖNDERİLDİ.$NL;$NL;2014’TE PAYDAY GANG KAÇMASINA YARDIM ETTİ. ÇIKTIĞINDAN BERİ BİRİNİN ONA KOMPLO KURDUĞUNA İNANIYOR.",
["old_hoxton_desc_codex"] = "HOXTON, İLK PAYDAY EKİBİNİN ÜYELERİNDEN BİRİDİR. 2012’YE KADAR SÜREN BAŞARILI BÜYÜK SOYGUNLARIN ARDINDAN HOXTON, FBI TARAFINDAN YAKALANIP HAPSE GÖNDERİLDİ. 2014’TE PAYDAY GANG KAÇMASINA YARDIM ETTİ. ÇIKTIĞINDAN BERİ BİRİNİN ONA TUZAK KURDUĞUNDAN EMİN.",
