["ph1_trade7_loud_02"] = "HASSİKTİR! ANLAŞMA BU DEĞİLDİ! BİZ GİDİYORUZ!",
["pil_pal_01_01"] = "O İNSANLAR KİM?!",
["pil_pal_01_02"] = "BURADA NE HALT EDİYORSUNUZ?",
["pil_pal_01_03"] = "BURADA NE YAPIYORSUNUZ?!",
["pil_pal_01_04"] = "ACELE EDİP O SIZINTIYI DÜZELTSENİZ İYİ OLUR.",
["pil_pal_01_05"] = "KİM O İNSANLAR LAN?",
["pil_pal_01_06"] = "ACELE EDİP O SIZINTIYI DÜZELTSENİZ İYİ OLUR.",
["pil_pal_01_07"] = "ACELE EDİP O SIZINTIYI TAMİR ETSENİZ İYİ OLUR.",
["pil_pal_02_01"] = "BİRİ BANA İÇKİ GETİRSİN.",
["pil_pal_02_02"] = "DAHA SERT BİR ŞEYİN VAR MI DOSTUM?",
["pil_pal_03_01"] = "*MIRILDANIR*",
["pil_pal_04_01"] = "BU YAPTIĞINIZ YANINIZA KALMAYACAK!",
["pil_pal_04_02"] = "BURASI ÖZEL MÜLK, ÇIKIN GİDİN!",
["pil_pal_04_03"] = "BURASI ÖZEL MÜLK!",
["pil_pal_04_04"] = "SİZİ YAKALARSAM BU YAPTIĞINIZ YANINIZA KALMAZ!",
["pil_pal_04_05"] = "BORİS SİZİ YAKALAYACAK, ASLA PAÇAYI KURTARAMAZSINIZ, DUYDUNUZ MU?!",
["pil_pal_04_06"] = "BU YAPTIĞIN YANINA KALMAYACAK OROSPU ÇOCUĞU!",
["plc_cs1_01_01"] = "BEN 8. KARAKOL'DAN YÜZBAŞI ROGERS. GENSEC, ŞÜPHELİ BİR FAALİYETLE İLGİLİ ENDİŞELERİNİ BİLDİRDİ. TEDBİR AMAÇLI MEMUR YOLLUYORUM.",
["plc_cs1_01_02"] = "BEN MPDC'DEN YÜZBAŞI ROGERS. GENSEC'TEN TELEFON ALDIK. ORADA OLANLARLA İLGİLİ BAZI ENDİŞELERİ VARMIŞ. HER ŞEYİN YOLUNDA OLDUĞUNDAN EMİN OLMAK İÇİN ÜNİFORMALI MEMURLAR GÖNDERİYORUM.",
["plc_cs1_01_03"] = "YÜZBAŞI ROGERS KONUŞUYOR. ÖZEL GÜVENLİK ŞİRKETİNİZDEN BİR TELEFON ALDIK. BAZI ENDİŞELERİ VARMIŞ. BU YÜZDEN HERKESİN GÜVENLİĞİ İÇİN BULUNDUĞUNUZ YERE BİRKAÇ MEMUR YÖNLENDİRİYORUM.",
["plc_cs1_02_01"] = "YİNE YÜZBAŞI ROGERS. BAKIN, GÖNDERDİĞİM MEMURLAR CEVAP VERMİYOR. SORUN MU VAR?",
["plc_cs1_03_01"] = "EVLAT, ALTMIŞA KADAR SAYANA DEK ONLARI BU TELEFONA GETİRECEKSİN. YOKSA ELİMDEKİ HER MEMURU GÖNDERİP GÖTÜNÜ CTF'YE SÜRÜKLETİRİM.",
["plc_cs1_04_01"] = "EVLAT, ONLARI BU TELEFONA GETİRMEN İÇİN TAM İKİ DAKİKAN VAR. YOKSA MÜSAİT BÜTÜN LANET ÜNİFORMALILARI HEMEN GÖNDERİYORUM.",
["plc_cs1_05_01"] = "EVLAT, ONLARI TELEFONA GETİRMEK İÇİN SANA ÜÇ DAKİKA VERİYORUM. YOKSA POLİSİ OYALAMAKTAN İŞLEM YAPARIM.",
["pln_al1_01_01"] = "GÜRÜLTÜLÜ YA DA SESSİZ, SİZE KALMIŞ. AMA GİZLİCE YAPARSAK KALABALIĞA KARIŞIP ONLARLA KAÇABİLİRİZ. RAHAT RAHAT. ",
["pln_al1_01_02"] = "TAMAM MİLLET, HER ŞEY PLANA GÖRE GİDERSE FARK EDİLMEDEN ÇIKABİLİRİZ. KALABALIĞA KARIŞIP SIVIŞIN.",
["pln_al1_01_03"] = "BUNU SESSİZCE ATLATIRSANIZ KALABALIĞA KARIŞIP KAYBOLABİLİRSİNİZ.",
["pln_al1_02_01"] = "ARENADA KIRMIZI X İŞARETLİ MALZEME DOLAPLARINI ARAYIN. C4 ORALARDA.",
["pln_al1_02_02"] = "ARENADA KIRMIZI X İŞARETLİ DOLAPLARI ARAYIN. İÇERİDEKİ ADAM C4'Ü ORALARA SAKLADI",
["pln_al1_02_03"] = "C4'ÜMÜZ KIRMIZI X İŞARETLİ MALZEME DOLAPLARINA SAKLANDI. BULUN.",
["pln_al1_03_01"] = "İŞTE BU! ŞİMDİ C4'Ü YERALTI GARAJINA YERLEŞTİRİN. İÇERİDEKİ ADAMIMIZ, KASA DAİRESİ'NİN ALTINDAKİ TAVANI İŞARETLEDİ. C4'Ü ORAYA KOYACAKSINIZ.",
["pln_al1_03_02"] = "HARİKA, ŞİMDİ GARAJA İNİN. İÇERİDEKİ ADAMIMIZ C4 YERLEŞTİRMENİZ GEREKEN YERLERİ İŞARETLEDİ.",
["pln_al1_03_03"] = "TAMAM, C4'ÜN HEPSİ BU. GARAJA İNİN. İÇERİDEKİ ADAMIMIZ PATLATMANIZ GEREKEN YERİ İŞARETLEDİ.",
