["pln_al1_50_02"] = "MASKELERİ ÇIKARMAYA HAZIR OLDUĞUNUZDA İÇERİDEKİ ADAMA HABER VERİN. GANİMETİ O TAŞIYACAK, O YÜZDEN ALMAK İSTEDİĞİNİZ HER ŞEYİ HAVALANDIRMAYA ATTIĞINIZDAN EMİN OLUN.",
["pln_al1_50_03"] = "NEREDEYSE BİTTİ, MİLLET. MASKELERİ ÇIKARIP GİTMEYE HAZIR OLDUĞUNUZDA İNTERKOMA CEVAP VERİN YETER. ÖNCE GÖTÜRMEK İSTEDİKLERİNİZİ GÜVENE ALIN!",
["pln_al1_51_01"] = "MİLLET. KAÇMAYA HAZIR OLDUĞUNUZDA O DİYAFONA CEVAP VERİN. GERİDE BIRAKTIĞINIZ HER ŞEY ORADA KALIR.",
["pln_al1_51_02"] = "ADAMIMIZ GÖSTERİYİ BİTİRMEK İÇİN BEKLİYOR. HAZIR OLDUĞUNUZDA DAHİLİ TELEFONA CEVAP VERİN YETER. ALMAK İSTEDİĞİNİZ BÜTÜN GANİMETİN GÜVENCEYE ALINDIĞINDAN EMİN OLUN.",
["pln_al1_51_03"] = "BURADAN ÇIKMAYA HAZIR OLDUĞUNUZDA İNTERKOMA CEVAP VERİN. ADAMIMIZ GANİMETİ ÇIKARACAK. GÖTÜRMEK İSTEDİKLERİNİZİ GÜVENE ALDIĞINIZDAN EMİN OLUN.",
