["pln_al1_55_01"] = "GÜRÜLTÜLÜYDÜ VE DİKKAT ÇEKTİ. MÜKEMMEL İŞ. AMA GENSEC İÇİN KÖTÜ OLDU. YENİ TASARIMLARI ŞAKA GİBİ.",
["pln_al1_55_02"] = "BAŞARDINIZ. BİR TON PARA ALDINIZ VE BÜTÜN DİKKATLERİ ÜSTÜNÜZE ÇEKTİNİZ. GENSEC DE HERKESİN ÖNÜNDE REZİL OLMAYI HAK EDİYOR.",
["pln_al1_55_03"] = "BUGÜN GENSEC'E ÇOK ÇEKTİRDİNİZ. GÜRÜLTÜLÜ YAPTIĞINIZ İÇİN DÜNYA DA ÖĞRENDİ. BU İYİ.",
["pln_al1_56_01"] = "DAHA FAZLA C4. AZ KALDI. ARAMAYA DEVAM EDİN.",
["pln_al1_56_02"] = "DAHA FAZLA C4. TAM YETERLİ DEĞİL. ARAMAYA DEVAM EDİN.",
["pln_al1_56_03"] = "TAMAM. DAHA FAZLA C4. GEREKENİ NEREDEYSE TOPLADIK. ARAMAYA DEVAM EDİN.",
["pln_al1_56_04"] = "DAHA FAZLA C4. AZ KALDI. ARAMAYA DEVAM EDİN.",
["pln_al1_56_05"] = "İYİ BULDUNUZ. AMA DAHA FAZLA C4 GEREKECEK. ARAMAYA DEVAM EDİN.",
["pln_al1_brf_01_01"] = "ARENADA GENSEC'İN YÖNETTİĞİ KOCAMAN BİR GÜVENLİK KATI VAR. BİR KISMI ŞİRKET VIP'LARINA SERGİ AMA HÂLÂ ÇALIŞAN BİR KASA DAİRESİ. BU GECE VURACAĞIZ. İÇERİDE ADAMIMIZ VAR. ARENANIN ÇEŞİTLİ YERLERİNE C4 SAKLADI. TOPLAYIN, KASA DAİRESİNİ ALTTAN PATLATIN VE O TATLI KİRLİ PARAYI ÇIKARIN. BU İŞTE BEKLENMEDİK YARDIM ALACAĞIZ. ALESSO DİYE BİR DJ DUYDUNUZ MU? BU GECE DOĞU YAKASI TURNESİNİN SON GECESİ, ÇATIYI UÇURACAĞINA SÖZ VERDİ. DAHA İYİ NE KILIF İSTERDİNİZ?",
["pln_al1_cbf_01_01"] = "GENSEC'İN YEPYENİ BİR KASA DAİRESİ VAR: YATIRIM KASASI. KIRILAMAZ DİYORLAR, ARENADA SERGİLİYORLAR. KAPISI YENİ BİLEŞİKLERİ VİVİNİTE'TEN YAPILMIŞ. AMA HER ŞEYİN ZAYIF NOKTASI VARDIR. BİRAZ C4 VE YENİ BİR DAİRESEL KESİCİYLE PARALARINI TAM ALTLARINDAN ÇALABİLİRİZ.",
["pln_al1_cnc_01_01"] = "GENSEC, KIRILAMAZ KASA DAİRESİ'Nİ ARENADA SERGİLİYOR. ALESSO KONSERİNİ KULLANIP YANILDIKLARINI KANITLAYACAĞIZ.",
["pln_al1_cnc_01_02"] = "ALESSO, GENSEC ARENASINDA ÇALIYOR. ONLARA PAYDAY GANG'İ HİÇBİR ŞEYİN DURDURAMAYACAĞINI ÖĞRETECEĞİZ.",
["pln_al1_cnc_01_03"] = "ALESSO BU GECE ŞEHİRDE. KONSERİNİ GENSEC'İ ARENASINDA SOYMAK İÇİN ÖRTÜ OLARAK KULLANACAĞIZ.",
["pln_al1_intro_01_01"] = "ALESSO'NUN GÖSTERİSİNİN BİLETLERİ $400'A EL DEĞİŞTİRİYORDU! BU GECE NE OLURSA OLSUN BİRİ ZENGİN OLACAK.",
["pln_al1_intro_01_02"] = "İŞTE GENSEC ARENASI. BU ALESSO KONSERİ, BURANIN GÖRDÜĞÜ EN BÜYÜK GÖSTERİ. TARİHE GEÇMESİNİ SAĞLAYALIM.",
["pln_al1_intro_01_03"] = "AH! BURADA GÜZEL KONSERLER OLDU. ALESSO'NUNKİ ŞİMDİYE KADARKİLERİN EN BÜYÜĞÜ.",
["pln_art_end_01_01"] = "HARİKA İŞ! BUNLARI HEMEN MAL ALICILARIMIZ ÜZERİNDEN SATMAYA BAŞLAYACAĞIM. KAZANCINIZIN TADINI ÇIKARIN MİLLET!",
["pln_art_end_01_02"] = "USTALIKLA YAPTINIZ! KOLEKSİYONCULAR BU ŞEYLERE BÜYÜK PARALAR ÖDER. HARİKA İŞ ÇIKARDINIZ EKİP!",
["pln_art_intro_01_01"] = "UMARIM GEÇEN SEFERKİ KADAR BAŞARILI OLURUZ. BAŞLAYIN EKİP.",
["pln_art_intro_01_02"] = "BİR KERE YAPTIK, YİNE YAPARIZ. İÇERİ GİRİP O SANAT ESERLERİNİ AŞIRIN PALYAÇOLAR.",
["pln_as1_01_01"] = "TANRIM, ŞURAYA BAKIN!",
["pln_as1_01_02"] = "TANRIM, HABERLERDE KÖTÜ GÖRÜNÜYORDU AMA...",
["pln_as1_01_03"] = "MELEKLER ŞEHRİ. DEPREM BİRKAÇ MELEK DAHA YARATMIŞ GİBİ...",
["pln_as1_02_01"] = "VLAD HATTA.",
["pln_as1_02_02"] = "VLAD BU İŞTE SİZİNLE KONUŞMAYI ÇOK İSTİYOR.",
["pln_as1_02_03"] = "VLAD BU KASALARA EPEY SİNİRLENMİŞ. SİZİNLE KONUŞMAK İSTİYOR.",
["pln_as1_03_01"] = "DUYDUNUZ ONU. KAMYONLAR BURALARDA BİR YERDE.",
["pln_as1_03_02"] = "TAMAM, KAMYONLAR BU OTOYOLDA BİR YERDE.",
["pln_as1_03_03"] = "ADAMI DUYDUNUZ. O KAMYONLARI BULALIM.",
["pln_as1_04_01"] = "HADİ, İKİNCİ KAMYONU BULUN.",
["pln_as1_04_02"] = "İKİNCİ KAMYON İLKİNDEN ÇOK UZAKTA OLAMAZ. BULUN.",
["pln_as1_04_03"] = "İKİNCİ KAMYON NEREDE? BURALARDA BİR YERDE OLMALI.",
["pln_as1_05_01"] = "GÜZEL. ŞİMDİ ŞU KAMYONLARI AÇIN. VLAD NE TAŞIYORMUŞ BAKALIM.",
["pln_as1_05_02"] = "ŞİMDİ O KAMYONLARI AÇIN. İÇLERİNE GİRELİM.",
["pln_as1_05_03"] = "GÜZEL. ŞİMDİ KAMYONLARI AÇIP O DELİ IVAN'IN NE GÖNDERDİĞİNE BAKABİLİRİZ.",
["pln_as1_06_01"] = "EH, EN AZINDAN BU SEFER NÜKLEER BOMBA DEĞİL.",
["pln_as1_06_02"] = "VLAD BİZİ ONLAR İÇİN BU CEHENNEM ÇUKURUNA GÖNDERDİYSE ÖNEMLİ OLDUKLARINA EMİN OLABİLİRSİNİZ.",
["pln_as1_06_03"] = "TAÇLAR, NÜKLEER SAVAŞ BAŞLIKLARI VE KASALAR. VLAD İÇİN SIRADAN BİR İŞ DAHA.",
["pln_as1_07_01"] = "HOLLYWOOD İHTİŞAMI DEĞİL, BİLİYORUM AMA BİRİ O KASALARI ÇIKARSA İYİ OLUR.",
["pln_as1_07_02"] = "HADİ EKİP. KASALARI ÇIKARIN. VERİN KUVVETİ.",
["pln_as1_07_03"] = "KASALARI ÇIKARIN, EKİP. EVET, BİLİYORUM, SICAKLIK YÜZ DERECENİN ÜSTÜNDE AMA İŞE KOYULUN.",
["pln_as1_08_01"] = "ORADAN GEÇMEMİZ GEREKECEK. SİZE C4 GÖNDERİYORUM.",
["pln_as1_08_02"] = "BİRAZ C4 ONU HALLEDER. ŞİMDİ GÖNDERİYORUM. BEKLEYİN.",
["pln_as1_08_03"] = "PİLOTA SİZİ ORADAN GEÇİRMEK İÇİN C4'LE DÖNMESİNİ SÖYLÜYORUM. DAYANIN.",
["pln_as1_09_01"] = "TAMAM, C4 YERDE. ALIN!",
["pln_as1_09_02"] = "İŞTE C4, EKİP. BİRİNİZ ALSIN.",
["pln_as1_09_03"] = "C4'Ü ALIN EKİP. İNŞAAT ALANININ DUVARINI HALLEDER.",
["pln_as1_10_01"] = "PEKÂLÂ. ŞİMDİ C4'Ü ORAYA YAPIŞTIRIN. PATLATARAK ÇIKIYORUZ.",
["pln_as1_10_02"] = "HARİKA. ŞİMDİ GİDİP O ENGELİ PATLATIN. ÇIKIŞ YOLUNUZ BU.",
["pln_as1_10_03"] = "ŞİMDİ ŞURADAKİ ALANA GİDEN ENGELİ HALLEDİN. O TARAFTAN ÇIKIYORSUNUZ.",
["pln_as1_11_01"] = "TAMAM. KASALAR YÜKLENDİ. ALANDAN ÇIKIYORUZ. KAMYONUN ORADA OLDUĞUNDAN EMİN OLUN!",
["pln_as1_11_02"] = "KASALAR TAMAM. ŞİMDİ AVLUDAKİ O KAMYONU İSTİYORUM. BU İŞİ BİTİRİYORUZ!",
["pln_as1_11_03"] = "HARİKA. BÜTÜN KASALAR YÜKLENDİ. ŞİMDİ KAMYONU ALANA GERİ GETİRİN EKİP, ACELE!",
["pln_as1_12_01"] = "EKİP, İNŞAAT ALANINA GİRİN! ÇABUK!",
["pln_as1_12_02"] = "MİLLET, İNŞAAT ALANINA GELMENİZ GEREKİYOR. TEK ÇIKIŞ YOLU BU.",
["pln_as1_12_03"] = "İNŞAAT ALANINA GİDİN! ACELE EDİN!",
["pln_as1_13_01"] = "MİLLET, PİLOT TUR ATIYOR! İŞARET FİŞEĞİNİ BIRAKIN!",
["pln_as1_13_02"] = "EKİP, PİLOT SİZİ GÖREMİYOR. O İŞARET FİŞEĞİNİ YAKMALISINIZ.",
["pln_as1_13_03"] = "İŞARET FİŞEĞİNİ YAKIN, EKİP. ONSUZ PİLOT HİÇBİR ŞEY GÖREMİYOR.",
["pln_as1_14_01"] = "KASALARI YÜKLEYİP BOŞALTACAK VAKTİMİZ YOK. HELİKOPTER KAMYONU TAŞIYACAK. KALDIRABİLİR. SİZİN SADECE BİNMENİZ GEREKİYOR!",
["pln_as1_14_02"] = "HELİKOPTERE YÜKLEME YAPACAK VAKİT YOK. KAMYONU KAPIP GÖTÜRECEK, O YÜZDEN İÇİNDE OLMANIZ GEREK!",
["pln_as1_14_03"] = "KAMYONUN İÇİNE GİRİN! HELİKOPTER BÜTÜN LANET KAMYONU HAVAYA KALDIRACAK!",
["pln_as1_15_01"] = "VE... HAVALANDI! MUHTEŞEM İŞ ÇIKARDINIZ EKİP!",
["pln_as1_15_02"] = "UMARIM O KABLO DAYANIR. DUR, KASALARIN AĞIRLIĞINI EKLEMİŞ MİYDİM... ?",
["pln_as1_15_03"] = "MELEKLER GİBİ UÇUYORSUNUZ... O HARAP ŞEHRİN ÜZERİNDE. HARİKA İŞ!",
["pln_as1_16_01"] = "TANRIM, LA MAHVOLMUŞ. HER YER MOLOZ.",
["pln_as1_16_02"] = "DOSTUM, ŞEHİR HARABEYE DÖNDÜ. YOLLAR, BİNALAR... HER ŞEY MAHVOLMUŞ.",
["pln_as1_16_03"] = "MİLLET, ENKAZ İNANILMAZ. MOLOZLAR HER ŞEYİ KAPATMIŞ.",
["pln_as1_17_01"] = "KAMYONLAR BURALARDA BİR YERDE. VLAD'IN ADAMLARI DA OLACAK, ATEŞİNİZE DİKKAT EDİN.",
["pln_as1_17_02"] = "KAMYONLAR YAKINDA BİR YERDE. VLAD'IN KURYELERİNİ DE KOLLAYIN. VURMAYIN ONLARI!",
["pln_as1_17_03"] = "O KAMYONLARI BULUN! VLAD'IN ADAMLARINDAN SAĞ KALAN VARSA VURMAYIN.",
["pln_as1_18_01"] = "ONLARI SIRTINIZDA TAŞIMANIZ İMKÂNSIZ. BEKLEYİN, SİZE BİR NAKLİYE ARACI BULACAĞIM.",
["pln_as1_18_02"] = "ONLARI TAŞIYARAK ASLA ÇIKARAMAZSINIZ. BİR TAŞIMA ARACI VE ÇIKIŞ YOLU LAZIM. BİR DAKİKA VERİN, BİR ŞEY BULURUM.",
["pln_as1_18_03"] = "KASALAR TAŞINAMAYACAK KADAR AĞIR, KAMYONLAR DA MAHVOLDU. BAŞKA BİR TAŞIMA ARACI GEREKECEK. BİR ŞEY BULURUM, DAYANIN.",
["pln_as1_19_01"] = "LANET OLSUN, ORTALIK HARAP OLMUŞ. HÂLÂ ARIYORUM. DAYANIN.",
["pln_as1_19_02"] = "ŞEHİR HARABE OLMASA DAHA KOLAY OLURDU. DAYANIN YETER.",
["pln_as1_19_03"] = "HÂLÂ BAKIYORUM. KAHRETSİN, LA'NIN HER YERİ DUMAN. ONLARI OYALAYIN.",
["pln_as1_20_01"] = "BULDUM! KAMYONU OLAN BİR İNŞAAT ALANI. EN İYİ ÇIKIŞ GİBİ AMA O DUVARI PATLATMAK İÇİN C4 GEREKECEK. ŞİMDİ GÖNDERİYORUM. KASALARA DİKKAT!",
["pln_as1_20_02"] = "EKİP, NEHRİN KARŞISINDA BİR İNŞAAT ALANI VAR! PARK ETMİŞ BİR KAMYON VAR. BENCE EN İYİ ÇIKIŞ YOLUMUZ O. ŞİMDİ SİZE C4 GÖNDERİYORUM. KASALARI KORUYUN!",
["pln_as1_20_03"] = "EKİP, ÇIKMAK İÇİN EN İYİ YOLUNUZ KARŞIDAKİ ŞANTİYE GİBİ GÖRÜNÜYOR. BİR KAMYONLARI VAR. DUVARI YIKMANIZ İÇİN ŞİMDİ BİRAZ C4 YOLLUYORUM.",
["pln_as1_21_01"] = "O KAMYON MÜKEMMEL GÖRÜNÜYOR. ŞİMDİ KASALARI YÜKLEYİN. HEPSİNİ.",
["pln_as1_21_02"] = "BU YETER! ÇIKARMAYA BAŞLAYIP KAMYONA YÜKLEYİN!",
["pln_as1_21_03"] = "KASALARI O KAMYONA YÜKLEYİN!",
["pln_as1_brf_01_01"] = "HEY, HABERLERİ GÖRDÜNÜZ MÜ?! BATI YAKASI'NDA BÜYÜK DEPREM OLDU! LA DARMADAĞIN. SİZ DE ORAYA GİDİYORSUNUZ. GÖRÜNÜŞE GÖRE VLAD, SEATTLE'DAN D.C.'YE YÜK TAŞIMAK İÇİN BÜYÜK BİR ANLAŞMA YAPMIŞ. TUTTUĞU NAKLİYECİLER DEPREM OLUNCA LA'DEYMİŞ. HERHÂLDE LONG BEACH'TEN GÖNDERECEKLERDİ. VLAD YÜKÜNÜN GÜVENE ALINMASINI İSTİYOR. BUNDA PLANLAMAYA VAKİT YOK. LA HARAP, YOLLAR BOZUK, SİZİ HELİKOPTERLE BIRAKACAĞIZ.",
["pln_at1_brf_01_01"] = "MCCARTY VE JAMES'İN KÖŞESİNDE GENSEC KAMYONLARINI YOLDAN ÇIKARMAYA HAZIR BİR KESKİN NİŞANCIMIZ VAR. TİME OUT'TAKİ HİPSTERLAR LATTE MACCHİATO'LARINA SIÇACAK KESİN. KAMYONLARA GİRMEMİZ, SONRA İÇERİDEKİ SAĞLAM KASALARI AÇMAMIZ GEREKİYOR. NE TAŞIYORLARSA ALIN VE ÇIKIN.",
["pln_at1_brf_02_01"] = "ŞEHİR MERKEZİNDE BİR ÜST GEÇİT, STRATEJİK NOKTALARA YERLEŞTİRİLMİŞ BEŞ LİBRE C-4 VE KUSURSUZ ZAMANLAMAYLA GENSEC KAMYON KONVOYUNU YOLDA BIRAKACAĞIZ. HÂLÂ SERSEMLEMİŞKEN SERT VURUN. KAMYONLARA VE KASALARA GİRİN, GÜZELLİKLERİ KAÇIŞ ŞOFÖRÜNE GÖTÜRÜN.",
["pln_at1_brf_03_01"] = "MIKNATISLI BİR VİNÇLE GENSEC KONVOYUNUN YOLUNA KÜÇÜK BİR HEDİYE BIRAKIYORUZ: İÇİ PROFESYONEL BELALILARLA DOLU ÇELİK BİR KONTEYNER. KAMYONLARI VURUN VE GANİMETİ KAÇIŞ ARACINA GÖTÜRÜN. BU RIHTIMIN KÖKLÜ BİR SOYGUN GEÇMİŞİ VAR BEYLER; ONU GURURLANDIRIN.",
["pln_at1_brf_04_01"] = "SHERPİNG MEMORİAL PARK'IN ÖĞLE KALABALIĞI GENELDE SIÇAN BİR GÜVERCİNDEN DAHA HEYECANLI BİR ŞEY GÖRMEZ. ONLARA GÜZEL BİR GÖSTERİ YAPIN BEYLER. GENSEC KAMYONLARINI VE İÇLERİNDEKİ SAĞLAM KASALARI HALLETMENİZ GEREKİYOR.",
["pln_at1_brf_05_01"] = "BARİKAT KURMAK İÇİN ÇALINTI BİR AMBULANSIMIZ HAZIR, BİR GENSEC KONVOYU DA DULLES'TAN YOLA ÇIKTI. ESKİ BİR NUMARA AMA KLASİK. KAMYONLARDA NE VARSA KAÇIŞ ŞOFÖRÜNÜZE GÖTÜRÜN. BURADA DÜŞMAN BÖLGESİNİN GÖBEĞİNDEYİZ, BEYLER. D.C.'NİN GÖZDE POLİSLERİNDEN HIZLI BİR MÜDAHALE BEKLEYİN.",
["pln_at1_cbf_01_01"] = "EMİNİM DAHA ÖNCE GENSEC'LE KAPIŞMIŞSINIZDIR. BROŞÜRLERİNE İNANIRSANIZ DOĞU YAKASI'NIN BİR NUMARALI GÜVENLİK HİZMETİ SAĞLAYICISILAR. AMA REKLAMI BİR YANA BIRAKIRSAK BU ADAMLAR CİDDİYE ALINMALI. BUGÜN ONLARI VURUYORUZ.",
["pln_at1_cbf_01_02"] = "GENSEC DOĞU YAKASI'NDA BÜYÜK BİR GÜVENLİK ŞİRKETİ. BANKALARLA SİYASETÇİLER ARASINDA İTİBARLARI ÇOK İYİ AMA BUGÜN BUNA NE YAPABİLECEĞİMİZE BAKACAĞIZ. ŞEHRE GELEN BİR KONVOY HAKKINDA TÜYO ALDIM. PEŞİNE DÜŞÜYORUZ.",
["pln_at1_cbf_01_03"] = "GENSEC'İN KARADAN GİDEN ZIRHLI KONVOYLARINDA ATEŞ GÜCÜ VE KAS GÜCÜ SAĞLAYAN BİR SÜRÜ ESKİ ASKER ÇALIŞIR. KÜÇÜK JIMMY'NİN EN SEVDİĞİ BEYZBOL KARTINDAN KRALİYET MÜCEVHERLERİNE KADAR HER ŞEYİ TAŞIRLAR. D.C.'YE GİDEN BİR KONVOY HAKKINDA BİLGİ ALDIK. BAKALIM NE ALABİLECEĞİZ.",
["pln_at1_cnc_01_01"] = "BANLİYÖLERDE İLERLEYEN GENSEC KAMYONLARI VAR. GİDİP VURUN.",
["pln_at1_cnc_02_01"] = "ZIRHLI BİR NAKİL ARACI ŞEHİR MERKEZİNDE PLAN DIŞI DURACAK.",
["pln_at1_cnc_03_01"] = "RIHTIMDA YÜK İNDİRECEK GENSEC KAMYONLARININ ÖNÜNÜ KESİYORUZ.",
["pln_at1_cnc_04_01"] = "PARKTA PİKNİK İÇİN GÜZEL GÜN. SİLAHLI SOYGUN İÇİN DE. ",
["pln_at1_cnc_05_01"] = "ALT GEÇİT KONVOYUN SAVUNMASIZ NOKTASI. SERT VURUN.",
["pln_at1_cro_01_01"] = "O KESKİN NİŞANCIYA GÜVENEBİLECEĞİMİZİ BİLİYORDUM! İŞİNİ YAPIYOR. VAKİT KAYBETMEYİN, O NAKİL ARACINA GİRİŞİN!",
["pln_at1_cro_02_01"] = "NE NİŞANCI AMA! FENA İNDİRDİ! ŞİMDİ BİZ ÜSTÜMÜZE DÜŞENİ YAPALIM. GANİMETİMİZİ ALALIM!",
["pln_at1_cro_03_01"] = "OLAĞANÜSTÜ NİŞANCILIK. ÜÇ KAMYON VURULDU. HAZIRLAR MİLLET, ÇIKIN ORAYA.",
["pln_at1_cro_04_01"] = "BÖYLE ATIŞ GÖRMEDİM. DÖRT ATIŞTA DÖRT ZIRHLI ARAÇ DEVRE DIŞI. BU FIRSATI İYİ DEĞERLENDİRİN.",
["pln_at1_dow_01_01"] = "EH, ARTIK DÖNÜŞ YOK! MÜTHİŞ PATLAMAYDI! O KAMYONA GİRİP İŞİN SİZE DÜŞEN KISMINI YAPIN!",
["pln_at1_dow_02_01"] = "PATLAYICI UZMANIMIZ İŞİNİ YAPTI. İKİ ZIRHLI ARAÇ DURDU. İŞE KOYULUN!",
["pln_at1_dow_03_01"] = "VAY BE! ÜÇ KAMYON KENARA ÇEKTİ. EKİPLERİ SOKAKTA. SERT VURUN!",
["pln_at1_dow_04_01"] = "BUM! DAHA İYİ OLAMAZDI. DÖRT KAMYON DA DURDU, İLGİNİZİ BEKLİYOR. GİRİŞİN, EKİP!",
["pln_at1_end_01_01"] = "HAHA! BAŞARDINIZ! BU MÜCEVHERLER BİRKAÇ KURUŞ EDER, DEĞİL Mİ?",
["pln_at1_end_01_02"] = "HARİKA İŞ BEYLER!",
["pln_at1_end_01b_01"] = "HARİKA İŞ. BAĞLANTILARIMA PARLAK ŞEYLERİ SATTIRACAĞIM. O PLAN HAKKINDA DA NE ÖĞRENEBİLİRİM BAKACAĞIM. HABER BEKLEYİN.",
["pln_at1_end_02_01"] = "AMMA ÇOK NAKİT! İYİ İŞ!",
["pln_at1_end_02_02"] = "İYİ İŞ BEYLER! ALIN TERİYLE KAZANILMIŞ PARA!",
["pln_at1_end_02b_01"] = "MÜKEMMEL İŞ. SİZ O PARANIN BİRAZINI HARCAYIP SAVURUN. BEN DE BU PLANDA NELER BULABİLECEĞİME BAKAYIM.",
["pln_at1_end_03_01"] = "TATLI MI TATLI ALTIN! HERKES HARİKA İŞ ÇIKARDI!",
["pln_at1_end_03_02"] = "BİR SERVET EDECEK! HARİKA İŞ!",
["pln_at1_end_03b_01"] = "KÜLÇELERİ ALMAK İSTEYENLERİ ÇOKTAN SIRAYA KOYDUM. BU PLANLA İLGİLİ BULABİLDİĞİM BİLGİLERİ DE ÇIKARACAĞIM.",
["pln_at1_gen_01_01"] = "POLİS YOLDA! HADİ!",
["pln_at1_gen_01_02"] = "HADİ, HADİ, HADİ! POLİSLER HER AN GELEBİLİR!",
["pln_at1_gen_01_03"] = "ACELE EDİN! POLİS ÇOKTAN YOLA ÇIKTI!",
["pln_at1_gen_02_01"] = "ONU AÇMAK İÇİN ELİNİZDE NE VARSA KULLANIN!",
["pln_at1_gen_02_02"] = "ONU AÇIP İÇİNDE NE VARSA ALIN!",
["pln_at1_gen_02_03"] = "AÇIN!",
["pln_at1_gen_04_01"] = "POLİSLERİ MATKAPTAN UZAK TUTUN.",
["pln_at1_gen_04_02"] = "ÇOK UZUN SÜRMEZ, MEVZİNİZİ KORUYUN.",
["pln_at1_gen_04_03"] = "MATKABI SAVUNUN. BİRKAÇ DAKİKAYA DELER GEÇER.",
["pln_at1_gen_05_01"] = "İYİ İŞ. ŞİMDİ ÇANTALARI MİNİBÜSE GÖTÜRÜN DE BURADAN DEFOLUP GİDELİM!",
["pln_at1_gen_05_02"] = "MİNİBÜSE GÖTÜRÜN!",
["pln_at1_gen_05_03"] = "ÇANTALARI MİNİBÜSE GÖTÜRÜN!",
["pln_at1_gen_06_01"] = "O ÇATILARI AVANTAJINIZA KULLANIN!",
["pln_at1_gen_06_02"] = "ŞU ÇATILARDAN BİRİNDEN İYİ BİR KORUMA ATEŞİ SAĞLAYABİLİRSİNİZ.",
["pln_at1_gen_07_01"] = "ELİNİZ DEĞMİŞKEN O DÜKKÂNLARDA PARA EDECEK BİR ŞEY VAR MI BAKIN.",
["pln_at1_gen_07_02"] = "EKSTRA PARA İSTİYORSANIZ MAĞAZALARA BAKIN.",
["pln_at1_gen_08_01"] = "O OFİSLERİ AVANTAJINIZA KULLANIN!",
["pln_at1_gen_08_02"] = "ÇAPRAZ ATEŞE ALIN!",
["pln_at1_gen_09_01"] = "VAY, GANİMETİN BİR KISMI O PATLAMADA GİTTİ. ŞANSIMIZA İÇERİDE DAHA VAR.",
["pln_at1_gen_09_02"] = "YÖNLENDİRİLMİŞ PATLAYICI GANİMETİN BİR KISMINI DA GÖTÜRMÜŞ GALİBA. KALANI ALIN!",
["pln_at1_gen_09_03"] = "VAY, O PATLAMADA BİRAZ GANİMET KAYBETTİK! NEYSE, KAYBEDECEK VAKİT YOK! KALAN KİRALIK KASALARA BAKIN.",
["pln_at1_gen_10_01"] = "VAY! KAMYONDA BULLDOZER VAR! İNDİRİN ONU! BELA BEKLİYORLARMIŞ GALİBA.",
["pln_at1_gen_10_02"] = "DİKKAT! NAKLİYE ARACINDA BULLDOZER VAR!",
["pln_at1_gen_11_01"] = "HARİKA İŞ! MİNİBÜSÜ GÖNDERİYORUM, YAĞMALAMAYA DEVAM!",
["pln_at1_gen_11_02"] = "MİNİBÜSÜ YOLLUYORUM, MALLARI ÇANTALAMAYA DEVAM EDİN!",
["pln_at1_gen_11_03"] = "TAMAM! MİNİBÜS YAKINDA GELİYOR OLMALI!",
["pln_at1_gen_12_01"] = "HARİKA İŞ! TEKNEYİ GÖNDERİYORUM, YAĞMALAMAYA DEVAM EDİN!",
["pln_at1_gen_12_02"] = "TEKNEYİ GÖNDERİYORUM, MALLARI ÇANTALAMAYA DEVAM EDİN!",
["pln_at1_gen_12_03"] = "TAMAM! TEKNE YAKINDA GELMİŞ OLUR!",
["pln_at1_gen_13_01"] = "HARİKA İŞ! HELİKOPTERİ GÖNDERİYORUM, YAĞMALAMAYA DEVAM EDİN!",
["pln_at1_gen_13_02"] = "HELİKOPTERİ GÖNDERİYORUM, MALLARI ÇANTALAMAYA DEVAM EDİN!",
["pln_at1_gen_13_03"] = "TAMAM! HELİKOPTER YAKINDA GELİYOR OLMALI!",
["pln_at1_gen_14_01"] = "AÇILDI! BAKALIM NE VARMIŞ!",
["pln_at1_gen_14_02"] = "AÇILDI! O KİRALIK KASALARI AÇIN!",
["pln_at1_gen_14_03"] = "AÇILDI! KİRALIK KASALARIN İÇİNDEKİLERİ ALIN!",
["pln_at1_gen_15_01"] = "GELDİ, MALLARI İÇERİ ATIN!",
["pln_at1_gen_15_02"] = "TAMAM, GELDİ! GANİMETİ ORAYA TAŞIYIN!",
["pln_at1_gen_16_01"] = "KAMYON AÇILDI. GİRİP KASALARI AÇIN. EN AZ İKİ ÇANTA GANİMET LAZIM.",
["pln_at1_gen_17_01"] = "GİRDİK AMA KİRALIK KASALARI HÂLÂ HALLETMENİZ GEREK. ALINMA NOKTASINA ÜÇ ÇANTA GETİRMENİZ LAZIM. HIZLANIN!",
["pln_at1_gen_18_01"] = "AÇILDI! KİRALIK KASALARI HALLEDİP GANİMETİ ALIN. EN AZ DÖRT ÇANTA LAZIM.",
["pln_at1_gen_19_01"] = "İLK KAMYONU AÇTINIZ. ŞİMDİ KUTULARI AÇIP GANİMETİ ÇANTALAMAYA BAŞLAYIN. BEŞ ÇANTA, O YÜZDEN ACELE EDİN MİLLET!",
["pln_at1_gen_20_01"] = "BAKALIM BURADA NE VARMIŞ? ASKERÎ PLANLAR! BUNU ARAŞTIRAYIM. ",
["pln_at1_gen_20_02"] = "BU İLGİNÇ. GENSEC NAKİL ARACINDA ASKERÎ PLANLAR. ARAŞTIRACAĞIM.",
["pln_at1_gen_20_03"] = "YÜKSEK GÜVENLİKLİ NAKİL ARACINDA ASKERÎ PLANLAR MI? NE BULABİLECEĞİME BAKARIM.",
["pln_at1_har_01_01"] = "BİRAZ SARSILACAĞIZ, SIKI TUTUNUN! UĞRAŞACAK TEK KAMYON VAR. KAPILAR AÇILIR AÇILMAZ SERT VURUN!",
["pln_at1_har_02_01"] = "KONFOR İÇİN KUSURA BAKMAYIN AMA DEĞECEK. DIŞARIDA İKİ KAMYONUMUZ VAR. KAPILAR AÇILIR AÇILMAZ SERT VURUN!",
["pln_at1_har_03_01"] = "UMARIM ORADA DAYANIYORSUNUZDUR. ÜÇ KAMYON KENARA ÇEKTİ. KAPILAR AÇILINCA GİRİŞİN!",
["pln_at1_har_04_01"] = "SİZİ ÖYLE TIKILMIŞ GÖRMEK HOŞ DEĞİL AMA DÖRT KAMYON YAKALADIK. ÇIKIP ÜSTLERİNE GİDİN!",
["pln_at1_intro_01_01"] = "TAMAM! KONVOYU DURDURDUK. ŞİMDİ AÇIN VE GANİMETİ GÜVENCEYE ALIN!",
["pln_at1_intro_01_02"] = "NAKLİYE ARACI DURDURULDU! AÇIN, GANİMETİ ÇANTALAYIN, KAÇIN. BASİT.",
["pln_at1_intro_01_03"] = "İŞTE, GÜMÜŞ TEPSİDE SUNULMUŞ ZIRHLI ARAÇ. AÇIP GANİMETİ GÜVENCEYE ALIN YETER.",
["pln_at1_intro_02_01"] = "ADAMIMIZ YERİNDE, HEDEF DE AZ ÖNCE MCCARTY'YE DÖNDÜ. AZ KALDI. AZ KALDI...",
["pln_at1_intro_02_02"] = "GENSEC KAMYONLARI ADAMIMIZIN GÖRÜŞ ALANINA GİRDİ. BEKLEYİN... BEKLEYİN...",
["pln_at1_intro_03_01"] = "C4 YERİNDE. ŞU DÜĞMEYE BASMAM GEREK VE...",
["pln_at1_intro_03_02"] = "PATLAYICILAR YERLEŞTİRİLDİ. GENSEC NAKLİYE ARAÇLARI YAKLAŞIYOR. AZ KALDI...",
["pln_at1_intro_04_01"] = "HEDEF GÖRÜLDÜ. SİZİ KONUMUNUZA YERLEŞTİRELİM, SONRA...",
["pln_at1_intro_04_02"] = "TAMAM MİLLET, İŞTE GELİYORLAR. O VİNCİ HAREKET ETTİRİN!",
["pln_at1_intro_05_01"] = "TAMAM, GENSEC YAKLAŞIYOR. GAZA BASIN. HADİ! HADİ!",
["pln_at1_intro_05_02"] = "GENSEC GÖRÜNDÜ. O ARAÇLARI HAREKET ETTİRİN. HADİ! HADİ! HADİ!",
["pln_at1_intro_06_01"] = "ŞOFÖRÜMÜZ AMBULANSI KENARA ÇEKİP KAÇTI. İŞTE HEDEF DE GELİYOR, TAM ZAMANINDA...",
["pln_at1_intro_06_02"] = "GENSEC YAKLAŞIYOR. GÖSTERİYİ BAŞLATALIM. TAMAM, VURUN.",
["pln_at1_par_01_01"] = "VAY, BÜYÜK İKRAMİYE! SAĞLAM VURDUK! O KAMYON DEVRE DIŞI. İŞE KOYULUN!",
["pln_at1_par_02_01"] = "TAM İSABET! İYİ MİSİNİZ? NE ÇARPIŞMAYDI AMA! O NAKİL ARAÇLARINA GİRİŞİN!",
["pln_at1_par_03_01"] = "HASSİKTİR! ÜÇ KAMYONU DA YOLDAN ÇIKARDIK. FIRSATI İYİ DEĞERLENDİRİN!",
["pln_at1_par_04_01"] = "BU BİR FLOŞ ROYAL EKİP. BÜTÜN LANET KAMYONLAR YAĞMALANMAYA HAZIR. İŞE KOYULUN!",
["pln_at1_und_01_01"] = "ŞOFÖRÜN İLK GÜNÜ OLMALI. APTAL AMBULANS İÇİN DURMUŞ! ŞİMDİ SIRA SİZDE MİLLET. ÇIKIP İŞİNİZİ YAPIN!",
["pln_at1_und_02_01"] = "BARİKAT İŞE YARADI, İKİ ZIRHLI ARAÇ DURDU. İŞE KOYULUP AÇIN!",
["pln_at1_und_03_01"] = "YEMİ YUTTULAR. ÜÇ NAKLİYE ARACI. MÜRETTEBAT SOKAKTA, NELER OLDUĞUNU ANLAMAYA ÇALIŞIYOR. SERT VURUN!",
["pln_at1_und_04_01"] = "MÜKEMMEL İŞ! DÖRT KAMYON DA DURDU, HAZIR. PARA YAĞDIRIN MİLLET!",
["pln_bb1_01_01"] = "BENEVOLENT BANK. NEOKLASİK BİR GÜZELLİK. AMA İŞ BİZİ BEKLER. BİRKAÇ ŞİFRE GEREKECEK, SUNUCULARINA GİDİN. ",
["pln_bb1_01_02"] = "GÜZEL BİR BİNA AMA ÇİRKİN İŞLER GETİRİYORUZ. DAHA DERİNE GİRMEK İÇİN ŞİFRELER LAZIM, SUNUCULARINI ARAYIN.",
["pln_bb1_02_01"] = "NE YAPACAĞINIZI BİLİYORSUNUZ. MUHAFIZLARA VE KAMERALARA DİKKAT EDİN. SİVİLLERİ KONTROL ALTINDA TUTUN. ETRAFTA ANAHTAR KARTLARI, BANKA MÜDÜRÜ, YARDIMCI OLABİLECEK NE VARSA ARAYIN.",
["pln_bb1_02_02"] = "NASIL İŞLEDİĞİNİ BİLİYORSUNUZ. GÜVENLİĞE GÖZÜNÜZ AÇIK OLSUN. SİVİLLERİ KONTROL ALTINDA TUTMALISINIZ. ANAHTAR KARTLARI DA HEP İŞE YARAR.",
["pln_bb1_03_01"] = "SUNUCU ODASI BURASI. İÇERİ GİRİP BENİ BAĞLAYIN.",
["pln_bb1_03_02"] = "SUNUCU ODASI. BENİ BAĞLAYIN MİLLET.",
["pln_bb1_04_01"] = "BENİ BAĞLAYIN. BURADAN SİSTEMLERİNE GİREBİLİRİM.",
["pln_bb1_04_02"] = "BENİ BAĞLAYIN. BURADAN BİRAZ YARAMAZLIK YAPABİLİRİM.",
["pln_bb1_05_01"] = "LANET OLSUN! GÖRÜNÜŞE GÖRE YEREL ERİŞİM GEREKİYOR. BÜYÜK İHTİMALLE PERSONEL BİLGİSAYARLARINDAN BİRİ. HANGİSİ OLDUĞUNU BULUN. GEREKİRSE HEPSİNİ DENEYİN.",
["pln_bb1_05_02"] = "GÜVENLİK DUVARLARI DEVREYE GİRDİ. YEREL BİR BAĞLANTI NOKTASI LAZIM, PERSONEL TERMİNALLERİNDEN BİRİ. ONLARI KONTROL EDİN.",
["pln_bb1_06_01"] = "TAMAM, GİRDİM! BEKLEYİN. ÇOK UZUN SÜRMEZ.",
["pln_bb1_06_02"] = "İÇERİDEYİM. BEKLEYİN MİLLET, BİRAZ ZAMANA İHTİYACIM VAR.",
["pln_bb1_07_01"] = "BAĞLANIYORUM. AYNI ANDA SADECE BİRİNİ YAPABİLİRİZ. UMARIM DOĞRU OLAN BUDUR.",
["pln_bb1_07_02"] = "ŞİMDİ BAĞLANIYORUM. DOĞRU OLAN BU OLSUN DİYE DUA ETSENİZ İYİ OLUR.",
["pln_bb1_08_01"] = "BAĞLANILIYOR...",
["pln_bb1_08_02"] = "ERİŞİM SAĞLIYORUM...",
["pln_bb1_08_03"] = "ŞİMDİ ERİŞİYORUM...",
["pln_bb1_09_01"] = "YANLIŞ BİLGİSAYARDI. BAŞKASINI DENEYİN. BELKİ GEREKEN TERMİNALİ BULMANIN BİR YOLU VARDIR.",
["pln_bb1_09_02"] = "YANLIŞ TERMİNALDİ. DENEMEYE DEVAM EDİN. İPUCU ARAYIN, SAAT İŞLİYOR, DOĞRU OLANI BULMALIYIZ.",
["pln_bb1_10_01"] = "ŞİFRE YOK. BAŞKASINI DENEYİN.",
["pln_bb1_10_02"] = "YANLIŞ TERMİNAL. BAŞKASINI DENEYİN.",
["pln_bb1_10_03"] = "BUNDAN BİR ŞEY ÇIKMAZ. BAŞKASINI DENEYİN. ÇABUK!",
["pln_bb1_11_01"] = "TAMAM! ŞİFREYİ ALDIK! ZAMAN KİLİDİNİ BAŞLATIN.",
["pln_bb1_11_02"] = "KOD BU! HARİKA. ŞİMDİ ZAMAN KİLİDİNDE KULLANIN.",
["pln_bb1_12_01"] = "PERSONEL BİLGİSAYARLARINDAN BİRİNDE BİR KOD VAR. ONU BULUP SİSTEMİ KIRMAYA BAŞLAYIN.",
["pln_bb1_12_02"] = "PERSONEL ODALARINDAN BİRİNDE HACKLEYEBİLECEĞİMİZ BİR BİLGİSAYAR OLACAK. BULUN.",
["pln_bb1_13_01"] = "ALARM ZAMAN KİLİDİNİ DEVRE DIŞI BIRAKTI. AKSİLİK AMA BAŞARISIZLIK DEĞİL. ÇATIDA BAKIM ODASI VAR. ORAYA GİDİN. YENİDEN BAŞLATABİLİRİZ.",
["pln_bb1_13_02"] = "ALARM ZAMAN KİLİDİNİ DURDURDU. SAKİN OLUN. ÇATIDA BİR BAKIM OFİSİ VAR. ORAYA GİDİN. KABLOLARINI DEĞİŞTİREBİLMEMİZ LAZIM.",
["pln_bb1_14_01"] = "ŞİMDİ BEKLİYORUZ. GÜZEL HİKÂYESİ OLAN VAR MI?",
["pln_bb1_14_02"] = "ŞİMDİ ZAMAN KİLİDİNİN SÜRESİNİN DOLMASINI BEKLİYORUZ. DEDEMİ VE SOYGUNCULUK GÜNLERİNİ HİÇ ANLATMIŞ MIYDIM?",
["pln_bb1_15_01"] = "ZAMAN KİLİDİNİN SÜRESİ DOLANA KADAR POLİSLERİ UZAK TUTUN.",
["pln_bb1_15_02"] = "SİPER ALIN EKİP. ZAMAN KİLİDİ BİTENE KADAR HATTI KORUYUN.",
["pln_bb1_16_01"] = "ÇATIYA ÇIKAN BİR MERDİVEN VAR. GARAJIN ÜSTÜNDE.",
["pln_bb1_16_02"] = "GARAJIN ÜSTÜNDE BİR ERİŞİM MERDİVENİ VAR. ORADAN ÇATIYA ÇIKABİLİRSİNİZ.",
["pln_bb1_17_01"] = "GÜZEL. DEVRE KUTUSU ORADA. KABLOLARINI YENİDEN BAĞLAMAK ZAMAN KİLİDİNİ TAMAMEN SIFIRLAR.",
["pln_bb1_17_02"] = "O DEVRELERİN BAĞLANTILARINI DEĞİŞTİRİN. ZAMAN KİLİDİNİ SIFIRLAMALI.",
["pln_bb1_18_01"] = "BU YETERLİ OLMALI. ŞİMDİ ZAMAN KİLİDİNİ YENİDEN BAŞLATIN. UMARIM İŞE YARAMIŞTIR.",
["pln_bb1_18_02"] = "TAMAM. ŞİMDİ ZAMAN KİLİDİNİ YENİDEN BAŞLATIP İŞE YARADI MI BAKALIM.",
["pln_bb1_19_01"] = "İŞE YARADI! HARİKA. ŞİMDİ POLİSLERİ UZAK TUTUN.",
["pln_bb1_19_02"] = "HARİKA. ŞİMDİ POLİSLERİ ONDAN UZAK TUTUN.",
["pln_bb1_20_01"] = "BUNU BEKLERKEN, YÜREĞİNİZ YETİYORSA ÇATIYA ÇIKIP ÇELİK HALATI KURUN.",
["pln_bb1_20_02"] = "ZAMAN KİLİDİ GERİ SAYARKEN BİRAZ HAZIRLIK YAPABİLİRSİNİZ. ÇATIDA KURULMASI GEREKEN BİR HALAT VAR.",
["pln_bb1_20_03"] = "PEKÂLÂ, BEKLERKEN İŞİ İLERLETMEK İSTERSENİZ ÇATIYA ÇIKABİLİRSİNİZ. ORAYA BİR ÇELİK HALAT KURMANIZ GEREK.",
["pln_bb1_21_01"] = "POLİSLER ZAMAN KİLİDİNİ BOZDU! YENİDEN ÇALIŞTIRIN!",
["pln_bb1_21_02"] = "POLİSLER ZAMAN KİLİDİNİ KURCALADI. YENİDEN BAŞLATIN.",
["pln_bb1_22_01"] = "HADİ! ZAMAN KİLİDİNİ YENİDEN BAŞLATIN!",
["pln_bb1_22_02"] = "O ZAMAN KİLİDİNİ YENİDEN İŞLETMEZSENİZ BÜTÜN BU İŞ BOŞA GİDECEK.",
["pln_bb1_23_01"] = "GÜZEL. ŞİMDİ POLİSLERİ UZAK TUTUN.",
["pln_bb1_23_02"] = "HARİKA. ŞİMDİ LÜTFEN POLİSLERİ ZAMAN KİLİDİNDEN UZAK TUTUN.",
