["pln_bb1_34_03"] = "ÜRETİCİLERİ BUNA AĞIR HİZMET TİPİ ENDÜSTRİYEL DELME AYGITI DİYOR AMA SOYGUNCULAR THE BEAST OLARAK BİLİR. BEYLER, ÇALIŞTIRIN.",
