["pln_bb1_43_02"] = "HARİKA. ŞİMDİ C4'Ü YERLEŞTİRİN DE BURADAN ÇIKMAYA BAŞLAYALIM.",
["pln_bb1_44_01"] = "OTOBÜSÜ ŞEY YAPACAK ŞEKİLDE AYARLADIM... NEYSE, İŞARETİ VERİN YETER. BİR DE GERİ ÇEKİLİN.",
["pln_bb1_44_02"] = "OTOBÜS ŞEY İÇİN TAMAMEN HAZIR... NEYSE, SİZ İŞARETİ VERMEYE BAKIN. SONRA GÖRÜRSÜNÜZ.",
