["pln_bb1_48_02"] = "BU ŞEHRİN OTOBÜSLERİ VAKTİNDE GELMEZ DİYEN KİMMİŞ! GANİMETİ TAŞIMAYA BAŞLAYIN.",
["pln_bb1_49_01"] = "İSTEDİĞİNİZ ZAMAN BİTİREBİLİRSİNİZ AMA ALABİLDİĞİNİZ KADAR ALIN.",
["pln_bb1_49_02"] = "BU İŞİ ŞİMDİ BİTİREBİLİR YA DA ŞIK BİR ŞEKİLDE BİTİRİP BURAYI TAMAMEN BOŞALTABİLİRSİNİZ.",
