["pln_bb1_50_02"] = "BİRİ TELEFONA CEVAP VERSİN!",
["pln_bb1_51_01"] = "ZAMAN KİLİDİ TAMAM. GİZLİLİĞİ KORUMAYA ÇALIŞIN. KASA DAİRESİNİN ÜÇ AŞAMALI ERİŞİM KONTROLÜ VAR. İLKİNİ BEN HALLETTİM. ORAYA GİDİP PARMAK İZİ TARAYICISINI KULLANIN.",
["pln_bb1_51_02"] = "ZAMAN KİLİDİ TAMAM. ÇOK İYİ GİDİYORSUNUZ. SESSİZ KALMAYA ÇALIŞIN. ŞİMDİ, KASA DAİRESİNİ AÇMANIN ÜÇ ADIMI VAR. İLKİ CEPTE, GİDİP PARMAK İZİ TARAYICISINI KULLANIN YETER.",
["pln_bb1_52_01"] = "O LAZERLER SİZE ZORLUK ÇIKARIYORSA ANAHTAR KARTLARI'YLA DEVRE DIŞI BIRAKABİLİRSİNİZ.",
["pln_bb1_52_02"] = "ANAHTAR KARTLARI LAZERLERİ KAPATABİLİR. BULMAK İÇİN GÖZÜNÜZ AÇIK OLSUN.",
["pln_bb1_53_01"] = "O BAŞPARMAĞI NEREDEN BULDUĞUMU SORMAYIN. ŞİMDİ GÜVENLİK KONSOLLARINDAN KİMLİĞİ DOĞRULAYIN. SORUN ÇIKMAMASI LAZIM.",
["pln_bb1_53_02"] = "BAŞPARMAK GİBİ ŞEYLERİ TEDARİK EDERKEN 'NE SORARIM NE ANLATIRIM' İLKESİNİ UYGULARIM. ŞİMDİ GÜVENLİK KONSOLLARINA GİDİN.",
["pln_bb1_54_01"] = "BİRİ TAMAM, BİRİ KALDI.",
["pln_bb1_54_02"] = "İLK KONSOL BU. ŞİMDİ İKİNCİ.",
["pln_bb1_55_01"] = "HARİKA. ŞİMDİ SON ADIM. MÜDÜRÜN ŞİFRESİNİ BULUN. BİLGİSAYARINDA OLMALI.",
["pln_bb1_55_02"] = "AZ KALDI. SON PROTOKOL, MÜDÜRÜN ŞİFRESİ. BİLGİSAYARINA BAKIN.",
["pln_bb1_56_01"] = "BAĞLANDIK... BAKALIM NE VAR.",
["pln_bb1_56_02"] = "HARİKA. BAĞLANDIK.",
