["pln_bb1_57_02"] = "ŞİFREYİ ALDIK. KASA DAİRESİNE DÖNÜN.",
["pln_bb1_58_01"] = "İŞE YARADI! HEPİNİZ HARİKASINIZ.",
["pln_bb1_58_02"] = "İŞTE BU! HARİKA İŞ EKİP.",
["pln_bb1_59_01"] = "O KAPILARI AÇMANIN SESSİZ YOLU ANAHTAR KULLANMAK. BULABİLİRSENİZ TABİİ.",
["pln_bb1_59_02"] = "HER KAPININ ANAHTARI VARDIR. BUNU SESSİZCE YAPMAK İSTİYORSANIZ ANAHTARLARI BULUN.",
["pln_bb1_60_01"] = "TERMİTİ ALIN. KASA DAİRESİNE ONUNLA GİRECEĞİZ.",
["pln_bb1_60_02"] = "KASA DAİRESİNE EN İYİ GİRİŞ YOLUMUZ TERMİT. BUNU DAHA ÖNCE YAPTIK.",
["pln_bb1_61_01"] = "ŞİMDİ KASA DAİRESİNE GİDİP O DÜZENEĞİ KURUN.",
["pln_bb1_61_02"] = "TERMİTİ KASA DAİRESİNE GERİ GÖTÜRÜN.",
["pln_bb1_62_01"] = "HAVAİ FİŞEK GÖSTERİSİNE HAZIR MISINIZ?",
["pln_bb1_62_02"] = "TUTUŞTURMA VAKTİ, MİLLET.",
["pln_bb1_63_01"] = "PATLATIYORUM!",
["pln_bb1_63_02"] = "ALÜMİNYUM VE DEMİR OKSİT... GÜZEL.",
["pln_bb1_64_01"] = "TERMİT İŞİNİ BİTİRDİ. ŞİMDİ İÇERİ ATLAYIP PARAYI ALIN.",
["pln_bb1_64_02"] = "TERMİT SÖNDÜ. YOLUNUZ AÇIK. AŞAĞI İNİP ÇANTALAMAYA BAŞLAYIN.",
["pln_bb1_65_01"] = "KASA DAİRESİ'NİN İÇİNDEKİ KAPILARIN ANAHTARLARI BUNLAR. İYİ BULDUNUZ.",
["pln_bb1_65_02"] = "O ANAHTARLAR KASA DAİRESİNDEKİ KAPILARI AÇAR. YARDIMCI OLUR.",
["pln_bb1_66_01"] = "İŞTE ALARM.",
["pln_bb1_66_02"] = "MİLLET, SANTRALLER AYDINLANDI. ALARM BU GALİBA.",
["pln_bb1_67_01"] = "ŞEY... EKİP... ASANSÖRLER HAREKET EDİYOR. MİSAFİR BEKLEYİN.",
["pln_bb1_67_02"] = "ASANSÖRLER KATINIZA GELİYOR. GÖZÜNÜZ ÜZERLERİNDE OLSUN.",
["pln_bb1_67_03"] = "MİLLET, ASANSÖRLER HAREKET EDİYOR. ORADAN GELECEK SALDIRIYA HAZIR OLUN.",
["pln_bb1_68_01"] = "BANKAYA BİR POLİS GİRİYOR. BİR FİKİR: ONU HALLEDİN.",
["pln_bb1_68_02"] = "BİR YAYA DEVRİYE POLİSİ BANKAYI KONTROL EDİYOR. GÜZELCE... KARŞILANDIĞINDAN EMİN OLUN.",
["pln_bb1_68_03"] = "BANKAYA BİR POLİS GİRDİ. İŞKİLLENMESİNE İZİN VERMEYİN.",
["pln_bb1_brf_01_01"] = "BENEVOLENT BANK'İN GEÇMİŞİ KÖKLÜ. ABD'NİN EN ESKİ BANKASI. 1812'DE İNGİLİZLER YAĞMALADI, İÇ SAVAŞ ALTININI TUTTU, FDR'NİN İLK TAHVİLLERİNİ ÇIKARDI. HATTA ON DOLARLIKLARIN ARKASINDA BİLE BULURSUNUZ. TAHMİN EDİN NE OLDU: BUNCA ZAMANDA HİÇ BAŞARIYLA SOYULMADI. ‘BAŞARIYLA.’ BUGÜN BUNU DEĞİŞTİRMEYİ DENEME SIRASI SİZDE. ÖN KAPIDAN GİRECEKSİNİZ. LOBİDEN İLERİDEKİ KASA DAİRELERİNE EN İYİ GEÇİŞ YOLUNU BULMAK İÇİN KEŞİF YAPIN. ONCA GANİMETİ NASIL ÇIKARACAĞIMIZA DAİR FİKİRLERİM VAR. GÜVENİN BANA. TARİH YAZIN MİLLET.",
["pln_bb1_end_01_01"] = "İKİ YÜZ YIL SÜRDÜ AMA BENEVOLENT BANK SONUNDA SOYULDU. MUHTEŞEM İŞ!",
["pln_bb1_end_01_02"] = "TARİHÎ BİR GÜN EKİP. HAHA, SONUNDA BENEVOLENT'I AÇTINIZ.",
["pln_bb1_end_02_01"] = "RAKAMLARI KONUŞALIM. İKİ YÜZ YILDA ON ÜÇ MÜDÜR, MİLYONLARCA MÜŞTERİ, TAŞINAN TRİLYONLARCA DOLAR. BİR DE DÖRT BELALI GANGSTERİN TEK SOYGUNU.",
["pln_bb1_end_02_02"] = "SADECE BİR TON PARA ÇALMAKLA KALMADINIZ, BU İŞ BENEVOLENT'IN HİSSE DEĞERİNDEN DE MİLYONLAR SİLDİ. HARİKA İŞ!",
["pln_bb1_end_03_01"] = "SOYGUNCULAR BU İŞTEKİ TEKNİĞİNİZİ YILLARCA İNCELEYECEK. HARİKA İŞ!",
["pln_bb1_end_03_02"] = "TARİH KİTAPLARINDAKİ YERİNİZİ GARANTİLEDİNİZ EKİP. TEK KELİMEYLE MÜKEMMEL!",
["pln_bb1_end_04_01"] = "BU GÜN SUÇ DÜNYASI İÇİN HEP ÖZEL KALACAK. PAYDAY GANG'İN BENEVOLENT'I DİZE GETİRDİĞİ GÜN.",
["pln_bb1_end_04_02"] = "(ŞARKI SÖYLER) \"MONTE CARLO'DA BANKAYI SOYAN EKİP ONLAR.\" MUHTEŞEM!",
["pln_bb1_intro_01_01"] = "BURADA GÜVENLİK SIKI. BU SOYGUNU SESSİZCE YAPABİLİRİZ BELKİ. AMA GÜRÜLTÜ ÇIKARSA ENDİŞELENMEYİN. BENİM HER ZAMAN BİR B PLANIM VARDIR.",
["pln_bb1_intro_01_02"] = "BÜYÜK BİR BANKA AMA SONUÇTA BANKA. USULÜ BİLİYORSUNUZ. ETRAFA BAKIP SESSİZ Mİ KALACAKSINIZ, GÜRÜLTÜ MÜ KOPARACAKSINIZ, KARAR VERİN.",
["pln_bb1_intro_01_03"] = "İŞTE BU. ŞİMDİYE KADARKİ EN BÜYÜK BANKA SOYGUNU. HER ŞEY BU ANIN HAZIRLIĞIYDI. NE YAPACAĞINIZI BİLİYORSUNUZ.",
["pln_bigoil_stage1_01_any_01"] = "TAMAM, EVE GİDİP ADRESİ BULUN. DİKKATLİ OLUN.",
["pln_bigoil_stage1_02_any_01"] = "TAMAM MİLLET, ETRAFI ARAYIN. ADRESİN ORADA BİR YERDE OLDUĞUNU BİLİYORUM.",
["pln_bigoil_stage1_03_any_01"] = "BULDUNUZ MU? MUHTEMELEN GÜVENLİ BİR YERE KOYMUŞLARDIR.",
["pln_bigoil_stage1_04_any_01"] = "ADRES BU! GEREKENİ ALDIK. MİNİBÜSE DÖNÜN DE BURADAN ÇIKALIM.",
["pln_bigoil_stage1_05_any_01"] = "BU BİR ANAHTAR KARTI GİBİ GÖRÜNÜYOR. MUHTEMELEN SONRA KULLANABİLİRİZ.",
["pln_bigoil_stage1_06_any_01"] = "ŞİFRELERE BENZİYOR, İŞE YARAR.",
["pln_bigoil_stage1_07_any_01"] = "BU İŞE YARAR GİBİ.",
["pln_bigoil_stage1_08_any_01"] = "İSTİHBARATA BENZİYOR. İŞE YARAYACAK.",
["pln_bigoil_stage1_09_any_01"] = "BU DOSYALARIN ARASINDA MUHTEMELEN İŞE YARAR BİLGİLER VAR...",
["pln_bigoil_stage1_10_any_01"] = "O FOTOĞRAFLAR SONRA İŞE YARAYABİLİR.",
["pln_bigoil_stage1_11_any_01"] = "BUNLAR MUHTEMELEN BİNANIN PLANLARI.",
["pln_bigoil_stage1_12_any_01"] = "SİKTİR, POLİS BURADA!",
["pln_bigoil_stage1_13_any_01"] = "KAHRETSİN! SİZİ GÖRDÜLER!",
["pln_bigoil_stage1_14_any_01"] = "HASSİKTİR! KAMERA SİSTEMİNE MAYIN BAĞLAMIŞLAR!",
["pln_bigoil_stage1_15_any_01"] = "DOĞUDAN, ORMAN TARAFINDAN GELİYORLAR.",
["pln_bigoil_stage1_16_any_01"] = "BATIDAN, İNŞAATIN YANINDAN GELİYORLAR.",
["pln_bigoil_stage1_17_any_01"] = "GÜNEYDEN, FABRİKANIN YANINDAN GELİYORLAR.",
["pln_bigoil_stage1_18_any_01"] = "GÜZEL, PARAYI MİNİBÜSE GETİRİN.",
["pln_bigoil_stage1_brief_01"] = "THE ELEPHANT BİZE BİLİM İNSANININ KÜÇÜK CİHAZININ PEŞİNDEKİ MOTORCU ÇETESİNİN KONUMLARINI VERDİ. BENCE ONU BULMAYA ÇOK YAKLAŞTILAR. ONDAN ÖNCE DAVRANMAK İÇİN İSTİHBARATLARINI ALMAMIZ GEREK.",
["pln_bigoil_stage1_brief_01b"] = "BAHSE GİRERİM KASALARINDADIR.",
["pln_bigoil_stage1_brief_02"] = "GÖZCÜLERİN SAYISINA BAKILIRSA BİZE HAZIRLAR... KAMERALARI DA VAR GALİBA. VURMADAN ÖNCE İYİCE YAKLAŞIN.",
["pln_bigoil_stage1_brief_02b"] = "İSTİHBARATI ALMADAN ÖNCE BİZİ DURDURMALARINI İSTEMEYİZ. KASAYI BULUN, MUHTEMELEN ORADA.",
["pln_bigoil_stage1_end_a_01"] = "TAMAM, İSTİHBARAT SAĞLAM. BİLİM İNSANININ SAKLANDIĞI ANLAŞILAN BÜYÜK VİLLAYA SALDIRIYI PLANLAMAMIZA YARDIM EDECEK. HAZIRLANIP ORAYA GİDELİM.",
["pln_bigoil_stage1_end_b_01"] = "TAMAM, ADRESİ ALDIK. DAĞLARDA, YÜKSEK GÜVENLİKLİ BİR VİLLADA YAŞIYOR. GÖZDEN UZAK, LÜKS BİR BÖLGE. HİÇ İSTİHBARAT OLMADAN, KÖRLEMESİNE GİRECEĞİZ. SİLAHLANIN DA GİDELİM. ",
["pln_bigoil_stage1_end_b_02"] = "ADRESİ ALDIK AMA HİÇ İSTİHBARAT ELDE EDEMEDİK. YANİ SERT GİRECEĞİZ VE BİZİ NEYİN BEKLEDİĞİNE DAİR HİÇBİR FİKRİMİZ YOK. ZAMAN DARALIYOR, HADİ DAĞLARA ÇIKIP ŞU MOTORU ÇALALIM. ",
["pln_bigoil_stage1_intro_a_01"] = "MOTORCULAR GELECEĞİMİZİ NEREDEN BİLİYOR BİLMİYORUM AMA BİLİYORLAR. BELKİ O KADAR MET KULLANINCA ALTINCI HİSLERİ AÇILMIŞTIR...",
["pln_bigoil_stage1_intro_a_01b"] = "NEYSE, YAKLAŞIN, SERT VURUN, KASAYI BULUN VE ORADAKİ BÜTÜN İSTİHBARATI ALIN. HİÇBİR ŞEY BIRAKMAYIN.",
["pln_bigoil_stage1_intro_a_02"] = "KAVGA BEKLİYORLAR GALİBA. SİZİN DE İSTEDİKLERİNİ VERECEĞİNİZİ BİLİYORUM. KASAYI VE ADRESİ BULUN... BU PİSLİKLERDEN ALABİLDİĞİNİZ KADAR İSTİHBARAT ALIN. HADİ BAŞLAYALIM.",
["pln_bigoil_stage1_intro_a_03"] = "YA SÜR YA ÖL, SLOGANLARI BUYDU. İYİ İŞ. BU İSTİHBARAT ÇOK YARDIM EDECEK. BİLİM İNSANININ EVİNİ VURMADAN ÖNCE İYİCE İNCELEYİN. GİDİP ŞU FÜZYON MOTORUNU ALALIM.",
["pln_bigoil_stage2_01_any_01"] = "PEKÂLÂ, EVİ GÖRÜYOR MUSUNUZ? İÇERİ GİRİP SUNUCU ODASINI BULUN. LABORATUVARA ULAŞMAK İÇİN GÜVENLİK SİSTEMİNİ ELE GEÇİRMEMİZ GEREK.",
["pln_bigoil_stage2_02_any_01"] = "SUNUCU ODASI BURASI. İÇERİ GİRİP BENİ BİLGİSAYARA BAĞLAYIN.",
["pln_bigoil_stage2_03_any_01"] = "BULDUĞUNUZ ANAHTAR KARTI'NI KULLANABİLİRSİNİZ.",
["pln_bigoil_stage2_04_any_01"] = "GÜZEL, ŞİMDİ BAĞLANTIYI KURUN.",
["pln_bigoil_stage2_05_any_01"] = "GİRDİM, BU BİRAZ SÜREBİLİR...",
["pln_bigoil_stage2_06_any_01"] = "SIZMAYI KİMSENİN FARK ETMEDİĞİNDEN EMİN OLUN...",
["pln_bigoil_stage2_07_any_01"] = "LANET OLSUN! SUNUCUNUN ELEKTRİĞİNİ KESTİLER! GERİ GETİRİN!",
["pln_bigoil_stage2_08_any_01"] = "ELEKTRİĞİ KESTİLER, YENİDEN AÇIN!",
["pln_bigoil_stage2_08_any_02"] = "SUNUCUNUN ELEKTRİĞİNİ GERİ GETİRİN!",
["pln_bigoil_stage2_08_any_03"] = "BAĞLANTIM KESİLDİ, ELEKTRİĞİ GERİ GETİRMENİZ GEREKİYOR.",
["pln_bigoil_stage2_09_any_01"] = "HARİKA! ŞİMDİ BAĞLANTIYI YENİDEN KURUN.",
["pln_bigoil_stage2_09_any_02"] = "TAMAM, BENİ TEKRAR BAĞLAYIN.",
["pln_bigoil_stage2_10_any_01"] = "HARİKA İŞ, BAĞLANTI KURULDU!",
["pln_bigoil_stage2_11_any_01"] = "TAMAMDIR! LABORATUVAR KAPISINI AÇIN!",
["pln_bigoil_stage2_12_any_01"] = "TAMAM, GÖRÜNÜŞE GÖRE... 11... 12 PROTOTİP VAR. EVDE HANGİSİNİN ÇALIŞTIĞINI GÖSTERECEK BİR ŞEY BULABİLİR MİSİNİZ, BAKIN. SONRA ALIP BANA GETİRİN.",
["pln_bigoil_stage2_13_any_01"] = "HARİKA, İŞARET FİŞEĞİNİ YAKIN DA İNELİM!",
["pln_bigoil_stage2_14_any_01"] = "TAMAM, GÖRÜYORUM! YAKINDA ORADAYIZ.",
["pln_bigoil_stage2_15_any_01"] = "YAKLAŞIK BİR DAKİKAYA ORADAYIZ.",
["pln_bigoil_stage2_16_any_01"] = "TAMAM, GELİYORUM, SUNUCUYU HAZIRLAYIN!",
["pln_bigoil_stage2_17_any_01"] = "REAKTÖRÜ BANA VERİN, ÇABUK OLUN!",
["pln_bigoil_stage2_18_any_01"] = "TEŞEKKÜRLER, BURADAKİ ADAMIMA İNCELETECEĞİM. DOĞRU OLANSA GİTMEYE HAZIRIZ. BİRAZ BEKLEYİN.",
["pln_bigoil_stage2_19_any_01"] = "ÜZGÜNÜM MİLLET, BU DEĞİL DİYOR. BİRAZDAN DÖNERİM, ÇALIŞANI VERİRSİNİZ.",
["pln_bigoil_stage2_20_any_01"] = "HAYIR... BU DA ÇALIŞMIYOR. BAŞKASINI GETİRİN, HEMEN ORADAYIM.",
["pln_bigoil_stage2_20_any_02"] = "BU ARIZALI GİBİ. BAŞKASINI ALMAK İÇİN DÖNECEĞİM.",
["pln_bigoil_stage2_20_any_03"] = "HAYIR, BUNDA BİR SORUN VAR. BAŞKASINI ALMAYA GERİ DÖNÜYOR...",
["pln_bigoil_stage2_21_any_01"] = "İYİ İŞ MİLLET! DOĞRU OLAN BU GİBİ! BİR AN ÖNCE ORADAN ÇIKSANIZ İYİ OLUR.",
["pln_bigoil_stage2_22_any_01"] = "POLİSLER GELDİ, MEVZİNİZİ TUTUN!",
["pln_bigoil_stage2_23_any_01"] = "ÇATIYA SWAT KONUŞLANDIRIYORLAR!",
["pln_bigoil_stage2_24_any_01"] = "KESKİN NİŞANCI KONUŞLANDIRDILAR. BAŞINIZI EĞİN.",
["pln_bigoil_stage2_25_any_01"] = "BULDUĞUNUZ KODLARI KULLANARAK PENCERE PANJURLARINI KAPATABİLİRSİNİZ.",
["pln_bigoil_stage2_brief_01"] = "İSTİHBARATI İNCELEDİM. İLGİNÇ OLACAK. DESTEK SEÇENEKLERİNE BAKIN, İÇLERİNİ DIŞLARINI İYİCE ÖĞRENİN. GİZLİCE GİRİP ADAMIN LABORATUVARINI, LABORATUVARDA DA FÜZYON MOTORUNU BULMALIYIZ.",
["pln_bigoil_stage2_brief_01b"] = "GÜVENLİĞİN ÇOK SIKI OLMASI ŞAŞIRTICI DEĞİL. O YÜZDEN ARABAYLA GİTMEK YERİNE HAVADAN ATLAYACAĞIZ. SESSİZ VE ÖLÜMCÜL. MOTORU BULUN, BEN DE UÇAKLA ÇIKARTAYIM. İYİ ŞANSLAR.",
["pln_bigoil_stage2_end_a_01"] = "THE ELEPHANT ÇOK HEYECANLANACAK. PETROL DEVLERİNDEN 2050'YE KADAR SEÇİM KAMPANYASI DESTEĞİ ALDI RESMEN. ÇOK PROFESYONELCE MİLLET.",
["pln_bigoil_stage2_end_a_02"] = "EH, FÜZYON YOK AMA EN AZINDAN BÖYLECE BENZİN CANAVARI ARABALARIMIZI DAHA UZUN KULLANABİLECEĞİZ. BEN DE HERKES KADAR FİREBİRD'ÜMÜ SEVİYORUM.",
["pln_bigoil_stage2_end_a_03"] = "TUCKER'IN KİM OLDUĞUNU BİLİYOR MUSUNUZ? UMARIM BİLMİYORSUNUZDUR. ORADA HARİKA İŞ ÇIKARDINIZ.",
["pln_bigoil_stage2_end_b_01"] = "TAMAM MİLLET, AĞIR İŞTİ! DOĞRU MOTOR TESLİM EDİLDİ, ŞİMDİ KİLİT ALTINDA. PARAMIZ GELİYOR!",
["pln_bigoil_stage2_end_b_02"] = "İYİ İŞ ÇIKARDINIZ MİLLET. TAŞIMASI TAM BİR BELAYDI AMA DOĞRU MOTORU ALDIK VE SIKI SIKIYA KİLİTLEDİK. BELKİ BİR GÜN KENDİ HESABIMIZA ÇALIŞIP ONU GERİ ALIRIZ, HA?",
["pln_bigoil_stage2_end_b_03"] = "BİLİMİ SEVMİYOR MUSUNUZ? HARİKA EKİP İŞİ. MOTORU EMEKLİYE AYIRDIK, TA Kİ... ONU KENDİMİZ ÖZGÜRLEŞTİRMEYE KARAR VERENE KADAR. KAZANCIN TADINI ÇIKARIN.",
["pln_bigoil_stage2_intro_a_01"] = "HERKES BURADA, GÜZEL. VİLLA PİSTİN DİĞER TARAFINDA. GİZLİCE GİRİP LABORATUVARI BULUN. MOTORU BULUNCA HIZLA BU HAVAALANINA GETİRİN VE ALINMAYI BEKLEYİN.",
["pln_bigoil_stage2_intro_a_01b"] = "BİR DE DÜŞÜRMEYİN...",
["pln_bigoil_stage2_intro_a_02"] = "ON NUMARA İNİŞ. GÜZEL ATLAYIŞTI. VİLLASINA BİR KİLOMETRE UZAKTASINIZ. HAVAALANINI GİZLİCE GEÇİP EVE GİRİN. MOTORU BULUN VE BURAYA GETİRİN. GERİSİNİ BEN HALLEDERİM.",
["pln_bigoil_stage2_intro_a_03"] = "TAM İSABET. PLANIN ÖZETİ: EVE GİRİN, LABORATUVARI BULUN, MOTORU ALIN, BU HAVAALANINA DÖNÜN, KAÇIN. İYİ ŞANSLAR.",
["pln_bo1_01_any_01"] = "TAMAM, EVE GİDİP ADRESİ BULUN, DİKKATLİ OLUN.",
["pln_bo1_01_any_02"] = "TAMAM, KULÜP BİNASI ORASI. GEREKEN ADRES MOTORCULARDA. GİZLİCE GİRİN.",
["pln_bo1_01_any_03"] = "ŞİMDİ SESSİZCE. SİNSİCE YAKLAŞIP SERT VURUN. ",
["pln_bo1_02_any_01"] = "TAMAM MİLLET, BURAYI ARAYIN. BİR YERDE KASALARI VAR, MUHTEMELEN ONUN İÇİNDEDİR.",
["pln_bo1_02_any_02"] = "TAMAM, KAYBEDECEK VAKİT YOK, BÜTÜN İSTİHBARATI ALIN.",
["pln_bo1_02_any_03"] = "HİÇBİR İSTİHBARATI YOK ETMELERİNE İZİN VERMEYİN. HEPSİNİ ALIN!",
["pln_bo1_03_any_01"] = "KASAYI BULDUNUZ MU? ADRES MUHTEMELEN İÇİNDEDİR.",
["pln_bo1_03_any_02"] = "KASA'YI ARAYIN MİLLET. ORALARDA BİR YERDE OLMALI.",
["pln_bo1_03_any_03"] = "KASAYA BAKIN, BULUN ONU. ÇABUK!",
["pln_bo1_04_any_01"] = "TAMAM, İŞTE BU! ŞİMDİ O ŞEYİ AÇIN.",
["pln_bo1_04_any_02"] = "BULDUNUZ. ŞİMDİ AÇIP O ADRESİ ALIN.",
["pln_bo1_04_any_03"] = "İŞTE BU. AÇIN DA BAKALIM NE VARMIŞ.",
