["pln_bo2_32_any_02"] = "TAMAM, LABORATUVAR KAPISININ KİLİDİ AÇILDI. AÇIN KAPIYI.",
["pln_bo2_33_any_01"] = "TAMAM, GİRDİK. ÇALIŞAN DOĞRU FÜZYON MOTORUNU BULUN. NOTLARINI İNCELEYİN. ÇÖZÜN ŞU İŞİ!",
["pln_bo2_33_any_02"] = "TAMAM DOKTORLAR, MIT BECERİLERİNİZİ KONUŞTURUN. DOĞRU FÜZYON MOTORUNU BULUN. HADİ!",
["pln_bo2_33_any_03"] = "AH TAMAM... GÖRÜNÜŞE GÖRE BURADA BİRAZ FAZLA VAR. FÜZYON MOTORU YANİ. DOĞRU OLANI BULUN.",
["pln_bo2_34_any_01"] = "MİLLET... DOĞRU OLANIN NASIL GÖRÜNDÜĞÜNE DAİR İPUCU GÖRÜYOR MUSUNUZ?",
["pln_bo2_34_any_02"] = "KÂĞITLARINA, NOTLARINA VE BİLGİSAYARLARINA BAKIN. BURADA NEYİN DOĞRU OLDUĞUNA DAİR İPUCU OLABİLECEK HER ŞEYE.",
["pln_bo2_34_any_03"] = "SİKTİR, BU İLERİ BİLİM İŞİ. KAFALARI ÇALIŞTIRIN. RENK KODU, KİMYASAL FALAN, HER ŞEY İPUCU OLABİLİR.",
["pln_bo2_35_any_01"] = "HARİKA, HELİKOPTERİN İNMESİ İÇİN İŞARET FİŞEĞİNİ YAKIN!",
["pln_bo2_35_any_02"] = "İŞARET FİŞEĞİNİ YAKIN DA HELİKOPTERİ GETİRELİM.",
