["pln_bo2_38_any_02"] = "İÇERİ YÜKLEYİN!",
["pln_bo2_39_any_01"] = "TAMAM! İNCELEYEBİLMEMİZ İÇİN BURAYA GETİRECEK.",
["pln_bo2_39_any_02"] = "TAMAM, BİZE UÇURARAK GETİRİYOR. KONTROL EDECEĞİZ.",
["pln_bo2_39_any_03"] = "BURAYA GELİNCE DOĞRULATACAĞIM. YERİNİZDE KALIN.",
["pln_bo2_40_any_01"] = "MOTOR BİZDE. BURADAKİ ADAMIMA İNCELETECEĞİM.",
["pln_bo2_40_any_02"] = "MOTORU TESLİM ETTİ. BURADAKİ ADAMIMA İNCELETECEĞİM. DOĞRU OLANSA GİTMEYE HAZIRIZ. BİRAZ BEKLEYİN.",
["pln_bo2_40_any_03"] = "TAMAM, İNCELİYORUZ... ŞİMDİLİK HER ŞEY YOLUNDA... ŞİMDİ TESTLERİ YAPIYOR...",
["pln_bo2_41_any_01"] = "ŞANSIMIZ YAVER GİTMEDİ GALİBA. BU İŞ GÖRMEZ. BAŞKASINI GETİRİN. ALMASI İÇİN HELİKOPTERİ GERİ GÖNDERİYORUM.",
["pln_bo2_41_any_02"] = "KUSURA BAKMAYIN MİLLET, DOĞRU OLAN BU DEĞİLMİŞ. HELİKOPTER BİRAZDAN DÖNECEK, BURAYA BİR TANE DAHA GÖNDERİRSİNİZ. UMARIM DOĞRUSU OLUR.",
["pln_bo2_41_any_03"] = "LANET OLSUN, BU ARIZALI GALİBA! BAŞKASINI ALMASI İÇİN HELİKOPTERİ GERİ YOLLUYORUM.",
["pln_bo2_41_any_04"] = "BU PARAMPARÇA OLMUŞ, DUMAN ÇIKARIYOR. LABORATUVARDAN YENİSİNİ GETİRİN.",
["pln_bo2_42_any_01"] = "EVET! DOĞRU OLAN BU. SİZİ ALMASI İÇİN HELİKOPTERİ GÖNDERİYORUM! SIKI DURUN!",
["pln_bo2_42_any_02"] = "SÜPER! DOĞRU OLAN BU. FÜZYON TAM GÜÇ ÇALIŞIYOR. SAĞ OLUN MİLLET. ŞİMDİ ÇIKIN ORADAN. ",
["pln_bo2_42_any_03"] = "FÜZYON TEPKİMESİ DOĞRULANDI. HER ŞEY YOLUNDA. ORADAN SIVIŞIN!",
["pln_bo2_43_any_01"] = "İYİ İŞ MİLLET! DOĞRUSU BU GİBİ GÖRÜNÜYOR! BİR AN ÖNCE ORADAN ÇIKSANIZ İYİ OLUR. BULDUĞUNUZ UÇAK ANAHTARLARINI KULLANIN.",
["pln_bo2_43_any_02"] = "AHA! İŞTE BU! SOĞUK FÜZYON, TAM BURADA. UÇAĞININ ANAHTARLARI SİZDE, HATIRLADINIZ MI? DEFOLUN ORADAN!",
["pln_bo2_44_any_01"] = "DR FANTASTİC! SİZ GERÇEKTEN ZEKİSİNİZ. DOĞRU MOTORU ALDIK VE ZENGİN OLDUNUZ. ŞİMDİ ÇIKIN ORADAN! HELİKOPTER GELİYOR.",
["pln_bo2_45_any_01"] = "BAY DOKTOR MUHTEŞEM EFENDİM! TUTTURDUNUZ. BİLİM İŞTE, İYİ İŞ EKİP. O BÜYÜK BEYİNLERİNİZİ ÇIKARIN ORADAN! UÇAĞI KULLANIN.",
["pln_bo2_46_any_01"] = "TAMAM BEYLER! ORADAN DEFOLUP GİTME VAKTİ!",
["pln_bo2_46_any_02"] = "TAMAM, SÖZÜNÜZÜ TUTTUNUZ! ŞİMDİ SİZİ ORADAN ÇIKARAYIM.",
["pln_bo2_46_any_03"] = "AFERİN. HELİKOPTERE BİNİN DE PARAMIZI ALALIM.",
["pln_bo2_47_any_01"] = "KUSURA BAKMAYIN MİLLET, PİLOT YAKIT ALMASI GEREKTİĞİNİ SÖYLÜYOR... BİRAZ SÜRECEK. BİR SÜRE DAYANIN, TAMAM MI?",
["pln_bo2_47_any_02"] = "HIMM, UFAK BİR SORUNUMUZ VAR. HELİKOPTER BU KADAR GİDİP GELİNCE YAKITI BİTİYOR. YAKIT ALINCA GERİ DÖNECEK. MEVZİNİZİ KORUYUN!",
["pln_bo2_47_any_03"] = "AH... TAMAM MİLLET, HELİKOPTERE BİRAZ YAKIT GEREKİYOR. DEPOSU BOŞ. YAKLAŞIK 10 - 15 DAKİKA YERİNİZDE KALMANIZ LAZIM. ",
["pln_bo2_48_any_01"] = "TAMAM, ŞİMDİ YAKIT DOLDURUYOR. ACELE ETMESİNİ SÖYLEDİM AMA...",
["pln_bo2_48_any_02"] = "TAMAM, ŞİMDİ HELİKOPTERE YAKIT DOLDURUYOR. DAYANIN MİLLET!",
["pln_bo2_48_any_03"] = "PİLOT HELİKOPTERE YAKIT ALIYOR, YAKINDA DÖNECEK, SÖZ VERİYORUM.",
["pln_bo2_49_any_01"] = "EVET! YAKITI ALDI, GERİ DÖNÜYOR!",
["pln_bo2_49_any_02"] = "HELİKOPTER GERİ GELİYOR. BU KADAR UZATTIĞIM İÇİN KUSURA BAKMAYIN.",
["pln_bo2_49_any_03"] = "SONUNDA HELİKOPTER PİLOTU SİZİ ALMAYA GERİ DÖNÜYOR MİLLET. GECİKME İÇİN KUSURA BAKMAYIN.",
["pln_bo2_50_any_01"] = "ÇATIDA BLACKHAWK! KÖTÜ GÖRÜNÜYOR MİLLET!",
["pln_bo2_50_any_02"] = "BLACKHAWK! BLACKHAWK ALÇALIYOR! SİLAHLARI KALDIRIN, EKİP!",
["pln_bo2_50_any_03"] = "ÇATI, ÇATI! ÇATIDA BLACKHAWK VAR!",
["pln_bo2_51_any_01"] = "LANET OLSUN! ALARM! ARTIK BÜTÜN EV GELDİĞİMİZİ BİLİYOR!",
["pln_bph_01_01"] = "DENTİST, SENİ GÖT HERİF, O PARLAYAN GÖZLERİNİ MATKAPLA OYACAĞIM...",
["pln_bph_01_02"] = "HEY MİLLET! BENİ ALMAYA GELECEĞİNİZİ BİLİYORDUM. BURADAN ÇIKMANIN BİR YOLUNU BULDUNUZ MU?",
["pln_bph_01_03"] = "AA, EVET. GİTMEMİZ LAZIM.",
["pln_bph_01_04"] = "SAĞ OLUN MİLLET. UMARIM İYİ BİR TAHLİYE PLANINIZ VARDIR.",
["pln_bph_02_01"] = "HEY DENTİST, BURALARDA MISIN?",
["pln_bph_02_02"] = "BEN VURURUM, SEN ÖLÜRSÜN!",
["pln_bph_02_03"] = "BU NE? SİLAH MI? OH, EVET!",
["pln_bph_03_01"] = "KENTO, BAŞINA BELA GELİYOR...",
["pln_bph_03_02"] = "İŞTE BURADASIN, SENİ PİÇ!",
["pln_bph_04_01"] = "MURKYWATER OROSPU ÇOCUĞU!",
["pln_bph_04_02"] = "AL BAKALIM, OROSPU ÇOCUĞU.",
["pln_bph_05_01"] = "NİYE BU KADAR UZUN SÜRDÜ LAN?",
["pln_bph_05_02"] = "HEY MİLLET. SİZİ BEKLİYORDUM. NASIL GÖRÜNÜYORUM?",
["pln_bph_05_03"] = "MİLLET, KENTO. KENTO, BUNLAR DA BİZİMKİLER. AA, ÖLMÜŞ GALİBA. NEYSE.",
["pln_bph_05_04"] = "VAY. KAZANDIM MI?",
["pln_bph_06_01"] = "ALTIN MİLLET... MAYA ALTINI... KULLANMALISINIZ...",
["pln_bph_06_02"] = "ALTIN GEREKECEK... 1ST WORLD BANK... MAYA MALZEMESİ...",
["pln_bph_06_03"] = "DENTİST... ELEPHANT... SPUTNİK... UYARMALIYIM...",
["pln_branchbank_bbv_stage1_intro_a_01"] = "TAMAM, BANKA BU. ÖNCE MEKÂNI KOLAÇAN ETMENİZİ ÖNERİRİM. SONRA KASA DAİRESİNİ İSTEDİĞİNİZ GİBİ VURUN. GENELDE GÜVENLİK ODASI OLUR, DİKKATLİ OLUN.",
["pln_branchbank_bbv_stage1_intro_a_02"] = "SOYGUN VAKTİ. BURADAN NE ÇIKARACAĞIMIZI BİLMİYORUM AMA UNUTMAYIN, SİVİLLERİ KONTROL ALTINDA TUTUN. ALARM YA DA TELEFON KULLANMALARINA İZİN VERMEYİN. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_branchbank_bbv_stage1_intro_a_03"] = "MİLLET, NASIL YAPILDIĞINI BİLİYORSUNUZ. BİRAZ KEŞİF AKILLICA OLUR. HAZIR OLDUĞUNUZDA KASA DAİRESİNİ MATKAPLA AÇIN. BURADA NE VAR BİLMİYORUM AMA ŞANSIMIZI BEĞENİYORUM.",
["pln_branchbank_cash_brf_speak_01"] = "THE HARVEST & TRUSTEE BANK'E, ŞEHİR DIŞINDAKİ KUMARHANELERE TAŞINACAK YENİ BİR NAKİT SEVKİYATI GELDİ. BENCE BİZ DE KÜÇÜK BİR PARASAL \"MÜDAHALEDE\" BULUNALIM.",
["pln_branchbank_cash_brf_speak_01b"] = "YANİ O KADAR DA İHTİYAÇLARI YOK... ŞU KASA DAİRESİNİ VURALIM.",
["pln_branchbank_cash_brf_speak_02"] = "YAKINDAKİ BİR İSVEÇ MOBİLYA DEPOSUNDAN HARVEST & TRUSTEE BANKASINA AZ ÖNCE TEK SEFERDE BÜYÜK BİR NAKİT YATIRILDIĞINI BİLİYORUM. İÇERİ GİRİP ORAYI İNDİRECEĞİZ.",
["pln_branchbank_cash_brf_speak_02b"] = "YERLEŞİMİ BİZİM İÇİN OLDUKÇA UYGUN. KASA DAİRESİ ARKADA. VAR MISINIZ?",
["pln_branchbank_cash_brf_speak_03"] = "BUGÜN ŞANSLI GÜNÜMÜZ. HAVAALANINDAN BU BANKAYA NAKİT GELİYOR, HER TÜRLÜ KUPÜRDEN... O YÜZDEN KENDİ PARA DEĞİŞİMİMİZİ YAPMAYI ÖNERİYORUM.",
["pln_branchbank_cash_brf_speak_03b"] = "O KASA DAİRESİNİ VURACAĞIZ, HEM DE SERT VURACAĞIZ. HAZIR MISINIZ?",
["pln_branchbank_cash_brf_speak_04"] = "BİRAZ NAKİT ÇOK İŞ GÖRÜR. YEREL HARVEST & TRUSTEE ŞUBESİNİN YÜKÜNÜ HAFİFLETMEK GEREK. BANKAYI VURALIM, KASA DAİRESİNİ AÇIP CEPLERİMİZİ BİRAZ DOLDURALIM.",
["pln_branchbank_cash_cnc_01"] = "STANDART BANKA İŞİ, ÖYLE BİR ŞEY VARSA TABİİ. BURASI NAKİT AÇISINDAN ZENGİN GÖRÜNÜYOR.",
["pln_branchbank_cash_cnc_02"] = "BU BANKADA NAKİT FIRSATI DOĞDU. BU HAFTA GENEL MERKEZE GÖNDERMELERİ GEREKEN PARAYI GÖNDEREMEMİŞLER. HEPİNİZ BİRDEN İÇ GEÇİRMEYİN...",
["pln_branchbank_cash_cnc_03"] = "MAAŞ GÜNÜ BU HAFTA, YANİ NAKİT ŞU ANDA BURADA. BİZ DE ÖYLE.",
["pln_branchbank_cash_cnc_04"] = "BANKA ŞUBESİNDE NAKİT İŞİ. VURALIM ŞURAYI. GÜZEL KAZANDIRIR.",
["pln_branchbank_cash_cnc_05"] = "YENİ BİR GÜN, YENİ BİR BANKA. EMİNİM BİRAZ PARAYI ÖZGÜRLÜĞÜNE KAVUŞTURABİLİRİZ.",
["pln_branchbank_cash_cnc_06"] = "BANKALAR BİZİ SOYARKEN ÜZÜLSEYDİ BEN DE BAŞKA BİR BANKAYI SOYARKEN ÜZÜLÜRDÜM. AMA ÜZÜLMÜYORUM. PARAYI ALALIM.",
["pln_branchbank_cash_cnc_07"] = "VURDUĞUMUZ ONCA BANKAYA YAZIK AMA HEPİMİZİN MASRAFI VAR. WOLF'UN HAYAT TARZI UCUZ DEĞİL. HAREKET VAKTİ.",
["pln_branchbank_cash_stage1_brief_01"] = "KÜÇÜK BİR BANKAYI VURUYORUZ AMA KOLAY OLACAK DEMEK DEĞİL. NAKİT PEŞİNDEYİZ. BANKANIN KASA DAİRESİNE GİRİN, TERMAL MATKABI GETİRİN, KAPIYI AÇIN, PARAYI ÇANTALAYIP MİNİBÜSÜMÜZLE KAÇIN.",
["pln_branchbank_cash_stage1_brief_01b"] = "HA, ADAMIM TERMAL MATKABI BANKANIN ARKASINA SAKLADI. İYİ ŞANSLAR MİLLET.",
["pln_branchbank_cash_stage1_brief_02"] = "BU NAKİT İÇİN YAPILAN BİR BANKA SOYGUNU DİYE KOLAY OLACAK SANMAYIN. BANKANIN KASA DAİRESİNE GİRMELİ, ALARMI ÇALMASINLAR DİYE SİVİLLERİ VE VEZNEDARLARI KONTROL ALTINDA TUTMALISINIZ.",
["pln_branchbank_cash_stage1_brief_02b"] = "MÜDÜRDE DE ANAHTAR OLABİLİR. BOL ŞANS DİLERDİM AMA İHTİYACINIZ YOK, DEĞİL Mİ?",
["pln_branchbank_cash_stage1_brief_03"] = "BU BANKAYI NAKİT İÇİN SOYUYORUZ. GAYET BASİT. TERMAL MATKAPLA KASA DAİRESİ'NE GİRMELİSİNİZ. BİR TON KAMERA VAR. SIK GİTTİĞİM BİR MEKÂNDA BİRİNİN GÜVENLİK ODASINDAN SÖZ ETTİĞİNİ DUYDUM... AMA EMİN DEĞİLİM.",
["pln_branchbank_cash_stage1_brief_03b"] = "GANİMETİ KAÇIŞ ARABASINA TAŞIYIN, KURTULDUK DEMEKTİR. İYİ ŞANSLAR!",
["pln_branchbank_cash_stage1_intro_a_01"] = "TAMAM, KASA DAİRESİ İÇİN GEREKEN TERMAL MATKAP OTOPARKTA BİR YERDE. BASKINA BAŞLAMADAN ÖNCE ALIN. SONRA KASA DAİRESİNE GİRİŞEBİLİRSİNİZ. KAMERALARA VE BANKA ÇALIŞANLARINA DİKKAT EDİN. İÇERİ GİRMEDEN ÖNCE ÖDEVİNİZİ YAPIN VE UNUTMAYIN: NAKİT KRALDIR.",
["pln_branchbank_cash_stage1_intro_a_02"] = "TAMAM MİLLET, ADAMIM BANKA KASA DAİRESİ İÇİN TERMAL MATKABI OTOPARKA SAKLADI. ÖNCE ONU ALIN. MUHAFIZLARA DİKKAT EDİN, KAMERALARI KOLLAYIN; KAMERA VARSA GENELDE BİR GÜVENLİK ODASI DA VARDIR... PARA VAKTİ.",
["pln_branchbank_deposit_cnc_05"] = "YEREL GİRİŞİMCİLERDEN BİRİNİN KİRALIK KASALARI DOLDURDUĞUNU DUYDUM. BENCE BİR GÖZ ATALIM.",
["pln_branchbank_deposit_cnc_06"] = "SIRLARI KİM SEVMEZ, DEĞİL Mİ? ÖNÜMÜZDE İNCELENECEK SIRLARLA DOLU BİR BANKA KASA DAİRESİ VAR.",
["pln_branchbank_deposit_cnc_07"] = "İYİ Kİ DOĞDUNUZ. YENİ DOLDURULMUŞ KİRALIK KASALARLA DOLU BİR KASA DAİRESİ. KİM VAR?",
["pln_branchbank_depositbox_a_intro_a_01"] = "BİRKAÇ KİRALIK KASA AÇMA FIRSATIMIZ VAR GİBİ.",
["pln_branchbank_depositbox_a_intro_a_02"] = "BU BANKADA BİR KİRALIK KASA FIRSATI VAR. İÇERİDEN BİLGİM VAR.",
["pln_branchbank_depositbox_a_intro_a_03"] = "KİRALIK KASA İŞLERİNİ SEVDİĞİMİ BİLİRSİNİZ. BU DA GÜZEL GÖRÜNÜYOR...",
["pln_branchbank_depositbox_a_intro_a_04"] = "BU BANKADA ÇOK DEĞERLİ BİR EŞYA OLABİLİR. BUNU DOĞRULAYAN SİGORTA BELGELERİ BENDE.",
["pln_branchbank_depositbox_brf_speak_01"] = "HARVEST & TRUSTEE BANKALARINDAN BİRİNDE KİRALIK KASALARA BÜYÜK TALEP OLDUĞUNU DUYDUM. ESKİDEN, ŞEY, SOSYAL OLARAK GÖRÜŞTÜĞÜM BİR GİŞE GÖREVLİSİNDEN. BENCE KASA DAİRESİNE GİRİP O KASALARI TAMTAKIR BIRAKMALIYIZ... VAR MISINIZ?",
["pln_branchbank_depositbox_brf_speak_02"] = "YEREL TRUSTEE BANKASINDA BİRİ BİR SÜRÜ KİRALIK KASA TUTMUŞ GİBİ GÖRÜNÜYOR. İÇLERİNDE NE OLDUĞUNU BİLMİYORUM. BUNU NASIL BİLDİĞİMİ DE SORMAYIN AMA BENCE BU BANKA İŞİNİ KAÇIRMAMALIYIZ.",
["pln_branchbank_depositbox_brf_speak_02b"] = "ŞU KASA DAİRESİNE GİRELİM.",
["pln_branchbank_depositbox_stage1_brief_01"] = "ŞİMDİ BANKANIN KASA DAİRESİNE GİRİYORUZ. BU İŞ KİRALIK KASALARLA İLGİLİ. İÇERİ GİRİP KASA DAİRESİNİ MATKAPLA DELMENİZ GEREK. ÖNCE BANKAYI KOLAÇAN EDİN. HER YER GÜVENLİK KAMERASI VE ELİ TETİKTE MUHAFIZ DOLU.",
["pln_branchbank_depositbox_stage1_brief_01b"] = "KASA DAİRESİ'Nİ TERMAL MATKAPLA AÇIN. SONRA KİRALIK KASALARI AÇIN, TESTERE İSTEYEBİLİRSİNİZ. ARDINDAN GANİMETİ KAÇIŞ MİNİBÜSÜNE TAŞIYIN.",
["pln_branchbank_depositbox_stage1_brief_02"] = "TAMAM, BU BİR BANKA SOYGUNU AMA HEDEFİMİZ KİRALIK KASALAR, YANİ BİRAZ FARKLI. İÇERİ GİRİN, MUHAFIZLARA VE KAMERALARA DİKKAT EDİN, KASA DAİRESİNİ MATKAPLA AÇIN, SONRA KİRALIK KASALARDA NE VARSA ALIN.",
["pln_branchbank_depositbox_stage1_brief_02b"] = "İHTİYACIMIZ KADARINI ALIN AMA ŞANSLI HİSSEDİYORSANIZ DAHA FAZLASINI DA ALIN. SONRA ÇANTALAYIP KAÇIŞ MİNİBÜSÜNE GİDİN. HADİ YAPALIM ŞU İŞİ!",
["pln_branchbank_depositbox_stage1_intro_a_01"] = "TAMAM MİLLET, KUSURSUZ BİR İŞ İSTİYORUM. ÖNCE MATKABI OTOPARKTAN ALIN. SONRA İÇERİ GİRİP KASA DAİRESİ'NE YÖNELİN. GÜVENLİKÇİLERE VE KAMERALARA DİKKAT EDİN. ",
["pln_branchbank_depositbox_stage1_intro_a_01b"] = "SİVİLLERİN AKLINA FİKİR GELEBİLİR. İZİN VERMEYİN. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_branchbank_depositbox_stage1_intro_a_02"] = "TAMAM MİLLET, BAĞLANTIM SAĞ OLSUN, BANKA KASA DAİRESİNİ AÇMAK İÇİN GEREKEN TERMAL MATKABI OTOPARKTA BİR YERE SAKLAMIŞ. ALIN, SONRA KASA DAİRESİNE GİRİŞİN.",
["pln_branchbank_depositbox_stage1_intro_a_02b"] = "DİKKATLİ OLMANIZI ÖNERİRİM; BU BANKA OLDUKÇA KALABALIK. BÜTÜN KİRALIK KASALARI BOŞALTIP HEPİMİZİ SEVİNDİRİN.",
["pln_branchbank_gold_a_intro_a_01"] = "UFAK BİR FARKI OLAN BANKA ŞUBESİ İŞİ. FARKIMIZ ALTIN. KÜLÇELER YANİ. İŞİMİZİ YAPALIM.",
["pln_branchbank_gold_a_intro_a_02"] = "TAMAM, STANDART BİR İŞ AMA BU SEFER ALTIN KAPLAMA, NE DEMEK İSTEDİĞİMİ ANLADIYSANIZ. ",
["pln_branchbank_gold_a_intro_a_03"] = "TAMAM, STANDART BANKA SOYGUNU AMA ALTIN SEVKİYATI GÜNÜNDE GİDİYORUZ. LİKİT KALMAK GEREK, DEĞİL Mİ?",
["pln_branchbank_gold_a_intro_a_04"] = "EKİP, BU HABER DAHA YENİ GELDİ. BİZİ BEKLEYEN BİR ALTIN DEPOSU VAR. ",
["pln_branchbank_gold_a_intro_a_05"] = "MİLLET, BENCE BU İŞ ALTIN MADENİ. NEREDEYSE GERÇEK ANLAMIYLA.",
["pln_branchbank_gold_a_intro_a_06"] = "İÇERİDEKİ ADAMIM BU İŞTE PARANIN RENGİNİN ALTIN SARISI OLDUĞUNU SÖYLÜYOR.",
["pln_branchbank_gold_a_intro_a_07"] = "ALTIN, ALTIN, ALTIN. HADİ KASA DAİRESİ'NDE KAZI YAPALIM MI?",
["pln_branchbank_gold_brf_speak_01"] = "ALTINLA YANLIŞ YAPMAZSINIZ. THE HARVEST & TRUSTEE BANKASI BÜYÜK BİR MEVDUATLA LİKİDİTESİNİ ARTIRMAYA ÇALIŞIYOR. YARARLANMAMIZ GEREKEN BİR ŞEY, SİZCE DE ÖYLE DEĞİL Mİ?",
["pln_branchbank_gold_brf_speak_01b"] = "KASA DAİRESİNE GİRİP ALTINIMIZI ÇIKARALIM.",
["pln_branchbank_gold_brf_speak_02"] = "THE HARVEST & TRUSTEE BANKASINA GÜNEY AFRİKA'DAN BÜYÜK BİR ALTIN SEVKİYATI GELDİ. BENCE ORTADAN KAYBOLMASINI SAĞLAMALIYIZ. PEK ÖZLEYECEKLERİNİ SANMIYORUM.",
["pln_branchbank_gold_brf_speak_02b"] = "KUŞANIN DA O KASA DAİRESİNİ DELELİM. KENDİMİZİ ZENGİN CÜCELER GİBİ HİSSETMEK İSTİYORUM. ",
["pln_branchbank_gold_brf_speak_03"] = "BÖYLE İSTİKRARSIZ ZAMANLARDA GERÇEKTEN GÜVENEBİLECEĞİNİZ TEK ŞEY ALTINDIR. EKONOMİK GELECEĞİMİZİ SAĞLAMLAŞTIRMAYA KİM VAR? THE HARVEST & TRUSTEE BANKASININ KASA DAİRESİ BİZİ BEKLİYOR.",
["pln_branchbank_gold_brf_speak_03b"] = "VAR MISINIZ? ÇÜNKÜ BİR BAĞLANTIM, KAYBOLMASI ÇOK YAZIK OLACAK BİR GÜNEY AFRİKA ALTIN SEVKİYATININ YENİ GELDİĞİNİ SÖYLÜYOR...",
["pln_branchbank_gold_stage1_brief_01"] = "DEDİĞİM GİBİ, ALTIN İÇİN BANKA SOYGUNU. KÜÇÜK BANKA AMA GÜVENLİĞİ VE MÜŞTERİSİ ÇOK. İŞLER KÖTÜYE GİTMESİN DİYE ÇOK UĞRAŞACAKSINIZ. KASA DAİRESİ'Nİ DELİN. KAT PLANLARINA GÖRE ARKA TARAFTA.",
["pln_branchbank_gold_stage1_brief_01b"] = "GANİMETİ ÇANTALAYIN, ALTININ AĞIR OLDUĞUNU UNUTMAYIN VE KAÇIŞ ARABASINI GÖNDERMEMİ BEKLEYİN. ANLAŞILDI MI? HA, ADAMIM KASA DAİRESİ'NE GİRMEK İÇİN GEREKEN TERMAL MATKABI ARKA TARAFA BIRAKTI. HADİ BAŞLAYALIM.",
["pln_branchbank_gold_stage1_brief_02"] = "ALTIN GİBİSİ YOK. BU İŞTE ÇOK ÇALIŞACAKSINIZ. BANKAYA GİRİN, İÇERİYİ KONTROL ALTINA ALIN, KASA DAİRESİ'Nİ TERMAL MATKAPLA AÇIN... ADAMIMA SİZİN İÇİN BIRAKTIRMAYA ÇALIŞACAĞIM.",
["pln_branchbank_gold_stage1_brief_02b"] = "SONRA ALTINLARI ÇIKARIN. AĞIRDIR, GÜÇLÜ İNSANLAR GETİRİN. GANİMETİ KAÇIŞ MİNİBÜSÜNE TAŞIYIN; EN AZINDAN TAŞIYABİLECEĞİNİZİ DÜŞÜNDÜĞÜNÜZ KADARINI. İYİ ŞANSLAR!",
["pln_branchbank_gold_stage1_brief_03"] = "ALTIN DOLU BİR BANKA SOYGUNUNA GİRİYORUZ. HAREKETE GEÇMEDEN ETRAFA BAKMAK AKILLICA OLUR, GÜVENLİK SIKI. SONRA İÇERİ GİRİP KASA DAİRESİNİ MATKAPLA AÇIN. ALTINI ÇANTALARA DOLDURUN; UNUTMAYIN, AĞIRDIR.",
["pln_branchbank_gold_stage1_brief_03b"] = "SONRA KAÇIŞ MİNİBÜSÜNE DÖNÜN VE BAM, ZENGİNİZ! ZARAFETLE YAPIN.",
["pln_branchbank_gold_stage1_intro_a_01"] = "BANKADA KEŞİF YAPIN. ADAMIM BANKANIN ARKA TARAFLARINDA BİR YERE TERMAL MATKAP BIRAKTI, BULUN. SONRA İÇERİ GİRİP KASA DAİRESİNDE HÜNERİNİZİ GÖSTERİN. ALTIN SİZİ BEKLİYOR.",
["pln_branchbank_gold_stage1_intro_a_02"] = "TAMAM MİLLET, İÇERİDEKİ ADAMIM KASA DAİRESİ İÇİN GEREKEN TERMAL MATKABI ARKA TARAFA SAKLADI. ETRAFI KOLAÇAN EDİP BULUN. HAZIR OLUNCA KASA DAİRESİ'NE YÖNELİN. BU İŞ ALTIN GİBİ OLACAK.",
["pln_branchbank_gold_stage1_intro_a_03"] = "TAMAM, BU İŞ İÇİN TERMAL MATKAP GEREKECEK. ADAMIM BANKANIN ARKA TARAFINA SAKLADI. ALIP KASA DAİRESİNDE İŞE KOYULUN. GÜVENLİK KAMERALARI VE BİR SÜRÜ SİVİL OLDUĞUNU UNUTMAYIN. GİDİP ALTINI KAZANIN, MİLLET.",
["pln_branchbank_random_brf_speak_01"] = "TAMAM EKİP, EKİPMANINIZI HAZIRLAYIN. EN İYİ YAPTIĞIMIZ İŞ BU, BANKA SOYGUNU. GANİMET ÇANTALARINI KONTROL EDİN, CEP TELEFONLARINI EVDE BIRAKIN, ELDİVENLERİ ALIN, SİLAHLARI DOLDURUN VE PARAYI ALMAYA HAZIR OLUN.",
["pln_branchbank_random_brf_speak_01b"] = "VURMAMIZ GEREKEN BİR BANKA KASA DAİRESİ VAR... ",
["pln_branchbank_random_brf_speak_02"] = "TAMAM EKİP. NASIL OLDUĞUNU BİLİYORSUNUZ, BANKA BASKINI. TELEFONLARI BIRAKIN, ZİHNİNİZİ TAM ALARMA ALIN, ELDİVENLERİ GEÇİRİN. BU BANKA ŞUBESİNİ VURACAĞIZ. ŞEHRİN HER YERİNDELER.",
["pln_branchbank_random_brf_speak_02b"] = "HARVEST & TRUSTEE. BAĞLANTILARIMA GÖRE ÇOK BEREKETLİ. GİRİP ÇIKACAĞIZ. VAR MISINIZ?",
["pln_branchbank_random_brf_speak_03"] = "MİLLET, BUNU MUHTEMELEN BİR DÜZİNE KEZ YAPMIŞSINIZDIR. 5. CADDE'DEKİ HARVEST & TRUSTEE BANK'İ VURUYORUZ. İÇİNDE NE VAR BİLMİYORUM AMA GÜZEL OLACAĞINI BİLİYORUZ. KASA DAİRESİNİ AÇIP TÜYERİZ. VAR MISINIZ?",
["pln_branchbank_random_brf_speak_04"] = "TAMAM MİLLET, ADAMIM BANKAYI VURMAK İÇİN UYGUN BİR ZAMAN OLDUĞUNU SÖYLÜYOR. ANLAŞILAN HARVEST & TRUSTEE BANKA MÜDÜRÜ AĞZINI KAPALI TUTMALIYMIŞ. İÇERİDE HER ŞEY OLABİLİR.",
["pln_branchbank_random_brf_speak_04b"] = "DEVLET SIRLARI, KİRLİ ÇAMAŞIRLAR, HOPE DİAMOND... ASLA BİLEMEZSİNİZ. BANKAYI VURUP ÖĞRENELİM, NE DERSİNİZ?",
["pln_branchbank_random_stage1_brief_01"] = "THE HARVEST & TRUSTEE ORTA BÜYÜKLÜKTE BİR BANKA ŞUBESİ. KASA DAİRESİ ARKADA, BİRKAÇ FARKLI GİRİŞİ VAR. ÖNCE KEŞİF YAPIN... KASA DAİRESİNE GİRECEK, MATKAPLA AÇACAK, İÇİNDEKİLERİ ÇIKARIP KAÇIŞ ARABASINA TAŞIYACAKSINIZ.",
["pln_branchbank_random_stage1_brief_01b"] = "ADAMIM İŞ İÇİN GEREKEN TERMAL MATKABI ARKA TARAFA BIRAKACAK. İYİ ŞANSLAR.",
["pln_branchbank_random_stage1_brief_02"] = "THE HARVEST & TRUSTEE'NİN GÜVENLİĞİ ZAYIF, BURADA BİZİM İÇİN BİR FIRSAT GÖRÜYORUM. KEŞİF YAPIP AÇIKLARINI BULUN. TERMAL MATKAPLA KASA DAİRESİNE GİRMENİZ, İÇİNDEKİLERİ ÇANTALAYIP KAÇIŞ ARABASINA TAŞIMANIZ GEREKECEK. AKLINIZI KULLANIN, AÇGÖZLÜLÜK ETMEYİN... İYİ ŞANSLAR MİLLET.",
["pln_branchbank_random_stage1_brief_02b"] = "TERMAL MATKAPLA KASA DAİRESİNE GİRMENİZ, İÇİNDEKİLERİ ÇANTALAYIP KAÇIŞ ARABASINA TAŞIMANIZ GEREKECEK. AKLINIZI KULLANIN, AÇGÖZLÜLÜK ETMEYİN... İYİ ŞANSLAR MİLLET.",
["pln_branchbank_random_stage1_brief_03"] = "BU HARVEST & TRUSTEE ŞUBELERİ SİZİN GİBİLER İÇİN KOLAY LOKMA. ZAYIF NOKTASINI BULMAK İÇİN BANKAYI KOLAÇAN EDİN.",
["pln_branchbank_random_stage1_brief_03b"] = "KAMERALARA DİKKAT EDİN. BU ŞUBELERDE GENELLİKLE KAMERALARI KAPATABİLECEĞİNİZ GÜVENLİK ODALARI OLUR. KASA DAİRESİNE GİRMENİZ, GANİMETİ ÇANTALAMANIZ VE KAÇIŞ ARABASINA TAŞIMANIZ GEREKECEK.",
["pln_branchbank_random_stage1_brief_03c"] = "AKLINIZI KULLANIN, AÇGÖZLÜLÜK ETMEYİN. ADAMIM BANKA KASA DAİRESİ İÇİN TERMAL MATKABI ARKA TARAFA BIRAKTI. İYİ ŞANSLAR MİLLET.",
["pln_branchbank_random_stage1_brief_04"] = "BU HARVEST & TRUSTEE ŞUBESİNİN ZAYIF NOKTALARI VAR. NEREDE OLDUKLARINI KEŞFEDİN. TERMAL MATKAPLA KASA DAİRESİ'NE GİRİP İÇİNDE NE VARSA ÇANTALAMALI, KAÇIŞ ARABASINA GERİ TAŞIMALISINIZ. AKLINIZI KULLANIN, AÇGÖZLÜ OLMAYIN. UNUTMAYIN, BANKA KAMERALARININ GENELDE GÜVENLİK ODASI OLUR AMA BUNU BİLİYORSUNUZDUR. BOL ŞANS MİLLET!",
["pln_branchbank_random_stage1_intro_a_01"] = "TAMAM, BANKA BU. ÖNCE MEKÂNI KOLAÇAN ETMENİZİ, SONRA ARKA OTOPARKTA BİR YERLERDEKİ TERMAL MATKABI ALMANIZI ÖNERİRİM. KASA DAİRESİNİ İSTEDİĞİNİZ GİBİ AÇIN. GENELLİKLE BİR GÜVENLİK ODASI OLUR, DİKKATLİ OLUN.",
["pln_branchbank_random_stage1_intro_a_02"] = "SOYGUN VAKTİ. OTOPARKA SAKLANAN TERMAL MATKABI ALIN. SONRASI SİZE KALMIŞ. BURADAN NE ÇIKARACAĞIMIZI BİLMİYORUM AMA UNUTMAYIN: SİVİLLERİ KONTROL ALTINDA TUTUN, ALARM YA DA TELEFON KULLANMALARINA İZİN VERMEYİN. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_branchbank_random_stage1_intro_a_03"] = "HERKES İŞİN NASIL YAPILDIĞINI BİLİYOR. ADAMIM TERMAL MATKABI OTOPARKA BIRAKTI, İÇERİ GİRMEDEN ÖNCE ONU ALIN. BİRAZ KEŞİF YAPMAK AKILLICA OLUR.",
["pln_branchbank_random_stage1_intro_a_03b"] = "HAZIR OLUNCA KASA DAİRESİ'Nİ DELİN. BURADA NE VAR BİLMİYORUM AMA ŞANSIMIZI BEĞENİYORUM.",
["pln_branchbank_regular_a_intro_a_01"] = "BANKA SOYMA VAKTİ MİLLET. MASKELERİ TAKIN DA NE VARMIŞ BAKALIM.",
["pln_branchbank_regular_a_intro_a_02"] = "BANKA SOYMAYA KİM HAZIR? BEN HAZIRIM.",
["pln_branchbank_regular_a_intro_a_03"] = "MİLLET, BU BANKA TAM UYGUN GÖRÜNÜYOR. NE KADAR VAR BİLMİYORUM AMA YÜKLÜ OLMALI.",
["pln_branchbank_regular_a_intro_a_04"] = "GÜZEL BİR BANKA FIRSATI. BİR SÜRE SONRA HEPSİ AYNI GÖRÜNMEYE BAŞLIYORDUR HERHÂLDE. HADİ YAPALIM.",
["pln_branchbank_regular_a_intro_a_05"] = "BU BANKA ŞUBESİ SOYULMAYA HAZIR. BAŞLAYALIM.",
["pln_branchbank_regular_a_intro_a_06"] = "BANKA SOYGUNU VAKTİ MİLLET. SİZE MÜKEMMEL BİR TANE BULDUM.",
["pln_branchbank_stage1_01_any_01"] = "BANKADA KEŞİF YAPIN. ADAMIM TERMAL MIZRAĞI ARAZİDE BİR YERE BIRAKTI... BANKANIN ARKA TARAFINA, BULUN.",
["pln_branchbank_stage1_01_any_02"] = "TAMAM MİLLET, İÇERİDEKİ ADAMIM KASA DAİRESİ İÇİN GEREKEN TERMAL KARGIYI ARKA TARAFA SAKLADI. ETRAFI ARAŞTIRIP BULUN.",
["pln_branchbank_stage1_01_any_03"] = "TAMAM... BU İŞ İÇİN TERMAL MATKAP LAZIM... ADAMIM BANKANIN ARKASINA SAKLADI. ALIP İŞE KOYULUN.",
["pln_branchbank_stage1_02_any_01"] = "TAMAM, ALTIN KASA DAİRESİNDE. ",
["pln_branchbank_stage1_03_any_01"] = "TAMAM, KİRALIK KASALAR İÇİN BURADAYIZ.",
["pln_branchbank_stage1_04_any_01"] = "DOĞRUDAN NAKİT SOYGUNU. NASIL OLDUĞUNU BİLİYORSUNUZ.",
["pln_branchbank_stage1_05_any_01"] = "BANKALARI SEVERİM. BÜTÜN O PARANIN KOKUSUNU.",
["pln_branchbank_stage1_05_any_02"] = "KİM BİRAZ BANKACILIK YAPMAK İSTER?",
["pln_branchbank_stage1_05_any_03"] = "HERKES KÜÇÜK BİR PARA ÇEKME İŞLEMİNE HAZIRLANSIN.",
["pln_branchbank_stage1_06_any_01"] = "AÇILDI! PARAYI ÇANTALAYIN!",
["pln_branchbank_stage1_07_any_01"] = "KİRALIK KASALARDAN BİRKAÇINA BAKMAK İSTEYEBİLİRSİNİZ. DEĞERLİ BİR ŞEY OLABİLİR.",
["pln_branchbank_stage1_08_any_01"] = "TAMAM, MİNİBÜSE GÖTÜRÜN. HEMEN KÖŞEDE.",
["pln_branchbank_stage1_09_any_01"] = "TAMAM, 3 TANE DAHA, SONRA BURADAN ÇIKABİLİRİZ.",
["pln_branchbank_stage1_10_any_01"] = "HADİ ARTIK, 1 TANE DAHA.",
["pln_branchbank_stage1_11_any_01"] = "TAMAM, ARTIK GİDEBİLİRİZ AMA YAPABİLİYORSANIZ HEPSİNİ ALIN.",
["pln_branchbank_stage1_12_any_01"] = "GÖRÜNÜŞE GÖRE BÜYÜK İKRAMİYEYİ VURDUK!",
["pln_branchbank_stage1_12_any_02"] = "BURASI RESMEN ALTIN MADENİ, DEĞİL Mİ?",
["pln_branchbank_stage1_13_any_01"] = "TAMAM, MİNİBÜSE GÖTÜRÜN. TAM SOKAĞIN KARŞISINDA.",
["pln_branchbank_stage1_14_any_01"] = "POLİSLER AZ ÖNCE GELDİ!",
["pln_branchbank_stage1_15_any_01"] = "İÇERİDE İYİ MİSİNİZ?",
["pln_branchbank_stage1_15_any_02"] = "ÇANTALAYIN!",
["pln_branchbank_stage1_15_any_03"] = "TAMAM, KASA DAİRESİ AÇILDI!",
["pln_branchbank_stage1_15_any_04"] = "O ALTINI PAKETLEYİN!",
["pln_branchbank_stage1_15_any_05"] = "AÇILDI! ALTINI ÇANTALAYIN!",
["pln_branchbank_stage1_15_any_06"] = "KASA DAİRESİ AÇILDI! PARAYI ÇANTALAYIN!",
["pln_branchbank_stage1_15_any_07"] = "İÇERİ GİRİN MİLLET, O PARAYI ÇANTALAYIN.",
["pln_branchbank_stage1_15_any_08"] = "KASA DAİRESİ AÇILDI, BAKALIM NE VARMIŞ!",
["pln_branchbank_stage1_15_any_09"] = "İÇERİ GİRİN, NE VAR BAKALIM!",
["pln_branchbank_stage1_16_any_01"] = "PARA VAKTİ. ÇANTALAYIN!",
["pln_branchbank_stage1_17_any_01"] = "BÜYÜK İKRAMİYE... ŞU NAKDE BAKIN... HEMEN ÇIKARIN!",
["pln_branchbank_stage1_17_any_02"] = "AÇILDI... NAKİT YOK... KİRALIK KASALARA GİRİŞİN...",
["pln_branchbank_stage1_18_any_01"] = "ALTIN YOK... NAKİT YOK... KİRALIK KASALARI AÇIN. UMARIM TESTERE GETİRMİŞSİNİZDİR.",
["pln_branchbank_stage1_19_any_01"] = "DAHA FAZLA POLİS GELİYOR.",
["pln_branchbank_stage1_20_any_01"] = "BANKAYA GİRİYORLAR! ",
["pln_branchbank_stage1_21_any_01"] = "ŞU KİRALIK KASALARI UNUTMAYIN MİLLET, İÇLERİNDE GÜZEL ŞEYLER OLABİLİR.",
["pln_branchbank_stage1_22_any_01"] = "SOKAK ŞİMDİLİK TEMİZ!",
["pln_branchbank_stage1_23_any_01"] = "KASA DAİRESİ HÂLÂ AÇILMADI... LANET OLSUN.",
["pln_branchbank_stage1_23_any_02"] = "UMARIM SİGORTALARI VARDIR... ",
["pln_branchbank_stage1_23_any_03"] = "MİLLET, BURADA İŞLERİ İLERLETELİM.",
["pln_branchbank_stage1_24_any_01"] = "UMARIM HER ZAMANKİ GİBİ BECERİKSİZ MÜDAHALE EDERLER... ",
["pln_branchbank_stage1_25_any_01"] = "POLİS BASKIYI ARTIRIYOR...",
["pln_branchbank_stage1_26_any_01"] = "TAVSİYEM, O ÇANTALARI MİNİBÜSE ÇABUCAK TAŞIMANIZ.",
["pln_branchbank_stage1_27_any_01"] = "MİNİBÜS GELDİ MİLLET.",
["pln_branchbank_stage1_28_any_01"] = "SAVAŞ DEĞİL BU MİLLET, GİRİP ÇIKACAĞIZ.",
["pln_branchbank_stage1_29_any_01"] = "TAMAM! YETERİNCE ALDINIZ... YA DA DAHA FAZLASI İÇİN KALABİLİRSİNİZ.",
["pln_branchbank_stage1_30_any_01"] = "DIŞARISI BAYAĞI TATSIZLAŞIYOR. KALMAK İSTEDİĞİNİZE EMİN MİSİNİZ?",
["pln_branchbank_stage1_31_any_01"] = "SOKAĞIN HER YANI POLİS!",
["pln_branchbank_stage1_32_any_01"] = "ÇATIDALAR!",
["pln_branchbank_stage1_32_any_02"] = "BANKANIN İÇİNDELER!",
["pln_branchbank_stage1_33_any_01"] = "İÇERİDELER!",
["pln_branchbank_stage1_33_any_02"] = "O ODAYI KONTROL ALTINDA TUTUN MİLLET.",
["pln_branchbank_stage1_33_any_03"] = "OLDUKLARI YERDE TUTUN.",
["pln_branchbank_stage1_34_any_01"] = "KONTROLÜ ELDEN BIRAKMAYIN.",
["pln_branchbank_stage1_34_any_02"] = "İYİ GİDİYORUZ... İYİ GİDİYORUZ.",
["pln_branchbank_stage1_34_any_03"] = "İÇERİDE GÖRDÜKLERİMİ BEĞENİYORUM.",
["pln_branchbank_stage1_34_any_04"] = "UMUT VERİCİ... ÇOK UMUT VERİCİ...",
["pln_branchbank_stage1_34_any_05"] = "AZ KALDI... HADİ MİLLET... OLUYOR.",
["pln_branchbank_stage1_35_any_01"] = "ARTIK SADECE ZAMAN MESELESİ.",
["pln_branchbank_stage1_35_any_02"] = "...VE EVET, ALARM ÇALDI.",
["pln_branchbank_stage1_35_any_03"] = "LANET OLSUN. ŞİMDİ SANCILI YOLDAN GİDİYORUZ.",
["pln_branchbank_stage1_36_any_01"] = "ŞİMDİ ZOR KISMI.",
["pln_branchbank_stage1_37_any_01"] = "LANET OLSUN! GAZ! GAZ!",
["pln_branchbank_stage1_38_any_01"] = "AÇILDI! ALTINI ÇANTALAYIN!",
["pln_branchbank_stage1_39_any_01"] = "AÇILDI! KİRALIK KASALARI ARAYIN!",
["pln_branchbank_stage1_40_any_01"] = "AÇILDI! BAKALIM NE VARMIŞ!",
["pln_branchbank_stage1_41_any_01"] = "KOCAMAN PARA YIĞINLARI YOK. DEĞERLİ EŞYA İÇİN KİRALIK KASALARI ARAYIN.",
["pln_branchbank_stage1_42_any_01"] = "BİR SÜRÜ PARA! ÇANTALAYIN ÇOCUKLAR!",
["pln_branchbank_stage1_43_any_01"] = "TURNAYI GÖZÜNDEN VURDUK GALİBA! ÇANTALAYIN!",
["pln_branchbank_stage1_44_any_01"] = "TAMAM, MİNİBÜSE GETİRİN, CADDENİN HEMEN KARŞISINDA.",
["pln_branchbank_stage1_80_any_01"] = "TAMAM MİLLET, BANKA ORADA. İÇİNDE NE VAR BİLMİYORUM AMA GÜZEL OLACAK...",
["pln_branchbank_stage1_81_any_01"] = "GÜZEL, SÜRPRİZ GANİMET NAKİT ÇIKTI. ÇANTALAYIN.",
["pln_branchbank_stage1_82_any_01"] = "DİNLEYİN. POLİSLER YAKLAŞIYOR. 20 SANİYEYE BURADALAR.",
["pln_branchbank_stage1_83_any_01"] = "MİLLET, TERMAL MATKAP. GİDİP ALIN.",
["pln_branchbank_stage1_84_any_01"] = "TAMAM, HARİKA. ŞİMDİ O ŞEYİ KASA DAİRESİ'NİN KAPISINA GÖTÜRÜN.",
["pln_branchbank_stage1_85_any_01"] = "GÜZEL. ŞİMDİ ÇALIŞTIRIN.",
["pln_branchbank_stage1_86_any_01"] = "İŞTE BAŞLIYORUZ. BİRKAÇ DAKİKAYA DELER GEÇERİZ.",
["pln_branchbank_stage1_87_any_01"] = "HELİKOPTER GELİYOR! ÇATI MİLLET, ÇATI!",
["pln_branchbank_stage1_88_any_01"] = "KESKİN NİŞANCILAR GELİYOR. İÇERİDE KALIN MİLLET!",
["pln_branchbank_stage1_89_any_01"] = "İYİ DÜŞÜNDÜNÜZ, TAHTALAR ONLARI YAVAŞLATIR.",
["pln_branchbank_stage1_end_a_01"] = "HİÇ ŞANSLARI YOKTU. BENCE ULUSAL MUHAFIZLAR BİLE SİZİ DURDURAMAZDI.",
["pln_branchbank_stage1_end_a_02"] = "GANİMET BİZİM. BANKA İŞLERİNDE SEVDİĞİM ŞEY, ÖDÜLÜNÜ ANINDA ALMAK. İYİ İŞ.",
["pln_branchbank_stage1_end_a_03"] = "GÜVENLİ EVİN KASA DAİRESİ BU GECE BİRAZ KALABALIK OLACAK. İYİ İŞ MİLLET.",
["pln_branchbank_stage1_end_a_04"] = "BURADAN SIVIŞMA VAKTİ. GANİMETİ GÜVENLİ EVDE BÖLÜŞÜP HAFTA SONU TATİL YAPALIM.",
["pln_branchbank_stage1_end_a_05"] = "İÇKİLER BENDEN. KLASİK BİR SOYGUNDU.",
["pln_branchbank_stage1_end_a_06"] = "GÜZEL SOYGUNDU. HEPİNİZE TASTEFUL KULÜBÜNDE BİRER İÇKİ BORÇLUYUM. AKŞAM GÖRÜŞÜRÜZ MİLLET.",
["pln_branchbank_stage1_end_a_07"] = "YANİ HİÇBİR ŞEY MÜKEMMEL DEĞİLDİR AMA BU BAYAĞI İYİ HİSSETTİRDİ, SİZCE DE ÖYLE DEĞİL Mİ? HARİKA İŞ.",
["pln_branchbank_stage1_end_a_08"] = "GANİMET ÇANTALARI YERİNDE, PARA BÖLÜŞÜLMEYE HAZIR. HİÇ HAYAL KIRIKLIĞINA UĞRATMIYORSUNUZ. BAYILIYORUM!",
["pln_branchbank_stage1_end_a_09"] = "MUHASEBECİMLE KONUŞUYORUM. ŞEY, BİRAZ ÇAMAŞIR YIKAMAMIZ LAZIM. AFERİN.",
["pln_branchbank_stage1_end_a_10"] = "BAŞARILI BİR BANKA SOYGUNUNDAN DAHA ÇOK SEVDİĞİM TEK ŞEY SONRASINDA İÇİLEN PURODUR. SİZİN İÇİN BİR TANE YAKIYORUM MİLLET.",
["pln_branchbank_stage1_end_a_11"] = "PEK SIK KUSURSUZ DEMEM AMA ŞİMDİ DİYORUM. İYİ İŞ.",
["pln_branchbank_stage1_end_a_12"] = "SİZİN GİBİ DAHA ÇOK EKİP OLSA DÜNYA DEĞERLİ EŞYALARINI BAŞKA YERDE SAKLAMAK ZORUNDA KALIRDI SANIRIM.",
["pln_branchbank_stage1_end_a_13"] = "UMARIM BANKALARI ASLA KALDIRMAZLAR. AMA BÖYLE ÇALIŞIRSANIZ SOYLARINI TÜKETEBİLİRSİNİZ. BAYILIYORUM.",
