["pln_briefing_start_b_04"] = "...PLAN ŞÖYLE.",
["pln_briefing_start_b_05"] = "...DURUM ŞU.",
["pln_briefing_start_b_06"] = "...A PLANI ŞÖYLE.",
["pln_briefing_start_b_07"] = "...İŞİN PÜF NOKTASI BU.",
["pln_briefing_start_b_08"] = "...DURUM ŞÖYLE GÖRÜNÜYOR.",
["pln_briefing_start_b_09"] = "...PLAN ŞÖYLE OLACAK.",
["pln_briefing_start_b_10"] = "...GÖRÜNÜŞ BÖYLE.",
["pln_briefing_start_b_11"] = "...ŞU ANDA DURUM BÖYLE.",
["pln_briefing_start_b_12"] = "...İYİ DİNLEYİN.",
["pln_brn_01_01"] = "FAZLASIYLA YAKINDI. ŞİMDİ DİKİLECEK VAKTİMİZ YOK, EKİP. ONU SANDALYEDEN KALDIRIN DA BU İŞİ BİTİRELİM.",
["pln_brn_01_02"] = "ÇOK DAHA KÖTÜ OLABİLİRDİ. ŞİMDİ BAĞLARINI ÇÖZÜN DE BAŞLAYALIM.",
["pln_brn_01_03"] = "TAMİRCİYİ TAM ZAMANINDA KURTARDINIZ. ŞİMDİ SANDALYEDEN KALDIRIN DA MOTORU TOPLASIN.",
["pln_brn_02_01"] = "TAMİRCİ RUST'IN MOTORU ÜZERİNDE ÇALIŞMAYA BAŞLASIN. DEDİĞİNİ YAPIP İHTİYACI OLANLARI ONA GETİRİN.",
["pln_brn_02_02"] = "TAMİRCİ RUST'IN MOTORUNU BİRLEŞTİRMENİZE YARDIM ETSİN. BU İŞTE ONUN DEDİĞİNİ YAPMALISINIZ.",
["pln_brn_02_03"] = "RUST'IN MOTORUNU TOPLAMAK İÇİN TAMİRCİNİN YARDIMI LAZIM. ONUN DEDİĞİNİ YAPIN.",
["pln_brn_03_01"] = "TAMİRCİ ATÖLYEDEKİ ALETLERİNİN GEREKTİĞİNİ SÖYLEDİ. ORAYA GİDİN.",
["pln_brn_03_02"] = "TAMİRCİ, ATÖLYEDEN BİR TÜR ÖZEL ALET GETİRMENİZİ İSTEDİĞİNİ SÖYLEDİ. ACELE EDİN.",
["pln_brn_03_03"] = "ALETLERİ ATÖLYEDE BULACAKSINIZ. TAMİRCİ ÖYLE SÖYLEDİ.",
["pln_brn_04_01"] = "RUST'IN MOTOSİKLETİ MOTORSUZ GİTMEZ. TAMİRCİ DE KULÜP BİNASINA BAKIN DEDİ. HIZLANIN.",
["pln_brn_04_02"] = "MOTOR BLOĞU OLMADAN MOTOSİKLET ÇALIŞMAZ. TAMİRCİ KULÜP BİNASINDA GÖRDÜĞÜNÜ SÖYLEDİ.",
["pln_brn_04_03"] = "TAMİRCİ, KULÜP BİNASININ İÇİNE MOTOR KOYDUKLARINI GÖRDÜĞÜNÜ SÖYLEDİ. GİDİP BAKIN.",
["pln_brn_05_01"] = "RUST MOTORUNA İLLA KROM BİR KAFATASI İSTİYOR. TARTIŞACAK VAKTİMİZ YOK. KULÜP BİNASINA ULAŞINCA TAMİRCİNİN VERDİĞİ PÜRMÜZÜ KULLANIN.",
["pln_brn_05_02"] = "KROM KAFATASI MI? HER NEYSE, TAMİRCİNİN DEDİĞİNİ YAPIN. KULÜP BİNASINA GİDİP VERDİĞİ KAYNAK LAMBASINI KULLANIN.",
["pln_brn_05_03"] = "TAMİRCİNİN İSTEDİĞİ KROM KAFATASINI ALIN. KULÜP BİNASINA GİRİP SİZE VERDİĞİ ŞALOMAYI KULLANIN.",
["pln_brn_06_01"] = "MOTORCULAR ESKİ BİR SIĞINAKTA EŞYA SAKLIYORMUŞ. TAMİRCİ, MOTOSİKLETİN SELESİNİ ORADA BULACAĞINIZI SÖYLEDİ.",
["pln_brn_06_02"] = "TAMİRCİ SIĞINAĞA GİDİP ONUN İÇİN SELEYİ ALMANIZI SÖYLEDİ.",
["pln_brn_06_03"] = "UNUTMAYIN, TAMİRCİ BİR SIĞINAKTAN SÖZ ETMİŞTİ. MOTORUN SELESİNİ ORADA BULACAKTINIZ.",
["pln_brn_07_01"] = "BENZİN DEPOSU VE EGZOZ BORULARI, EKİP. TAMİRCİ BUNLAR LAZIM DEDİ, ATÖLYEDE BULACAKSINIZ.",
["pln_brn_07_02"] = "TAMİRCİ, ATÖLYEDEN BİR YAKIT DEPOSU VE EGZOZ BORULARI GEREKTİĞİNİ SÖYLEDİ.",
["pln_brn_07_03"] = "ADAMI DUYMADINIZ MI EKİP? ATÖLYEDEN BİR YAKIT DEPOSU VE EGZOZ BORULARI İSTİYOR. ORAYA GİDİP GETİRİN.",
["pln_brn_08_01"] = "ARADIĞIMIZ BU, TAMİRCİYE GÖTÜRÜN!",
["pln_brn_08_02"] = "MÜKEMMEL, ŞİMDİ PARÇAYI TAMİRCİYE GÖTÜRÜN DE ÇALIŞABİLSİN!",
["pln_brn_08_03"] = "HARİKA, GEREKEN PARÇA BU.",
["pln_brn_08_04"] = "İSTEDİĞİ SİZDE. ŞİMDİ ONA GÖTÜRMELİSİNİZ.",
["pln_brn_08_05"] = "İSTEDİĞİ PARÇA BU. BİR ADIM DAHA YAKLAŞTIK EKİP.",
["pln_brn_08_06"] = "MÜKEMMEL, BİR PARÇA ÇANTADA. TAMİRCİYE GERİ GÖTÜRÜN.",
["pln_brn_08_07"] = "BİR PARÇA TOPLANDI. TAMİRCİYE GÖTÜRÜN.",
["pln_brn_09_01"] = "ORAYA GÜZEL GANİMET SAKLAMIŞLAR AMA ARTIK BİZİM. NASIL ÇIKARACAĞIZ?",
["pln_brn_09_02"] = "AH, BİLİYORSUNUZ, O SİLAHLARDAN BİRKAÇINI ALMADAN GİTMİYORUZ. BİR ŞEKİLDE DIŞARI ÇIKARMAMIZ GEREKİYOR...",
["pln_brn_09_03"] = "BU GÜZEL SİLAHLARDAN BİRKAÇINI YANIMIZDA GÖTÜRECEĞİZ. AMA NASIL, MESELE BU...",
["pln_brn_10_01"] = "TAMİRCİNİN İŞİ BİTTİ. DAHA FAZLA GANİMET İSTİYORSANIZ ŞİMDİ ALIN, YOKSA MOTORLARA ATLAYIP ÇIKIN ORADAN. ",
["pln_brn_10_02"] = "ADAMI DUYDUNUZ! YA DAHA FAZLA EŞYA ÇALIN YA DA O MOTOSİKLETE BİNİP SÜRÜN! RÜZGÂR GİBİ SÜRÜN!",
["pln_brn_10_03"] = "BAŞARDI MİLLET. İSTERSENİZ DAHA FAZLA GANİMET TOPLAYIN, İSTERSENİZ MOTORLARA ATLAYIP KAÇIN!",
["pln_brn_11_01"] = "ŞİMDİ DİNLEYİN: POLİS HER AN BÜTÜN ALANI SARACAK. ZAMAN İŞLİYOR! KANAL YOLUNU KULLANIN, ÇABUK!",
["pln_brn_11_02"] = "MİLLET, ORADAN DEFOLUP GİTMELİSİNİZ, HEM DE ÇABUCAK. SWAT EKİPLERİ MEKÂNA ÜŞÜŞECEK VE ÇIKMAK İÇİN TEK ŞANSINIZ BU!",
["pln_brn_11_03"] = "LANET, POLİSLER SİZİ ALMAK İÇİN ELLERİNDEKİ HER ŞEYİ GETİRİYOR. HEMEN GİTMEZSENİZ KUŞATILACAKSINIZ. ACELE EDİP KANAL YOLUNDAN KAÇIN. HEMEN!",
["pln_brn_12_01"] = "DÜMDÜZ SÜRMEYE DEVAM EDİN!",
["pln_brn_12_02"] = "İŞTE BÖYLE! DEVAM EDİN!",
["pln_brn_12_03"] = "SÜRÜN ÇOCUKLAR, SÜRÜN!",
["pln_brn_13_01"] = "KAÇIŞ ORADA! KAPIDAN SÜRÜP GEÇİN, GÜVENDESİNİZ!",
["pln_brn_13_02"] = "MOTORLA KAPIDAN GEÇİN, GÜVENDE OLACAKSINIZ!",
["pln_brn_13_03"] = "O KAPI SİZİN KAÇIŞINIZ!",
["pln_brn_14_01"] = "ŞEY... TAMAM O ZAMAN.",
["pln_brn_14_02"] = "ADAM GERÇEKTEN GAZOZ İSTİYORMUŞ GALİBA...",
["pln_brn_14_03"] = "ASLINDA BEN DE BİRAZ SUSADIM. HEMEN DÖNERİM!",
["pln_ca1_01_01"] = "SİVİL KILIĞINDASINIZ. SİLAH YOK, MASKE YOK; GÜVENLİĞİN DİKKATİNİ ÇEKMİYORSUNUZ. HAZIR OLDUĞUNUZDA EKİPMANINIZI BULUN. HADEME MİCHO BİR YERLERE GİTAR KUTUSU İÇİNDE BIRAKTI.",
["pln_ca1_01_02"] = "UNUTMAYIN, SİVİL HÂLDESİNİZ. YANİ SİLAH VE MASKE YOK. GÖRÜNMEZSİNİZ. İÇERİDEKİ ADAMIMIZ MİCHO, EKİPMANINIZI BİR GİTAR KUTUSUNDA BİR YERE BIRAKTI.",
["pln_ca1_01_03"] = "SİVİL KILIĞINDASINIZ. SİLAHLARINIZ VE MASKELERİNİZ BİR YERE SAKLANDI. ALANA KADAR GÜVENLİĞİN DİKKATİNİ ÇEKMEZSİNİZ.",
["pln_ca1_02_01"] = "TAMAM, POLİS GELİYOR. İLK ADIM, MUHAFIZ ODASINDA C4 ARAMAK.",
["pln_ca1_02_02"] = "TAMAM, FEDERALLER YAKINDA GELİR. SERT VE HIZLI VURMA VAKTİ. MUHAFIZ ODASINDAKİ C4'Ü BULUN.",
["pln_ca1_02_03"] = "POLİS YOLDA, OYALANMAYIN. C4'Ü BULUN! MUHAFIZ ODASINA BAKIN.",
["pln_ca1_03_01"] = "TAMAM, BURAYI HAVAYA UÇURALIM. C4 LİMUZİNDE. ALIN!",
["pln_ca1_03_02"] = "LİMUZİNDEKİ C4'Ü ALIN DA BURAYI PATLATALIM. ACELE EDİN! POLİSLER GELİYOR.",
["pln_ca1_03_03"] = "LİMUZİNDEKİ C4'Ü UNUTMAYIN. DOSTUM, POLİSLER YAKIN. ACELE EDİN!",
["pln_ca1_04_01"] = "UYKU GAZI DA VAR. ALIN. SONRA GEREKECEK.",
["pln_ca1_04_02"] = "HA, ORAYA BİRAZ UYKU GAZI DA KOYUN. GERİDE BIRAKMAYIN.",
["pln_ca1_05_01"] = "ŞİMDİ HANGİ ODANIN HAVALANDIRMASININ GÜVENLİK MERKEZİYLE ORTAK OLDUĞUNU BULMALIYIZ. MUHAFIZLARI BAYILTMAK İÇİN KULLANACAĞIZ. ÖNCE BİNA PLANLARINI ALIN. ARŞİVDE OLMALILAR.",
["pln_ca1_05_02"] = "SIRADA HAVALANDIRMASI GÜVENLİK MERKEZİNE BAĞLI OLAN ODAYI BULMAK VAR. MUHAFIZLARI UYKU GAZIYLA BAYILTMAK İÇİN KULLANABİLİRİZ. YANİ PLANLAR LAZIM. ARŞİVE BAKIN.",
["pln_ca1_06_01"] = "HARİKA! ŞİMDİ BİLİŞİMDE BİR TARAYICI BULUN. PLANLARIN BİR KOPYASINI BANA FAKSLAYIN. O HAVALANDIRMAYI BULURUM.",
["pln_ca1_06_02"] = "ONLAR BUNLAR. ŞİMDİ TARATIP BİR KOPYASINI BANA FAKSLAYIN. DOĞRU HAVALANDIRMAYI BEN BULURUM.",
["pln_ca1_100_01"] = "İŞTE BU... HER NEYSE! TAMAM, BIRAKMA NOKTASI BİR DEPO ODASI. ORAYA GÖTÜRÜP GÜVENCEYE ALIN.",
