["pln_ca1_23_03"] = "ONA İÇKİ DOLDURUN. BİR YUDUM ALINCA EKLEDİĞİMİZ KÜÇÜK ŞEY... EN YAKIN TUVALETE KOŞACAK İŞTE. TAKİP EDİP ANAHTAR KARTI'NI ALIN.",
