["pln_ca1_27_01"] = "KASA DAİRESİNİ AÇMAK İÇİN ÜÇ HANELİ BİR KOD GEREKİYOR. HER HANE BİR MÜDÜRDE VE HER BİRİ BİR BİLGİSAYAR ÇANTASINDA. O KOD BİZE LAZIM. BULUN ONLARI.",
