["pln_ca1_37_03"] = "TAŞIYABİLDİĞİNİZ KADAR C4 ALIN EKİP.",
["pln_ca1_38_01"] = "ŞİMDİ ANA SALONA C4 YERLEŞTİRİN. KASA DAİRESİ HEMEN ALTINDA. PATLATMAK İÇİN İKİ OLASI YER VAR. UMARIM ŞANS TANRIÇASI BİZİMLEDİR!",
["pln_ca1_38_02"] = "ŞİMDİ ANA SALONDAKİ C4'Ü PATLATIN. TAM KASA DAİRESİNİN ÜSTÜNE YERLEŞTİRİN. TAM OLARAK NERESİ OLDUĞUNU SÖYLEMEK ZOR. İKİ OLASI NOKTA VAR. BİRAZ ŞANS İÇİN DUA EDİN.",
