["pln_ca1_39_01"] = "BILE'A İŞARET VERMEK İÇİN FİŞEK YAKIN. AŞAĞI İNMEK İÇİN KOCAMAN BİR MATKAP LAZIM, ONA DA ÖNCE VİNÇ GEREKİYOR. PARÇALARINI O GETİRECEK.",
["pln_ca1_39_02"] = "KASA DAİRESİ AÇIĞA ÇIKTI, ŞİMDİ AŞAĞI DOĞRU DELECEĞİZ. BÜYÜK BİR MATKAPLA. ONA DA VİNÇ GEREKİYOR. HAZIR OLUNCA İŞARET FİŞEĞİYLE BILE'A HABER VERİN.",
