["pln_ch1_35_01"] = "GÜZEL, BUNLARI BEN PATLATIRIM. SİZ ARABALARLA HAZIR OLUN.",
["pln_ch1_35_02"] = "TAMAM, BUNLARI UZAKTAN PATLATACAĞIM. SİZ ARABALARA ODAKLANIN.",
["pln_ch1_35_03"] = "HARİKA. BAIN BABANIZ BUNLARLA İLGİLENİR. ŞİMDİ ANAHTARLARA DÖNELİM.",
["pln_ch1_brf_01_01"] = "BURADAKİ HEDEFİMİZ TEUER OTOMOTİV. AKŞAM GEÇ SAATTE GALERİLERİNİ VURACAĞIZ. SAKİN OLUR, FAZLA SİVİL OLMAZ. LÜKS BİR YER. AVRUPA VE JAPONYA'DAN YÜKSEK PERFORMANSLI SÜPER ARABALAR İTHAL EDİYORLAR. O ARABALAR MÜHENDİSLİK HARİKASI. ÜSTELİK PAHALILAR; GEORGETOWN'DA BİR EV PARASINDAN SÖZ EDİYORUZ.",
["pln_ch1_cbf_01_01"] = "TEUER BAYİSİ, DOĞU YAKASI'NDA FALCOGİNİ SATAN SAYILI GALERİLERDEN BİRİ. YENİ GÖZDE MODEL LA TROİENNE ELLERİNE YENİ GEÇMİŞ. YURT DIŞINDA BU KÜÇÜK GÜZELE YÜKLÜ PARA ÖDEMEYE HAZIR TANIDIKLARIM VAR. İÇERİ GİRİN, ARABALARA ULAŞIN VE ÇIKARIN. BASİT, DEĞİL Mİ?",
["pln_ch1_cnc_01_01"] = "BU İŞTE ŞEHRİN LÜKS OTOMOBİL GALERİLERİNDEN BİRİNİ VURACAĞIZ. TEUER OTOMOBİL BAYİSİNİ.",
["pln_ch1_cnc_01_02"] = "TEUER GALERİSİNE GİDİYORUZ. LÜKS BİR YER.",
["pln_ch1_cnc_01_03"] = "BU İŞ TEUER GALERİSİNE BASKIN. ÜST SINIF BİR MEKÂN.",
["pln_ch1_cnc_02_01"] = "NADİR BİR İŞ. TEUER GALERİSİNİ VURUN. YENİ MODELLERİ AŞIRIN.",
["pln_ch1_end_01_01"] = "MUHTEŞEM İŞ! BU GÜZEL ARABALAR BİR HAFTA İÇİNDE ARAP ŞEYHLERİNİN ELİNDE OLACAK. İYİ İŞ!",
["pln_ch1_end_01_02"] = "BAŞARDINIZ. BU ARABALAR İÇİN EDERİNDEN FAZLASINI ÖDEYECEK BİRKAÇ RUS PETROL ZENGİNİ PLAYBOY BULDUM. İYİ İŞ ÇIKARDINIZ!",
["pln_ch1_end_01_03"] = "HARİKA İŞ! BU GÜZELLİKLER ÇOK YAKINDA DOĞU AVRUPA SOKAKLARINI YIRTACAK.",
["pln_ch1_intro_01_01"] = "TAMAM, GELDİK. ÇALIŞMA VAKTİ.",
["pln_ch1_intro_01_02"] = "BURADA KENARA ÇEKİN. TAMAM EKİP. HADİ YAPALIM.",
["pln_ch1_intro_01_03"] = "TAMAM, ARABA ÇALMA VAKTİ.",
["pln_ch1_intro_01_04"] = "BU HURDAYLA GELDİK AMA HAVALI BİR ŞEYLE AYRILACAĞIZ.",
["pln_ch1_intro_01_05"] = "KENARA ÇEK. YER BURASI. TEUER AUTOMOTİVES.",
["pln_ch1_intro_01_06"] = "BURAYA PARK ET. TAMAM. İŞTE ORADA. HADİ YAPALIM ŞU İŞİ.",
["pln_chw_01_01"] = "TAMAM MİLLET. ELEPHANT SİZE BRİFİNGİ VERDİ, NEYİN PEŞİNDE OLDUĞUMUZU BİLİYORSUNUZ. BCI BAŞLIĞINI VE BİLGİSAYAR YAZILIMINI BULMAMIZ GEREK. BAŞARIRSANIZ ÇOK PARA KAZANACAĞIZ.",
["pln_chw_01_02"] = "BEYNİNLE DRON KONTROL ETMEK Mİ? TANRIM, YAŞLANIYORUM. NEYSE, BU TEKNOLOJİ ÇOK PARA EDER. MOTORCULARDAN ÇALMALIYIZ.",
["pln_chw_01_03"] = "THE ELEPHANT SİZE BEYİN-BİLGİSAYAR ARAYÜZÜNDEN BAHSETTİ, DEĞİL Mİ? BEYNİNİZLE BİR DRONU KONTROL ETMENİZİ SAĞLAYAN İLERİ TEKNOLOJİ BİR BAŞLIK VE BİR YAZILIMIN PEŞİNDEYİZ. İNANIN, BEN BİLE ZOR İNANIYORUM. NEYSE, RUST'A GÖRE İKİSİ DE ŞU ANDA BU TRENLE TAŞINIYOR.",
["pln_chw_02_01"] = "RUST, MOTORCULARIN ARABALARDAN BİRİNİ ÖN TARAFTA TUTTUĞUNU SÖYLEDİ. ARADIĞIMIZ ŞEYLERİ ORADA KORUYORLAR. ORAYA GİDİN, HİÇBİR ŞEY SİZİ DURDURMASIN.",
["pln_chw_02_02"] = "RUST'A GÖRE OVERKILL MC TEKNOLOJİYİ ÖN VAGONLARDAN BİRİNDE TUTUYOR. OLABİLDİĞİNCE ÇABUK GİDİN, DURMAYIN. FAZLA VAKTİMİZ YOK.",
["pln_chw_02_03"] = "BCI TEKNOLOJİSİNİN TRENİN ÖN TARAFINDAKİ BİR VAGONDA OLMASI GEREKİYOR. HEDEFİNİZ ORASI.",
