["pln_chw_10_01"] = "TAMAM, MALLAR SİZDE. ÖNEMLİ OLAN BU. HEPSİNİ HELİKOPTERE GÖTÜRME VAKTİ. ACELE EDİN, BILE BEKLİYOR.",
["pln_chw_10_02"] = "ALDINIZ. HARİKA. HEPSİNİ HELİKOPTERE TAŞIMA VAKTİ. BILE BEKLİYOR, YOLA KOYULUN!",
["pln_chw_10_03"] = "TEKNOLOJİ ELİMİZDE! HELİKOPTERE DÖNME VAKTİ! BILE'I BEKLETMEYİN.",
