["pln_chw_11_03"] = "ACELE EDİP HELİKOPTERE DÖNÜN DE BCI TEKNOLOJİSİNİ GÜVENE ALALIM.",
["pln_chw_12_01"] = "TAMAM, BCI TEKNOLOJİSİ ARTIK EMİN ELLERDE. YİNE DE VAGONA DÖNÜP DAHA FAZLA GANİMET ALABİLİRSİNİZ. HEPSİ İYİ PARA EDER.",
["pln_chw_12_02"] = "MÜKEMMEL! BCI TEKNOLOJİSİ GÜVENCEYE ALINDI. İYİ PARA KAZANMAK İSTİYORSANIZ DAHA FAZLA GANİMET ALMAYA VAKTİNİZ VAR.",
["pln_chw_12_03"] = "BİR ŞEY TERS GİTMEDEN ÇIKMANIZI TERCİH EDERİM AMA DAHA FAZLA GANİMET İÇİN DÖNMEK İSTERSENİZ ANLARIM.",
["pln_chw_13_01"] = "HEPSİ TAMAM. BU SÜSLÜ ŞEYLERDEN İYİ PARA KAZANACAĞIZ. HELİKOPTERE DÖNÜP HEMEN ORADAN ÇIKIN.",
["pln_chw_13_02"] = "İYİ İŞ. FAZLADAN PARA HER ZAMAN İYİDİR. ŞİMDİ HELİKOPTERE KOŞUP ORADAN ÇIKIN.",
["pln_chw_13_03"] = "HER ŞEYİ SİLİP SÜPÜRDÜNÜZ. İYİ İŞ. ŞİMDİ DEFOLUP GİTME VAKTİ.",
["pln_chw_14_01"] = "EKİP! ÇIKIN ORADAN! NE HALT EDİYORSUNUZ?",
