["pln_chw_14_03"] = "GİTME VAKTİ GELDİ DEDİM!",
["pln_chw_15_01"] = "LANET OLSUN! POLİSLER İLERİDE RAYLARI KAPATMIŞ. ORAYA ULAŞMADAN GİTMENİZ GEREK DEMEK. BCI TEKNOLOJİSİNİ ALIP HELİKOPTERE KOŞUN!",
["pln_chw_15_02"] = "HEY! POLİS İLERİDE TRENİ DURDURACAK. BCI TEKNOLOJİSİNİ ALIP ORADAN DEFOLMALISINIZ!",
["pln_chw_15_03"] = "DİNLEYİN! POLİSLER İLERİDE RAYLARI KAPATMAYA BİR SÜRÜ ADAM GETİRİYOR. GERÇEKTEN GİTMELİSİNİZ. BCI TEKNOLOJİSİNİ ALIP BILE'A DÖNÜN!",
["pln_chw_16_01"] = "TREN POLİS BARİKATINA HIZLA YAKLAŞIYOR. GANİMETİ GÜVENE ALIP ÇIKMANIZ İÇİN SİZE EN FAZLA İKİ DAKİKA VERİYORUM.",
["pln_chw_16_02"] = "TREN BARİKATA VARANA KADAR YAKLAŞIK İKİ DAKİKANIZ VAR. DUYDUNUZ MU? İKİ DAKİKA.",
["pln_chw_16_03"] = "TRENİN ŞU ANKİ HIZIYLA BARİKATA ULAŞMANIZA YAKLAŞIK İKİ DAKİKA VAR. YANİ HER ŞEYİ GÜVENCEYE ALIP AYRILMAK İÇİN İKİ DAKİKANIZ VAR!",
