["pln_chw_18_03"] = "OTUZ SANİYE MİLLET! ACELE EDİN LAN!",
["pln_chw_19_01"] = "O PETROL VARİLLERİ YOLU KAPATIYOR. KAYIŞLARI BULUP ÇÖZÜN. BAŞKA YOL ARAMAYA VAKTİMİZ YOK.",
["pln_chw_19_02"] = "KAHRETSİN! O PETROL VARİLLERİ YOLU KAPATIYOR. KAYIŞLARI ÇÖZEBİLİYOR MUSUNUZ BAKIN. ÇABUK OLUN.",
["pln_chw_19_03"] = "O VARİLLERİ KALDIRMALISINIZ, HEM DE ÇABUCAK. KAYIŞLARI FALAN ÇÖZÜN.",
["pln_chw_20_01"] = "BU KAPIDAN GEÇMEK İÇİN PÜRMÜZ KULLANMANIZ GEREKECEK. ÇABUK OLUN.",
["pln_chw_20_02"] = "KAPIYI GEÇMEK İÇİN ŞALOMAYI KULLANIN!",
["pln_chw_20_03"] = "ŞALOMANIZ VAR, DEĞİL Mİ? O KAPIDA KULLANIN.",
["pln_chw_21_01"] = "KAPI KİLİTLİ. İLERLEYEBİLMEMİZ İÇİN BAŞKA ÇIKIŞ BULMAYA ÇALIŞIN.",
["pln_chw_21_02"] = "KAHRETSİN, KAPI DIŞARIDAN KİLİTLENMİŞ OLMALI. BELKİ BAŞKA ÇIKIŞ VARDIR.",
["pln_chw_21_03"] = "KAPI DIŞARIDAN KİLİTLİ GİBİ. ETRAFA BAKIP BAŞKA BİR ÇIKIŞ YOLU BULMAYA ÇALIŞIN.",
["pln_chw_22_01"] = "LANET, BÜYÜK SİLAHLARINI GERÇEKTEN SONA SAKLAMIŞLAR. GÖRÜNÜŞE GÖRE ONDA ANAHTAR KARTI VARDI.",
["pln_chw_22_02"] = "VAY! BUNU BEKLEMİYORDUM. KAPI İÇİN BİR ŞEYİ VAR MIYDI, BAKIN.",
["pln_chw_22_03"] = "TANRIM, O KALTAK ŞAKA YAPMIYORMUŞ, DEĞİL Mİ? DÜŞÜRDÜĞÜ ANAHTAR KARTI'NI ALIN.",
["pln_cp1_01_01"] = "HERKES SAĞ SALİM İNDİ Mİ? HARİKA. KAZA YERİNİ BULUN, PİLOT HÂLÂ HAYATTA MI BAKIN. HAYATTAYSA GÜVENLİ BİR YERE GÖTÜRMENİZ GEREK. BİR AN ÖNCE ALMASI İÇİN HELİKOPTER GÖNDERECEĞİM. BURADA BİR UÇAK KAZASI DİKKAT ÇEKMEDEN KALMAZ, MİSAFİR BEKLEYEBİLİRSİNİZ. HIZLI ÇALIŞIN.",
["pln_cp1_01_02"] = "HERKES İYİ Mİ? O ZAMAN YÜRÜYÜN! KAZA YERİNİ VE O SARHOŞ PİLOTU BULMANIZ GEREK, BOYNUNU BİR AĞACA DOLAMADIYSA TABİİ. GÜVENLİ BİR YERE GÖTÜRÜNCE TAHLİYEYİ AYARLARIZ.",
["pln_cp1_01_03"] = "KIRIK BACAK YOK MU? GÜZEL. ORMANA GİRİP UÇAĞI BULUN. TAHMİNİMCE PİLOT DA YAKINDADIR. GÜVENLİ BİR YERE GÖTÜRÜN, HAVADAN ALIRIZ. HAREKETE GEÇİN!",
["pln_cp1_02_01"] = "İŞTE ORADA! UYANDIRIP GÜVENLİ BİR YERE GÖTÜRÜN. YAKINLARDA BİR KERESTE DEPOSU VAR.",
["pln_cp1_02_02"] = "ADAMIMIZ ORADA. KAFASI BİR MİLYON! ONU ORADAN UZAKLAŞTIRIN. YAKININIZDA TERK EDİLMİŞ BİR KERESTE DEPOSU VAR.",
["pln_cp1_02_03"] = "İŞTE PİLOT. TANRIM, O YAŞLI AYYAŞ UÇAK UÇURMAYI BIRAK, AYAKTA ZOR DURUYOR. GÜVENLİ BİR YERE GÖTÜRÜN. HELİKOPTERİ YOLA ÇIKARACAĞIM.",
["pln_cp1_03_01"] = "DOSTUM, GERÇEKTEN SARHOŞ! O ADAMA EŞLİK ETMEK ZOR OLACAK.",
["pln_cp1_03_02"] = "TANRIM, ADAM ZİLZURNA SARHOŞ. YANINDA KALIN. KENDİNİ SAVUNACAK HÂLİ YOK.",
["pln_cp1_03_03"] = "KANINDAKİ ALKOL %80 OLMALI. YANINDAN AYRILMAYIN, ONA YARDIM EDİN.",
["pln_cp1_04_01"] = "HARİKA! ARTIK GÜVENDE OLDUĞUNA GÖRE ONU ALMAYA BİR HELİKOPTER YOLLUYORUM. YANINDAN AYRILMAYIN.",
["pln_cp1_04_02"] = "O SARHOŞ MORUĞA KAHVE YAPACAK VAKİT YOK. GÜVENDE TUTUN. ŞİMDİ TAHLİYE GÖNDERİYORUM.",
["pln_cp1_04_03"] = "GÜZEL. ONU ALMAK İÇİN HELİKOPTER GÖNDERİYORUM. GÜVENDE TUTUN. ÖYLE SARHOŞ Kİ KURŞUNLARI HİSSEDER Mİ, ŞÜPHELİYİM.",
["pln_cp1_05_01"] = "TAMAM, HELİKOPTER BURADA. PİLOTU GETİRİN!",
["pln_cp1_05_02"] = "TAMAM, DUYDUĞUNUZ HELİKOPTER. ADAMIMIZI ORAYA GÖTÜRÜN.",
["pln_cp1_05_03"] = "HELİKOPTER GELDİ. ONU ORAYA GÖTÜRÜN. KUMANDALARA UZANMASIN DİYE DUA EDİN.",
["pln_cp1_06_01"] = "İYİ İŞ! HELİKOPTER ONU BIRAKIP GERİ KALANINIZI ALMAK İÇİN DÖNECEK. BEKLERKEN ORMANDA BAŞKA PAKETLER ARAYIN.",
["pln_cp1_06_02"] = "HELİKOPTER KALANLARINIZ İÇİN DÖNECEK. ZAMANI İYİ KULLANIN, ÜRÜNÜ ARAYIN. VLAD PAKETLERE SAKLANDIĞINI SÖYLEDİ.",
["pln_cp1_06_03"] = "HELİKOPTER SİZİ ALMAK İÇİN DÖNECEK. BEKLERKEN VLAD'IN PAKETLERİNİ ARASAK NASIL OLUR? GÜZEL BİR EK KAZANÇ ÇIKABİLİR.",
["pln_cp1_07_01"] = "TAMAM, HELİKOPTER GELDİ. BULDUĞUNUZ GANİMETLERİ GÜVENE ALIN. İSTEDİĞİNİZ ZAMAN KAÇABİLİRSİNİZ AMA DIŞARIDA HER ZAMAN DAHA FAZLA GANİMET OLDUĞUNA EMİNİM. KARAR SİZİN.",
["pln_cp1_07_02"] = "HELİKOPTERİNİZ GELDİ. ÇANTALARI YÜKLEYİN. SONRA SIVIŞABİLİR YA DA KALIP DAHA FAZLA GANİMET BULABİLİRSİNİZ. SİZE KALMIŞ.",
["pln_cp1_07_03"] = "HELİKOPTER BURADA. ÇANTALARI YÜKLEYİN. ŞİMDİ GİDEBİLİR YA DA KALIP DAHA FAZLA KOKAİN BULABİLİRSİNİZ. KARAR SİZİN.",
["pln_cp1_08_01"] = "HELİKOPTER GİDİYOR AMA SAKİN OLUN, DÖNECEK. ORMANDA DAHA FAZLA GANİMET ARAYIN. GÜVENDE KALIN.",
["pln_cp1_08_02"] = "TAMAM, HELİKOPTER KALKIYOR. UMARIM BİRAZ GANİMET YÜKLEDİNİZ. YİNE GELECEK. VLAD'IN KOKAİNİNDEN DAHA FAZLA BULMAYA ÇALIŞIN.",
["pln_cp1_08_03"] = "HELİKOPTER GİDİYOR AMA MERAK ETMEYİN, DÖNECEK. BU ARADA O HEDİYELERDEN BİRAZ DAHA BULABİLİYOR MUSUNUZ BAKALIM.",
["pln_cp1_09_01"] = "HELİKOPTERİN YAKINDA GİTMESİ GEREKİYOR. BİNMEK İSTİYORSANIZ ACELE EDİN AMA YAKINDA GERİ DÖNECEK!",
["pln_cp1_09_02"] = "HELİKOPTER KALKMAYA NEREDEYSE HAZIR. ŞİMDİ PARAYI ALIP ÇIKMAK İSTİYORSANIZ ACELE EDİN. YA DA KALIP DAHA FAZLA KOKAİN BULUN.",
["pln_cp1_09_03"] = "HELİKOPTERİN BİRAZ UZAKLAŞMASI GEREKECEK. ŞİMDİ GİTMEYE HAZIRSANIZ BİNİN.",
["pln_cp1_10_01"] = "AZ ÖNCE AĞAÇTAN HEDİYE Mİ DÜŞTÜ? İÇİNDE DAHA FAZLASI TAKILI KALMIŞ GİBİ. BULUP AÇIN.",
["pln_cp1_10_02"] = "AĞAÇTAN BİR HEDİYE DÜŞTÜ GALİBA EKİP. VLAD'IN KOKAİNİNDEN BİRAZ DAHA OLABİLİR. BULUN ONU.",
["pln_cp1_10_03"] = "AĞAÇTAN DÜŞEN KOKAİN DOLU BİR HEDİYE MİYDİ O? NOEL GERÇEKTEN MUCİZELER ZAMANI.",
["pln_cp1_11_01"] = "BİR PAKET DAHA YERE DÜŞTÜ, PALYAÇOLAR. BULMAYA ÇALIŞIN.",
["pln_cp1_11_02"] = "GECE PEK DE SESSİZ DEĞİL. SANIRIM YERE DÜŞEN BİR HEDİYE DAHA DUYDUM. BULUN!",
["pln_cp1_11_03"] = "KULAKLARIM BENİ YANILTIYOR MU, YOKSA VLAD'IN HEDİYELERİNDEN BİRİNİN DAHA YERE DÜŞMESİNİN TATLI SESİNİ Mİ DUYDUM? ARAYIN!",
["pln_cp1_12_01"] = "PİLOT AZ ÖNCE YERE YIĞILDI. LANET OLSUN, UYUYOR MU? UYANDIRMANIZ GEREK!",
["pln_cp1_12_02"] = "PİLOT YERE YIĞILDI. KENDİNDEN GEÇMESİN. HAREKET ETTİRİN!",
["pln_cp1_12_03"] = "PİLOT DÜŞTÜ! YENİDEN AYAĞA KALDIRIN.",
["pln_cp1_13_01"] = "AH DOSTUM, PİLOT YİNE DÜŞTÜ. O İHTİYAR ŞARAPÇIYI UYANDIRIN!",
["pln_cp1_13_02"] = "YETER ARTIK, PİLOT YİNE YERE YIĞILDI. UYANDIRIN!",
["pln_cp1_13_03"] = "İHTİYAR SARHOŞ YİNE YERE SERİLDİ. KALDIRIN ŞUNU.",
["pln_cp1_14_01"] = "HELİKOPTER KERESTE DEPOSUNA GELİYOR, HAZIR OLUN!",
["pln_cp1_14_02"] = "HELİKOPTER KERESTE DEPOSUNA GİDİYOR. ORADA OLUN!",
["pln_cp1_14_03"] = "HELİKOPTER KERESTE DEPOSUNA GELİYOR, EKİP.",
["pln_cp1_15_01"] = "HELİKOPTER KAZA YERİNE GİDİYOR. HAZIR OLUN!",
["pln_cp1_15_02"] = "HELİKOPTER KAZA YERİNE GELİYOR. HAZIR BEKLEYİN EKİP!",
["pln_cp1_15_03"] = "HELİKOPTER HER AN DÜŞEN UÇAĞIN ÜSTÜNDE OLACAK.",
["pln_cp1_16_01"] = "BİZİM KUŞ HER AN TREN SAHASINA YAKLAŞABİLİR. HAZIR OLUN!",
["pln_cp1_16_02"] = "HELİKOPTERİMİZ HER AN TREN SAHASINDA OLACAK.",
["pln_cp1_16_03"] = "HELİKOPTERİMİZ BİRAZDAN TREN SAHASININ ÜZERİNDE OLACAK. HAZIRLANIN!",
