["pln_cr2_30_01"] = "EH, KAPTANIN YARDIMINI ARTIK ALAMAYIZ AMA GEMİYİ HÂLÂ TAŞIMAMIZ GEREK. GEMİ KONTROL TERMİNALİNE SIZIN, AÇIK KALDIĞINDAN EMİN OLUN YETER.",
["pln_cr2_30_02"] = "KAPTAN BUNU KESİN DUYMUŞTUR, YANİ İŞBİRLİĞİ YAPMASINI UNUTABİLİRİZ. ONU SIKIŞTIRMAYA DA VAKİT YOK, ONU DEVREDEN ÇIKARIYORUZ. GEMİ KONTROL TERMİNALİNİN SİSTEMİNİ KIRIN. ÇALIŞIR DURUMDA TUTUN.",
["pln_cr2_30_03"] = "KAPTANIN GEMİYİ BİZİM İÇİN HAREKET ETTİRMESİNİ ARTIK UNUTABİLİRİZ. NEYSE. ONSUZ DA HAREKET ETTİRİRİZ. GEMİ KONTROL TERMİNALİNE SIZIN. POLİSLERİN MÜDAHALE ETMESİNE DE İZİN VERMEYİN.",
