["pln_cr2_51_01"] = "TAMAM, RIHTIM AÇILDI. ŞİMDİ MORETTA'YI ÇAĞIRIP HAREKET ETTİRMELİYİZ. HABERLEŞME FREKANSLARI OFİSLERDEKİ BİLGİSAYARLARDAN BİRİNDE OLMALI. BULUN. BEN BAĞLANIP KONUŞURUM.",
