["pln_cr2_brf_01_01"] = "THE MORETTA KAPALI BİR RIHTIMDA, GÜMRÜK İZNİ BEKLİYOR. BURADA SİZ DEVREYE GİRİYORSUNUZ. LİMAN SAHASINA GİRDİKTEN SONRA GEMİYİ BİNEBİLECEĞİNİZ BİR YERE TAŞITACAKSINIZ. 2B'DEN 3B'YE. RIHTIM KAPILARINI AÇIP KAPTANA HAREKET EDEBİLECEĞİNİ SÖYLEYİN. MORETTA 3B'YE YANAŞINCA BİNİP PATLAYICILARI ÇALABİLİRSİNİZ. BASİT Mİ?$NL;$NL;EH, BELKİ O KADAR BASİT DEĞİL. BALKAN TARIM ÜRÜNLERİ YÜKLÜ BİR GEMİ İÇİN GÜVENLİK FAZLA SIKI. BU ROTADAN BİR SÜRÜ KARANLIK MAL GEÇTİĞİNİ DÜŞÜNMEYE BAŞLIYORUM. DİKKATLİ OLUN.",
["pln_cr2_intro_01_01"] = "MORETTA'YI HAVUZDAN ÇIKARIN. YANAŞINCA GEMİYE BİNİN, PATLAYICILARI ALIN, ÇIKIN. ANLADINIZ MI?",
["pln_cr2_intro_01_02"] = "GEMİNİN RIHTIMDAN ÇIKIP YANAŞMASINI SAĞLAYIN. SONRA BİNİP PATLAYICILARI ALABİLİRSİNİZ. SESSİZ KALIN.",
["pln_cr2_intro_01_03"] = "O HIRVAT GEMİSİNİ HAVUZDAN ÇIKARIP YANAŞTIRACAKSINIZ. SESİ ALÇAK TUTMAYA ÇALIŞACAĞIZ.",
["pln_cr3_01_01"] = "POLİS HER AN BURAYA AKIN EDECEK! HIZLI OLUN! KASA DAİRESİNİ BULMAK İÇİN VAGONLARA BAKIN.",
["pln_cr3_01_02"] = "VAGONLARI ARAMAYA BAŞLAYIN. POLİS ÇABUK MÜDAHALE EDECEKTİR. UNUTMAYIN, KASA DAİRESİNİN OLDUĞU VAGONU ARIYORSUNUZ!",
