["pln_cr3_19_03"] = "BAHSE GİRERİM O VAGONLARDA GANİMET VAR. KONTROL EDİN. C4 İÇİN DE GÖZÜNÜZ AÇIK OLSUN.",
["pln_cr3_20_01"] = "BU KASA DAİRESİ'Nİ SUYLA AÇACAĞIZ MİLLET. SUYLA DOLDURUP PATLATIN. İÇİNDEKİLERE ZARAR VERMEDEN KAPIYI YERİNDEN SÖKECEK.",
["pln_cr3_20_02"] = "BU KASA DAİRESİNE GİRMENİN EN İYİ YOLU SUYLA PATLATMAK. SUYLA DOLDURUR, PATLATIRIZ VE BUM! BASINÇ KAPIYI AÇAR. O PATLAYICILARI TUTUŞTURMADIĞIMIZDAN EMİN OLMANIN TEK YOLU.",
["pln_cr3_21_01"] = "TERMİT İŞİNİ BİTİRDİ. YAKINDAKİ SU POMPASIYLA VAGONLARI DOLDURABİLİRİZ. O HORTUMU KASA DAİRESİNE BAĞLAYIN.",
["pln_cr3_21_02"] = "TERMİT İŞİNİ YAPTI. ŞİMDİ SU POMPASINI KASA DAİRESİNE BAĞLAYIN.",
["pln_cr3_22_01"] = "HORTUM SAĞLAM GÖRÜNÜYOR. POMPAYI ÇALIŞTIRIN.",
["pln_cr3_22_02"] = "TAMAM, HORTUM İYİ GÖRÜNÜYOR. ŞİMDİ POMPAYI ÇALIŞTIRIN.",
