["pln_cr3_30_02"] = "O VAGONLAR ASKERÎ HİZMETTEN ÇIKARILMAYA GİDİYOR. BİRİNDE C4 OLMALI.",
["pln_cr3_30_03"] = "VAGONLARDAN BİRİNDE C4 OLDUĞUNU BİLİYORUM. BAKIN!",
["pln_cr3_31_01"] = "İYİ BULDUNUZ. BU SONRA İŞE YARAYACAK.",
["pln_cr3_31_02"] = "HARİKA. SONRA BİRAZ C4'E İŞ BULURUZ KESİN.",
