["pln_cr3_32_02"] = "O C4'Ü KASA DAİRESİNE KOYUN. SONRA GERİ ÇEKİLİN!",
["pln_cr3_33_01"] = "TAMAM. HER... AN...",
["pln_cr3_33_02"] = "PATLAYICI YERİNDE. VE...",
["pln_cr3_34_01"] = "YOLU MİNİBÜSLERLE KAPATIYORLAR! VE... EE... AĞIR BİRLİKLER YAKLAŞIYOR!",
["pln_cr3_34_02"] = "BARİKAT KURDULAR. AĞIR TAKVİYE DE YOLDA.",
["pln_cr3_35_01"] = "YOLU KAPATIYORLAR! SİKTİR, UÇAK İNEBİLECEK Mİ EMİN DEĞİLİM.",
["pln_cr3_35_02"] = "YOLU KAPATIYORLAR. LANET OLSUN. UÇAK İÇİN HÂLÂ YER VAR MI?",
["pln_cr3_36_01"] = "TEKNE GÖLDE SİZİ BEKLİYOR. HALATLA KAYARAK BİNEBİLİRSİNİZ.",
["pln_cr3_36_02"] = "GÖLDE BİR TEKNE VAR. ÇELİK HALAT SİZİ KARŞIYA GEÇİRİR.",
["pln_cr3_37_01"] = "HARİKA. ŞİMDİ ÇELİK HALATA GİDİN, İŞİNİZ BİTTİ.",
["pln_cr3_37_02"] = "ŞİMDİ AYNI HALATA GİDİP KENDİNİZİ ORADAN ÇIKARIN.",
["pln_cr3_37_03"] = "ÇIKIŞ YOLUNUZ O ÇELİK HALAT, ORAYA GİDİN!",
["pln_cr3_38_01"] = "SİZİ ALACAK UÇAK YOLDA AMA AĞAÇLAR YOLU KAPATIRKEN İNEMEZ. TESTERE BULUN, AĞAÇLARI TEMİZLEYİN, İNİŞ YERİNİ İŞARET FİŞEKLERİYLE BELİRLEYİN. MERAK ETMEYİN, CIA BUNU YILLARDIR YAPIYOR.",
["pln_cr3_38_02"] = "SİZİ ALMAYA KÜÇÜK BİR UÇAK YOLLUYORUM. AMA O AĞAÇLAR YÜZÜNDEN PİLOT İNEMEZ. BİR TESTERE BULUP BİRKAÇINI KESİN, SONRA DA PİSTİ ONUN İÇİN İŞARETLEYİN.",
["pln_cr3_38_03"] = "BILE SİZE GELİYOR AMA AĞAÇLAR ÖNÜNÜ KESERKEN İNEMEZ. TESTERE BULUN, ONA YOL AÇIN, SONRA FİŞEKLERLE İŞARETLEYİN.",
["pln_cr3_39_01"] = "O TESTEREYİ BULUN! BURALARDA BİR YERDE OLMALI. KÜTÜKLERİN ETRAFINA BAKIN.",
["pln_cr3_39_02"] = "BURADA BİR YERDE TESTERE OLMALI. KÜTÜKLERE BAKIN.",
["pln_cr3_39_03"] = "ŞU KERESTELERE BAKIN. BİR YERLERDE TESTERE OLMALI, ARAMAYA DEVAM EDİN.",
["pln_cr3_40_01"] = "BULDUNUZ! AĞAÇ DEVİRME VAKTİ!",
["pln_cr3_40_02"] = "HARİKA! ŞİMDİ ONU O AĞAÇLARDA ÇALIŞTIRIN!",
["pln_cr3_40_03"] = "MUHTEŞEM! AMA KAYBEDECEK VAKİT YOK. ÇALIŞTIRIP O AĞAÇLARI DEVİRMEYE BAŞLAYIN.",
["pln_cr3_41_01"] = "O AĞAÇLARI DEVİRİN!",
["pln_cr3_41_02"] = "YOLU AÇIN. AĞAÇLARI TEMİZLEYİN!",
["pln_cr3_42_01"] = "UÇAK YAKIN. İNİŞ PİSTİNİ İŞARET FİŞEKLERİYLE İŞARETLEYİN.",
["pln_cr3_42_02"] = "UÇAK NEREDEYSE GELDİ. İŞARET FİŞEKLERİNİ YAKIP PİSTİ İŞARETLEYİN.",
["pln_cr3_43_01"] = "HARİKA! UÇAK ŞİMDİ YAKLAŞIYOR...",
["pln_cr3_43_02"] = "GÜZEL. ARACINIZ ŞİMDİ ALÇALIYOR.",
["pln_cr3_44_01"] = "İNDİ! ŞİMDİ UÇAĞA GANİMETİ YÜKLEYİN!",
["pln_cr3_44_02"] = "UÇAK YERDE. ŞİMDİ GANİMETİ İÇİNE YÜKLEYİN.",
["pln_cr3_45_01"] = "HELİKOPTER YOLDA. DAYANIN MİLLET.",
["pln_cr3_45_02"] = "HELİKOPTER NEREDEYSE GELDİ. DAYANIN!",
["pln_cr3_46_01"] = "NEREDEYSE GELDİ. SESİNİ DUYABİLİYOR OLMALISINIZ.",
["pln_cr3_46_02"] = "HELİKOPTER TAM TEPENİZDE. GÖRÜYOR MUSUNUZ?",
["pln_cr3_47_01"] = "HELİKOPTER İNDİ. GANİMETİ YÜKLEYİP GİDİN!",
["pln_cr3_47_02"] = "HELİKOPTER GELDİ MİLLET. GANİMETİ YÜKLEYİP SIVIŞIN!",
["pln_cr3_48_01"] = "BİRİNİN İÇİNDE KASA DAİRESİ VAR. BULUN.",
["pln_cr3_49_01"] = "YÜKSEK SICAKLIKTA YANAN TERMİT MACUNU DOLU BİR EVRAK ÇANTASI BURADA SİZİ BEKLİYOR OLACAK.",
["pln_cr3_50_01"] = "YAKINDAKİ KERESTE FABRİKASININ KULLANDIĞI ENDÜSTRİYEL YÜKSEK BASINÇLI SU POMPASI. ŞANSIMIZ VARSA VE DOĞRU VAGON YAKININA DÜŞERSE KASA DAİRESİNİ DOLDURMAK İÇİN KULLANABİLİRİZ.",
["pln_cr3_51_01"] = "ŞİMDİ O PATLAYICIYI İÇİNE BATIRIP UZAKLAŞIN!",
["pln_cr3_51_02"] = "C4'Ü ORAYA KOYUN VE HAZIR OLUN!",
["pln_cr3_52_01"] = "AZ KALDI MİLLET. GÜZELCE DOLUYOR! BİRAZ DAHA BÖYLE DEVAM EDİN. DOLUNCA DÜZENEĞİ KURUP GÖSTERİNİN TADINI ÇIKARACAĞIZ!",
["pln_cr3_52_02"] = "HIZLA DOLUYOR EKİP. DEVAM ETMESİNİ SAĞLAYIN YETER. DOLUNCA PATLAYICIYI YERLEŞTİRİP GÖSTERİNİN TADINI ÇIKARIN.",
["pln_cr3_52_03"] = "SUYU AKITMAYA DEVAM EDİN, EKİP. BİRAZ DAHA. SONRA DÜZENEĞİ KURUN, GERİSİNİ HİDRODİNAMİĞE BIRAKIN.",
["pln_cr3_53_01"] = "NEYİ BEKLİYORSUNUZ?! O HORTUMU TAKIN ARTIK!",
["pln_cr3_53_02"] = "HORTUM KENDİ KENDİNE DÜZELMEZ. SİZ PALYAÇOLARDAN BİRİ HALLETSİN!",
["pln_cr3_53_03"] = "O HORTUMU YENİDEN BAĞLAMANIZ GEREK, MİLLET. HADİ!",
["pln_cr3_54_01"] = "POMPA TAMAM! KASA DAİRESİ DOLDU, PATLATILMAYA HAZIR!",
["pln_cr3_54_02"] = "POMPA İŞİ TAMAM. HARİKA İŞ!",
["pln_cr3_54_03"] = "POMPA İŞİNİ BİTİRDİ. O VAGON ŞİŞTİ VE HAZIR! GÜZEL İŞ.",
["pln_cr3_55_01"] = "VAGON KENDİ KENDİNE AÇILMAYACAK. O C4'Ü SUYA DALDIRIN!",
["pln_cr3_55_02"] = "HADİ, GÖSTERİYİ İZLEDİK, NASIL YAPILDIĞINI BİLİYORSUNUZ. C4'Ü YERLEŞTİRİN!",
["pln_cr3_55_03"] = "O VAGONUN TEK BEKLEDİĞİ GÜZEL BİR PARÇA C4. İŞE KOYULUN!",
["pln_cr3_intro_01_01"] = "OO... VAY BE. UMARIM VAGONLAR SAĞLAMDIR.",
["pln_cs1_01_01"] = "ETRAFTA BİRKAÇ ANAHTAR KARTI VARDIR, BELKİ ARABALARIN BAGAJLARINDA. KASA DAİRESİ'NE SESSİZCE GİRMENİZE YARDIM EDERLER. YA DA O MİSSİON IMPOSSİBLE SAÇMALIĞINI UNUTUP RAGNAROK'U BAŞLATABİLİRSİNİZ. SİZE KALMIŞ.",
["pln_cs1_01_02"] = "BU İŞİN İKİ YOLU VAR BEYLER. GÜRÜLTÜLÜ GİDEBİLİRSİNİZ, ONU NASIL YAPACAĞINIZI BİLİYORSUNUZ. AMA SEVİYENİZİ YÜKSELTMEK İSTİYORSANIZ İKİ ANAHTAR KARTI ARAYIP KASA DAİRESİNİ AÇIN. ARABA BAGAJLARINA BAKMAK İYİ FİKİR.",
["pln_cs1_01_03"] = "BURAYI GİZLİCE SOYMAK İSTERSENİZ İKİ TANE KASA DAİRESİ ANAHTAR KARTI BULMAYI DENEYİN. BELKİ BAGAJLARDADIR. YA DA SİLAHLARI KONUŞTURUN, SEÇİM SİZİN.",
["pln_cs1_02_01"] = "BU, KASA DAİRESİNİN ANAHTAR KARTLARINDAN BİRİ AMA BİR TANE DAHA LAZIM. ARAMAYA DEVAM EDİN.",
["pln_cs1_02_02"] = "ANAHTAR KARTLARINDAN BİRİNİ ALDINIZ, ŞİMDİ DİĞERİNİ BULUN.",
["pln_cs1_02_03"] = "BİR ANAHTAR KARTI TAMAM, İKİ TANE LAZIM. ARAMAYA DEVAM EDİN.",
["pln_cs1_03_01"] = "İKİ ANAHTAR KARTI DA TAMAM. PEKÂLÂ, KASA DAİRESİNE GİDİP KULLANIN.",
["pln_cs1_03_02"] = "TAMAM, İKİ ANAHTAR KARTI DA BİZDE. ŞU KASA DAİRESİNİ AÇALIM.",
["pln_cs1_03_03"] = "HARİKA, İKİ ANAHTAR KARTI. GEREKEN BU. İŞE KOYULUP O KASA DAİRESİNİ AÇIN.",
["pln_cs1_04_01"] = "YEŞİL IŞIKLAR. ŞİMDİ ZAMAN KİLİDİ DOLSUN. YAZ ÇİÇEĞİ GİBİ AÇILACAK, SİZ ARILAR DA BALI TOPLAMAYA BAŞLAYACAKSINIZ.",
["pln_cs1_04_02"] = "İŞTE BÖYLE, YEŞİL IŞIKLAR. ZAMAN KİLİDİNİ KENDİ HÂLİNE BIRAKIN. O KAPILAR ARDINA KADAR AÇILINCA MÜDÜRÜN YÜZÜNÜ GÖRMEYİ ÇOK İSTERDİM.",
["pln_cs1_04_03"] = "HARİKA. ŞİMDİ ZAMAN KİLİDİNİN DOLMASINI BEKLEYİN YETER. ŞİMDİYE KADAR KUSURSUZ GİDİYOR. AÇILINCA PARAYI ÇANTALAMAYA HAZIR OLUN.",
["pln_cs1_05_01"] = "İŞTE OLDU. KASA DAİRESİ AÇILDI. HEPSİ SİZİN EKİP. ",
["pln_cs1_05_02"] = "İŞTE BU! KASA DAİRESİ AÇILDI. PARAYI ÇANTALAMAYA BAŞLAYIN! ",
["pln_cs1_05_03"] = "KASA DAİRESİ AÇILIYOR. GİRİN İÇERİ! PARAYI ÇANTALAYIN! ",
["pln_cs1_06_01"] = "TAMAM, HARİKA! O PARA ÇUVALINI MİNİBÜSE GÖTÜRÜN.",
["pln_cs1_06_02"] = "YEŞİL PARA YIĞINLARI! BU İŞİ BUNUN İÇİN YAPIYORUZ EKİP.",
["pln_cs1_06_03"] = "TAKİPSİZ YÜZLÜKLERDEN GÜZEL DESTELER. DÜRÜST BİR SOYGUNCUNUN HAK ETTİĞİ ÖDÜL.",
["pln_cs1_07_01"] = "BİR ÇANTA PARA, HARİKA. AMA ÖNCE O ŞEREFSİZE ÖDEYELİM. OTO TAMİRCİSİNİN YANINDAKİ SARI DUVAR. MERAK ETMEYİN, ONU SONRA BULUP HALLEDERİZ.",
["pln_cs1_07_02"] = "O PARA İÇİN HEMEN PLAN YAPMAYIN. ÖNCE ŞANTAJCI GÖT HERİFE GÖTÜRMEMİZ GEREKTİĞİNİ UNUTMAYIN. MERAK ETMEYİN, ONU BULACAĞIZ.",
["pln_cs1_07_03"] = "PARA BU. UNUTMAYIN, POLİSLERİ ORADA İSTEMİYORSANIZ BİR ÇANTAYI SARI DUVARIN ÜZERİNDEN ATIN. MERAK ETMEYİN, O ŞANTAJCI GÖT HERİF HAK ETTİĞİNİ BULACAK.",
["pln_cs1_08_01"] = "TAMAM, ŞANTAJCIMIZI HALLETTİK. AÇGÖZLÜLÜĞÜ TUTMADAN DİĞER ÇANTALARI TAŞIYALIM.",
["pln_cs1_08_02"] = "O SİNSİ PİÇİN İŞİ TAMAM. HIZLICA BİTİRELİM. DAHA FAZLASINI İSTEYEBİLİR.",
["pln_cs1_08_03"] = "EH, ONA KOLAY PARA OLDU. AKLINIZA TAKMAYIN. DEVAM EDİN MİLLET.",
["pln_cs1_09_01"] = "BU İŞİ KÂRLI KILACAK KADAR ÇANTA ALDIK. HARİKA İŞ.",
["pln_cs1_09_02"] = "HARİKA GANİMET EKİP. YİNE BİRİNCİ SINIF İŞ.",
["pln_cs1_09_03"] = "İYİ İŞ ÇOCUKLAR. BU İŞE BAŞARI DEMEYE YETER.",
["pln_cs1_100_01"] = "KANALİZASYON GİRİŞİ JİMBOS'UN, ŞU OTO PARÇALAMA DÜKKÂNININ YAKININDA. BAŞINIZI EĞİN.",
["pln_cs1_101_01"] = "SİZE EN İYİ ÇIKIŞ YOLUNU BULANA KADAR ONLARI UZAK TUTUN.",
["pln_cs1_101_02"] = "BİRAZ DAHA DAYANIN MİLLET. SİZE BİR ÇIKIŞ YOLU BULUYORUM.",
["pln_cs1_101_03"] = "HAZIR BEKLEYİN EKİP. ÇIKIŞ AYARLIYORUM. HATTI KORUYUN!",
["pln_cs1_102_01"] = "ÜSTÜNÜZE KÜÇÜK BİR ORDU... YOK, DURUN, BİLDİĞİNİZ ORDU GELİYOR. MİNİBÜS BEKLEYEMEZ. HIZLANIN!",
["pln_cs1_102_02"] = "VANAYI İYİCE AÇTILAR. MİNİBÜS SONSUZA KADAR BEKLEYEMEZ. HEMEN TÜYMENİZ GEREK!",
["pln_cs1_102_03"] = "ŞEY, EKİP, ÜZERİNİZE ÇOK BÜYÜK BİR ATEŞ GÜCÜ GELİYOR. HEMEN MİNİBÜSE GİTMENİZ GEREKİYOR!",
["pln_cs1_103_01"] = "SAKİN OLUN. KONTROLÜ KORUYUN EKİP.",
["pln_cs1_103_02"] = "KAMERALARA DİKKAT EDİN. SİZİ GÖRMESİNLER.",
["pln_cs1_103_03"] = "ETRAFTA ANAHTAR KARTLARI OLMALI. GİZLİCE GİRMENİZE YARDIMCI OLABİLİRLER.",
["pln_cs1_103_04"] = "KALABALIĞI KONTROL ALTINDA TUTUN MİLLET. İNSANLARI YERDE TUTUN.",
["pln_cs1_103_05"] = "BURADA KAMERA OLACAKTIR. DİKKATLİ OLUN.",
["pln_cs1_103_06"] = "İNSANLARI YERDE TUTUN. SESSİZ TUTUN.",
["pln_cs1_103_07"] = "HARİKA GİDİYORSUNUZ. HER ŞEY GÜZEL VE SESSİZ KALSIN.",
["pln_cs1_104_01"] = "KASA DAİRESİ'Nİ AÇMALIYIZ. YA ANAHTAR KARTLARI'YLA SESSİZCE YA DA MATKAPLA ZORLAYARAK.",
["pln_cs1_104_02"] = "KASA DAİRESİ EKİP. İÇİNDE KİRALIK KASALAR, ONLARIN İÇİNDE DE PARA VAR.",
["pln_cs1_105_01"] = "O KAFESİ KURMANIZ GEREK.",
["pln_cs1_105_02"] = "PARAYI KAFESLE ÇIKARACAĞIZ, EKİP. KURUN ONU.",
