["pln_cs1_96_03"] = "ORADAN ÇIKAN BÜTÜN YOLLARI KAPATMIŞLAR. ONLARA VİETKONG USULÜ DAVRANMA VAKTİ. NE DEMEK İSTEDİĞİMİ GÖRECEKSİNİZ.",
