["pln_cs1_99_01"] = "BANKANIN YANINDAKİ ARABAYA SERVİS PENCERESİNİ GÖRÜYOR MUSUNUZ? ORADA KANALİZASYONA AÇILAN BİR RÖGAR KAPAĞI VAR. AŞAĞI İNİN.",
["pln_cs1_brf_01"] = "BURADA BİR BANKA VAR. BÜYÜK BİR ŞUBE DEĞİL AMA KASA DAİRESİ'NDE, NAKİL HÂLİNDEKİ DESTE DESTE PARANIN GEÇİCİ OLARAK TUTULDUĞUNU ÖĞRENDİM. YABANCI BANKNOTLAR. NEYSE, NASIL YAPACAĞINIZI BİLİYORSUNUZ. KENDİ YÖNTEMİNİZLE. SESSİZCE SÜZÜLÜN YA DA CEHENNEMİ YAŞATIN. HER İKİ DURUMDA DA PARAYI ORADAN NASIL ÇIKARACAĞIMIZA DAİR UFAK BİR FİKRİM VAR. NE DEMEK İSTEDİĞİMİ GÖRECEKSİNİZ. BENCE HOŞUNUZA GİDECEK.",
["pln_cs1_cbf_01_01"] = "YAKIN ZAMANDA GELEN BİR NAKİT SEVKİYATININ HABERİNİ ALDIM. ROBERTS BANKASININ BİR ŞUBESİNİN KASA DAİRESİNDE SAKLI. SAKİN BİR BÖLGE. BURADA HİÇBİR ŞEY OLMAZ, SALDIRI BEKLEMEZLER. O REHAVETİ CEZALANDIRALIM.",
["pln_cs1_cbf_01_02"] = "BURASI ROBERTS BANKASI. D.C.'DE KÜÇÜK BİR ŞİRKET, NEREDEYSE ŞEHİR KADAR ESKİ. BU ÜLKENİN KÖKLÜ KURUMLARINA BÜYÜK SAYGI DUYARIM AMA KASA DAİRELERİNDE TUTTUKLARINA SAYGIM DAHA BÜYÜK. İSTİHBARATIMA GÖRE BU ŞUBE ÜLKEDE EN AZ SOYULAN ŞUBEYMİŞ. BUNU DEĞİŞTİRME VAKTİ.",
["pln_cs1_cbf_01_03"] = "İŞTE BU MİLLET. BİR BANKA İŞİ DAHA. SOYGUNCU HAYATININ EKMEK KAPISI. BU SEFER ROBERTS BANK'İN BİR ŞUBESİNİ VURUYORUZ. KAYNAKLARIM, GÜZEL BİR SEVKİYAT ALACAKLARINI YA DA YENİ ALDIKLARINI SÖYLÜYOR. BİR ZİYARET EDELİM.",
["pln_cs1_cnc_01"] = "BANKA SOYGUNU. ADINDAN SÖZ ETTİRİN.",
["pln_cs1_cnc_02"] = "VANAYI ÇEVİRİP PARAYI SERBEST BIRAKIN. ELLER YUKARI, BANKAYI SOYUYORUZ.",
["pln_cs1_cnc_03"] = "BİR İKİ VEZNEYİ VURALIM. BİR BANKAYI ÇANTALAYALIM.",
["pln_cs1_end_01_01"] = "HER ŞEY USULÜNE UYGUN OLDU BEYLER. VANAYI ÇEVİRDİNİZ, KAYNAĞA ULAŞTINIZ VE KİMSE SİZİ GÖRMEDİ BİLE. ZAFER PAYDAY GANG'İN!",
["pln_cs1_end_01_02"] = "GÜZEL BİR YAKLAŞIMDI. GENSEC'İN AÇIKLAYACAĞI ÇOK ŞEY OLACAK. ŞUNU BÖLÜŞÜP ORTALIKTA GÖRÜNMEYELİM.",
["pln_cs1_end_01_03"] = "NAKİT KRALDIR. BUNUN ARDINDAN TEMİZLİK EKİBİNE BİLE GEREK YOK. PÜRÜZSÜZ!",
