["pln_dah_72_01"] = "TAMAM, ŞİMDİ O ANAHTAR KARTI LAZIM. DOĞUM GÜNÜ ÇOCUĞUMUZ RALPH'İ BULUN. MUHTEMELEN HÂLÂ BİR YERDE SAKLANIYORDUR!",
["pln_dah_72_02"] = "TAMAM EKİP, ANAHTAR KARTINI BULMA VAKTİ. DOĞUM GÜNÜ ÇOCUĞU HÂLÂ BURALARDADIR, GİDİP BULUN!",
["pln_dah_72_03"] = "GİDİP RALPH GARNET'I BULUN VE O ŞIMARIK HERİFTEN ANAHTAR KARTINI ALIN.",
