["pln_dah_76_01"] = "GÖZÜNÜZÜN İÇİNE BAKA BAKA YALAN SÖYLÜYOR. HELİKOPTERE GÖTÜRÜN, ŞİFREYİ SÖKTÜRÜRÜM.",
