["pln_dah_93_01"] = "BÜYÜK ADAM CFO'YA ELVEDA DEMEK GEREKTİ. EN AZINDAN GİTMEDEN YÜZÜMÜ GÖRME AYRICALIĞINA ERİŞTİ!",
["pln_dah_93_02"] = "EH, BENİ GÖRDÜKTEN SONRA YAŞAMASINA İZİN VERECEĞİMİZE SÖZ VERMEDİK YA.",
["pln_dah_93_03"] = "EH, BU DA BİTTİ. BENİ GÖRDÜ, O YÜZDEN ONU... SALMAM GEREKTİ.",
