["pln_dah_97_02"] = "EH, MUHTEMELEN BİR DÜNYA PARA EDER.",
["pln_dah_97_03"] = "ÇOK PARA EDİYOR OLMALI.",
["pln_dah_98_01"] = "ALIN, GÜZEL BİR BONUS GELSİN.",
["pln_dah_98_02"] = "İKİNCİ KASA DAİRESİNİ AÇIN, GÜZEL BİR İKRAMİYE ALIN.",
["pln_dah_98_03"] = "O KIRMIZI ELMASI ALIN, BU İŞTEN İKİ KAT PARA KAZANALIM.",
["pln_dah_99_01"] = "ÖNCELİK VİTRİNLERDEKİ TAŞLARDA AMA ALABİLDİĞİNİZ HER ŞEYİ ALIN.",
["pln_dah_99_02"] = "HER PARÇA İŞE YARAR AMA EN ÖNEMLİSİ VİTRİNLERDEKİ TAŞLAR.",
["pln_dah_99_03"] = "KUTULARDAKİLER İÇİN GELDİNİZ AMA DİĞER HER ŞEY EK KAZANÇ.",
["pln_dah_brf_01"] = "TAMAM, DİNLEYİN. KASA DAİRESİNE GİRMEK İÇİN GÜVENLİK SİSTEMİNİ AŞMALISINIZ. İSTİHBARATA GÖRE ANAHTAR KARTI GARNET'IN OĞLU RALPH'TA AMA DOĞUM GÜNÜ ÇOCUĞU DA O, BU SORUN OLABİLİR. BİR DE BİRİ DAHA GÜVENLİ OLACAĞINI SÖYLEDİĞİ İÇİN FARKLI DİZÜSTÜ BİLGİSAYARLARA BÖLÜNMÜŞ ÜÇ PARÇALI GÜVENLİK KODU VAR. HİÇ ALARM ÇALDIRMADAN HEM ANAHTAR KARTINI HEM KODU ELE GEÇİRMENİZ HARİKA OLUR. BAY GARNET'A SESSİZCE BİR OYUN OYNAYABİLİRSİNİZ.",
["pln_dah_cbf_01"] = "NATHAN GARNET'A AİT GARNET GROUP BUİLDİNG'İN 22. KATINDA, MİLYONLAR DEĞERİNDE ELMASLARIN BULUNDUĞU BİR KASA VAR. BİNANIN GÜVENLİK SİSTEMİ İLERİ TEKNOLOJİ, GÜVENLİKÇİLERİ DE TETİĞE BASMAYA HEVESLİ. NEYSE Kİ DEVAM EDEN BİR DOĞUM GÜNÜ PARTİSİ DİKKATLERİNİ DAĞITIYOR. ",
["pln_dah_cnc_01"] = "TAMAM EKİP, BİRAZ ELMASIN PEŞİNE DÜŞÜYORUZ GİBİ.",
["pln_dah_cnc_02"] = "HEY MİLLET, ELMAS SOYGUNUNA NE DERSİNİZ?",
["pln_dah_cnc_03"] = "UMARIM İYİ UYUMUŞSUNUZDUR, ÇÜNKÜ ELMASLARIN PEŞİNE DÜŞÜYORUZ. ",
["pln_dah_end_loud_01"] = "ORTALIK BİRAZ KARIŞTI AMA İŞİ BİTİRDİNİZ!",
["pln_dah_end_loud_02"] = "TAM DERS KİTAPLIK BİR KUSURSUZLUK DEĞİLDİ AMA HER ŞEY YOLUNA GİRDİKTEN SONRA KİMİN UMURUNDA!",
["pln_dah_end_loud_03"] = "GÜRÜLTÜLÜYDÜ AMA BAŞARILIYDI. OLAĞANÜSTÜYDÜNÜZ MİLLET.",
["pln_dah_end_stealth_01"] = "İYİ İŞ, EKİP. KLASİK BİR SOYGUN!",
["pln_dah_end_stealth_02"] = "HERKES SESSİZ KALARAK HARİKA İŞ ÇIKARDI. NEREDEYSE ÇATILARDAN BAĞIRASIM GELDİ.",
["pln_dah_end_stealth_03"] = "DERS KİTABINA GEÇECEK UYGULAMA, MİLLET.",
["pln_dah_intro_01"] = "TAMAM, GİRİŞ NOKTASI. İŞARETİMLE EŞZAMANLAYIN... ŞİMDİ.",
["pln_dah_intro_02"] = "19... 20... 21... ONCA PARASI VAR AMA GARNET DAHA HIZLI BİR CAM TEMİZLEME DÜZENEĞİNE PARA VEREMEYECEK KADAR CİMRİ! TAMAM, İŞTE BU, 22. KAT VE... HADİ.",
["pln_dah_intro_03"] = "TAMAM, NEREDEYSE 22. KATTASINIZ. HADİ İLERLEYİN, YUKARIDA BURNUNUZ KANAMASIN. ",
