["pln_dn1_15_03"] = "O GÜZEL ALTINI 61 NUMARALI KONTEYNERE TAŞIYIN. ACELE EDİN!",
["pln_dn1_16_01"] = "O LASTİKLERE BENZİN DÖKÜN. GÖKTEKİ O GÖZÜN GÖRÜŞÜNÜ KAPATMALIYIZ.",
["pln_dn1_16_02"] = "TAMAM, HELİKOPTER İÇİN BİR FİKRİM VAR. O LASTİKLERE BİRAZ BENZİN DÖKÜP YAKIN. DUMAN PERDESİ OLUŞTURUR.",
["pln_dn1_16_03"] = "ŞİMDİ O LASTİKLERİ YAKIN. BENZİNİ ÜZERLERİNE DÖKÜN. BU, HELİKOPTERİ HALLEDER.",
["pln_dn1_17_01"] = "UNUTMAYIN: LASTİKLERİ YAKIN. HER YERLERİNE BENZİN DÖKÜN!",
["pln_dn1_17_02"] = "EKİP, LASTİKLERİ YAKIN. O HELİKOPTERE UĞRAŞACAK KALIN BİR DUMAN PERDESİ VERİN!",
["pln_dn1_17_03"] = "O LASTİKLERİ YAKIN EKİP. ÜSTLERİNE BENZİN DÖKÜN.",
["pln_dn1_18_01"] = "UNUTMAYIN, BİRAZ BENZİN BULUP LASTİKLERE DÖKMENİZ GEREKİYOR!",
["pln_dn1_18_02"] = "EKİP, BENZİN BULUN VE LASTİKLERİ YAKIN. O HELİKOPTERE UĞRAŞACAĞI GÜZEL, YOĞUN BİR SİS PERDESİ VERİN!",
["pln_dn1_18_03"] = "O LASTİKLERİ YAKIN MİLLET. BİRAZ BENZİN BULUP ÜSTLERİNE DÖKÜN.",
["pln_dn1_19_01"] = "ARTIK HELİKOPTER KONTEYNERLERİ NEREYE YÜKLEDİĞİMİZİ GÖREMEYECEK.",
["pln_dn1_19_02"] = "HELİKOPTERLER UZAKLAŞIYOR. İŞE YARIYOR.",
["pln_dn1_19_03"] = "BURADAN DUMAN YETERİNCE KALIN GÖRÜNÜYOR. TAMAM, HELİKOPTERLER ÇEKİLİYOR.",
["pln_dn1_20_01"] = "12 NUMARALI KONTEYNER. KAÇIŞIMIZI KORUYACAK GÜZEL BİR TUZAK KURUN.",
["pln_dn1_20_02"] = "12 NUMARALI KONTEYNERE BİRAZ BENZİN DÖKÜN. KAÇIŞIMIZI ÖRTECEK.",
["pln_dn1_20_03"] = "KAÇIŞIMIZI ÖRTMEK İÇİN 12 NUMARALI KONTEYNERE ATEŞ TUZAĞI KURMALISINIZ. BENZİN KULLANIN.",
["pln_dn1_21_01"] = "TAMAM. ŞİMDİ ÇIKIŞIMIZIN YANINA GÖTÜRÜN. KONTROL PANELİNİ KULLANIN.",
["pln_dn1_21_02"] = "TAMAM. ONU GEREKEN YERE GÖTÜRELİM. VİNÇ KUMANDALARINI BULUN.",
