["pln_dn1_brf_01_01"] = "MURKYWATER AYLARDIR D.C.'DEN KONVOYLA MAL GEÇİRİYOR. BÜYÜK BİR ÖDÜL FIRSATI ÇIKANA KADAR ONLARI VURMADIM. İŞTE FIRSAT: ALTIN KÜLÇELERİ. ONLARI İSTEDİĞİMİZ YERE GETİRMEK İÇİN WOODROW'DA BİR ‘OYALAMA’ AYARLADIM. SONRA ZIRHLI KAMYONU SİLAHLI KONVOYDAN AYIRACAĞIZ. YALNIZ KALINCA VURUP O GÜZEL ALTINI ÇALIN. AU, İŞTE BU.",
["pln_dn1_cbf_01_01"] = "ALTIN DOLU BİR KAMYONUN HABERİNİ ALDIM. TEK SORUN, ESKİ DOSTLARIMIZ MURKYWATER TARAFINDAN KORUNMASI. AMA SİZİN HALLEDEMEYECEĞİNİZ BİR ŞEY DEĞİL, DEĞİL Mİ?",
["pln_dn1_cbf_01_02"] = "RIHTIM CİVARINDA BİR KONVOYA PUSU KURUYORUZ. YÜK ALTIN. KONVOY MURKYWATER'IN. SORU VAR MI?",
["pln_dn1_cbf_01_03"] = "MURKYWATER BİR ALTIN SEVKİYATINI DEPOLARINDAN GİZLİCE ÇIKARMAYA ÇALIŞIYOR. PUSUYA YATMAYA VAR MISINIZ?",
