["pln_dn1_cnc_01_02"] = "ALTIN DOLU BİR MURKYWATER KONVOYU. BASKIN VAKTİ.",
["pln_dn1_cnc_01_03"] = "ALTIN YÜKLÜ BİR KONVOYU VURUYORUZ.",
["pln_dn1_intro_01_01"] = "...AYRICA GÜNEYE GİDEN 45 NUMARALI YOLDA BÜYÜK BİR KAZA, BÜTÜN OTOYOLU TIKADI. BU SABAH ORTALIK SAVAŞ ALANI GİBİ. MANZARALI YOLDAN GİTSENİZ İYİ OLUR.",
["pln_dn1_intro_01_02"] = "I45'İN GÜNEYE GİDEN YÖNÜNDE TRAFİK BAŞTAN SONA TIKANDI. O BÖLGEDEN GEÇMEYİ PLANLIYORSANIZ UNUTUN.",
["pln_dn1_intro_01_03"] = "WOODROW BRİDGE YAKININDA BİR LİMUZİNİN ALEV ALMASIYLA CİDDİ BİR KAZA YAŞANDI. ACİL EKİPLERİ HÂLÂ OLAY YERİNDE. TRAFİKTE KALDIYSANIZ ARKANIZA YASLANIP KALİPSO SAATİMİZİN TADINI ÇIKARIN.",
["pln_drk_01_01"] = "TAMAM EKİP. TREN SAHASI TAM ÖNÜNÜZDE. İÇERİ SIZABİLECEĞİNİZ BİRKAÇ YOL OLMALI, SEÇİMLERİNİZİ AKILLICA YAPIN.",
["pln_drk_01_01a"] = "UNUTMAYIN, BUNU SESSİZCE YAPIYORUZ. ALARM ÇALARSA HAPI YUTARIZ.",
["pln_drk_01_02"] = "TAMAM MİLLET, İYİ BİR NOKTA. TREN SAHASINI NEREDEYSE TAMAMEN GÖREBİLİYORSUNUZ. DEVRİYE MUHAFIZLARINI VE KAMERALARI TAKİP EDİN.",
["pln_drk_01_02a"] = "NASIL HAREKET EDECEĞİNİZİ PLANLAMAK İÇİN FIRSATINIZ BU.",
["pln_drk_01_03"] = "İŞTE BURASI, GİZLİ MANEVRA SAHASI. FIRSATI DEĞERLENDİRİP BÖLGEYİ KEŞFEDİN. MURKY'LER VE KAMERALARLA SIKI KORUNUYOR, HATA YAPMA LÜKSÜMÜZ YOK.",
["pln_drk_02_01"] = "İÇERİ GİRMENİN YOLUNU BULUP MURKYWATER TRENLERİNİ BULUN. EMP PARÇALARI BÜYÜK İHTİMALLE FARKLI VAGONLARDA OLACAK.",
["pln_drk_02_02"] = "İÇERİ GİRİP MURKYWATER TRENLERİNİ ARAYIN. KOLAYCA FARK EDERSİNİZ.",
["pln_drk_02_02a"] = "EMP BOMBASININ İKİ PARÇA OLDUĞUNU UNUTMAYIN. İKİSİNİN DE GEREKTİĞİNİ HATIRLATMAMA GEREK YOK.",
["pln_drk_02_03"] = "EMP BOMBASININ PARÇALARINI TAŞIYAN TRENLERİ BULMAYA ODAKLANIN. ANA ÖNCELİĞİMİZ BU.",
["pln_drk_03_01"] = "MİLLET, MURKYWATER TRENLERİNİ BULUN.",
["pln_drk_03_02"] = "MURKYWATER'A AİT TRENLERİ FARK ETMEK KOLAY OLMALI. BULUN ONLARI.",
["pln_drk_03_03"] = "MURKYWATER TRENLERİNİ BULMAZSANIZ EMP BOMBASINI ALAMAYIZ.",
["pln_drk_04_01"] = "TAMAM, ŞİMDİ MURKYWATER'IN KENDİ TRENLERİNİ ARAMALISINIZ.",
["pln_drk_04_01a"] = "YANLARINDA BİR ÇEŞİT PANEL OLMALI.",
