["pln_drk_20_01"] = "BU BÖLGEDE BİR SÜRÜ İNŞAAT VAR. ETRAFI ARAŞTIRIN, O ÇELİK KAPIYI AŞMAMIZA YARDIM EDECEK BİR ŞEY BULABİLİR MİSİNİZ BAKIN.",
