["pln_drk_23_02"] = "O GÜVENLİK KAPISINI GEÇMEK İÇİN TERMİT KULLANMANIZ GEREKİYOR.",
["pln_drk_23_03"] = "GÜVENLİK KAPISINA DÖNÜP O PARMAKLIKLARI ERİTİN. İŞE YARAMALI.",
["pln_drk_24_01"] = "...BURAYI MATKAPLA GEÇMEYİ UNUTABİLİRİZ. ÇOK GÜRÜLTÜ ÇIKARIR. BELKİ SİSTEMİNİ KIRMANIN YOLUNU BULURUZ?",
["pln_drk_25_01"] = "MURKYWATER TEKNOLOJİYİ SEVER. YAKINLARDA BİR TÜR MOBİL KOMUTA MERKEZLERİ OLMALI. NE BULABİLİYORSUNUZ BAKIN.",
["pln_drk_25_02"] = "BİR SABİT DİSK ELE GEÇİRİRSEK KASA DAİRESİNİN SİSTEMİNİ KIRABİLİRİZ BELKİ.",
["pln_drk_26_01"] = "EKİP, KASA DAİRESİNİN SİSTEMİNİ KIRACAK BİR ŞEY OLMADAN AÇAMAYIZ. ARAMAYA DEVAM EDİN!",
