["pln_drk_26_03"] = "KASA DAİRESİNİN GÜVENLİK SİSTEMİNİ AŞMAK İÇİN KULLANABİLECEĞİMİZ BİR ŞEY OLMALI.",
["pln_drk_27_01"] = "O SABİT DİSK MÜKEMMEL OLACAK! BAĞLADIĞINIZDA SİSTEMLERİNE ERİŞİP KASA DAİRESİ'Nİ AÇABİLİRİM.",
