["pln_drk_27_03"] = "TAM İHTİYACIMIZ OLAN ŞEY! SABİT DİSKİ BAĞLAYIN, BEN HALLEDERİM. O KASA DAİRESİ HEMEN AÇILIR.",
["pln_drk_28_01"] = "SABİT DİSKİ KASA DAİRESİNE GERİ GETİRİP TAKIN.",
["pln_drk_28_02"] = "TRENE DÖNÜP SABİT DİSKİ KULLANIN. GÜVENLİĞİ GEÇERSİZ KILABİLİRİM HERHÂLDE.",
["pln_drk_28_03"] = "KASA DAİRESİ'NİN KAPISINA DÖNÜP SABİT DİSKİ TAKIN. GERİSİNİ BEN HALLEDERİM.",
["pln_drk_29_01"] = "O EKİPMAN SONRA İŞE YARAYABİLİR, SAKLAYIN.",
["pln_drk_29_02"] = "TABİİ, NEDEN OLMASIN? SONRA İŞİMİZE YARAYABİLİR.",
["pln_drk_29_03"] = "BUNUNLA YANLIŞ YAPAMAYIZ HERHÂLDE. SONRA İŞE YARAYACAĞI BİR YER OLABİLİR.",
["pln_drk_30_01"] = "O LEVYE, GİTMEDEN ÖNCE DAHA FAZLA GANİMET BULMA ŞANSIMIZI ARTIRIR.",
["pln_drk_30_02"] = "HARİKA, ARTIK ETRAFTAKİ SANDIKLARI ÇOK DAHA HIZLI AÇABİLİRİZ. İÇLERİNDE GÜZEL ŞEYLER OLDUĞUNA BAHSE GİRERİM.",
["pln_drk_30_03"] = "FAZLADAN GANİMET İÇİN KALACAKSANIZ O LEVYE İŞİNİZİ GÖRÜR.",
["pln_drk_31_01"] = "TAMAM, EMP PARÇALARINI ÇALMAK İÇİN GEREKEN HER ŞEY BİZDE. TRENLERE DÖNÜN.",
["pln_drk_31_02"] = "İŞTE BU MİLLET. ŞİMDİ TRENLERE DÖNÜP EMP BOMBASINI ELE GEÇİRİN.",
