["pln_drk_35_01"] = "TAMAM, BURAYA ALMAYA GELDİĞİMİZ EMP GÜVENCEYE ALINDI. AMA İSTERSENİZ GERİ DÖNÜP EK GANİMET ALACAK VAKTİNİZ VAR.",
["pln_drk_35_02"] = "HARİKA, EMP'Yİ GÜVENE ALDIK. KAÇMADAN ÖNCE BİRAZ DAHA GANİMET TOPLAMAK İSTERSENİZ SİZİ SUÇLAMAM. SİZE KALMIŞ.",
["pln_drk_35_03"] = "EMP GÜVENE ALINDIĞINA GÖRE KAÇIŞ ARACI GELENE KADAR BİRAZ VAKİT GEÇİREBİLİRİZ.",
["pln_drk_35_03a"] = "GERİ DÖNÜP O GÜZEL GANİMETTEN BİRAZ ALSANIZ YA? VAKTİNİZE DEĞMESİNİ SAĞLARIM.",
["pln_drk_36_01"] = "DİNLEYİN, EKİP. SİZİ ALMAK İÇİN TEKNE GÖNDERİYORUM. NEHRİN YANINDAKİ KÜÇÜK SU GİRİŞİNİ ARAYIN.",
["pln_drk_36_02"] = "HEY, KAÇIŞ ŞOFÖRÜNÜZ TEKNEYLE GELİYOR. NEHİR KENARINDAKİ KÜÇÜK SU GİRİŞİNE GİDİN.",
["pln_drk_36_03"] = "KAÇIŞ ŞOFÖRÜ SİZİ ALMAK İÇİN TEKNEYLE GELİYOR. NEHİR KENARINDAKİ KÜÇÜK SU GİRİŞİNE YAKIN DURUN.",
["pln_drk_37_01"] = "DİNLEYİN, EKİP. TWITCH MİNİBÜSLE GELİYOR. ÜST KÖPRÜ TARAFINDAN GELECEK.",
["pln_drk_37_02"] = "TWITCH SİZİ ALMAK İÇİN MİNİBÜSLE GELİYOR. ÜST KÖPRÜNÜN YANINDA BEKLEYECEK.",
["pln_drk_37_03"] = "MİNİBÜSÜ SİZE YOLLUYORUM. TWITCH ÜST KÖPRÜ TARAFINDAN GELECEK.",
["pln_drk_38_01"] = "HEY, CESET SAKLAMANIZ YA DA GANİMET GEÇİRMENİZ GEREKİRSE BU HAVALANDIRMALAR TAM SİZE GÖRE.",
["pln_drk_38_02"] = "BU HAVALANDIRMA SİSTEMİNİ LEHİMİZE KULLANABİLİRİZ; CESET SAKLAMAK YA DA FAZLADAN GANİMETİ GEÇİRMEK İÇİN, ANLIYOR MUSUNUZ?",
["pln_drk_39_01"] = "BİR MUHAFIZI İNDİRİRSENİZ FARK EDİLMESİN DİYE CESEDİNİ TRENİN ALTINA SAKLAYABİLİRSİNİZ.",
["pln_drk_39_02"] = "KİMSEYİ ÖLDÜRMEMEYE ÇALIŞIN. AMA MECBUR KALIRSANIZ CESEDİ TRENİN ALTINA SAKLAMAK GÜVENLİ OLMALI.",
["pln_drk_40_01"] = "LANET OLSUN, BUNLAR DRON MU? GERÇEKTEN GELECEKTE YAŞIYORUZ, DEĞİL Mİ? KAMERALARI VAR GİBİ, GÖZDEN UZAK DURUN.",
["pln_drk_40_02"] = "KAMERALI DRONLAR MI, CİDDİ MİSİNİZ? MURKYWATER İŞİ İLERLETMİŞ. GÖRÜNMEMEYE DİKKAT EDİN.",
["pln_drk_41_01"] = "GÜZEL, ŞU ZIMBIRTIYI İNDİRDİNİZ. AMA PİSLİĞİ GİZLEYİN. MUHAFIZLAR DRONLARINDAN BİRİNİ PARÇALADIĞINIZI ÖĞRENİRSE TEPKİ VERİRLER.",
["pln_drk_41_02"] = "İYİ İŞ. O DRON, ROBOT DEVRİMİNİ GÖREMEYECEK. AMA HURDA YIĞININI SAKLAYIN. GÜVENLİKÇİLERDEN BİRİ BULMASIN.",
["pln_drk_42_01"] = "MİLLET, BÜTÜN TREN SAHASINI ARAMIŞ OLAMAZSINIZ. BİR ŞEYİ KAÇIRIYOR OLMALISINIZ.",
["pln_drk_42_02"] = "BÜTÜN TREN SAHASINI ARAŞTIRDINIZ MI?",
["pln_drk_42_03"] = "TEMBELLİK ETMEYİN MİLLET. GEREKİRSE BÜTÜN MANEVRA SAHASINI ARAYIN.",
["pln_drk_43_01"] = "MİLLET, ARADIĞIMIZ ŞEY BAKIM TÜNELLERİNDE OLABİLİR.",
["pln_drk_43_02"] = "ARADIĞINIZ ŞEY BAKIM TÜNELLERİNDE OLABİLİR. ARAYIN.",
["pln_drk_43_03"] = "BAKIM TÜNELLERİNE BAKMAYA DEĞER OLABİLİR.",
["pln_drk_44_01"] = "BAKIM TÜNELLERİNDE BİRKAÇ ODA VAR. HEPSİNE BAKTINIZ MI?",
