["pln_drk_45_02"] = "TRENLERİN ARASINDA DA BOŞLUK VAR. BAKMAYA DEĞER.",
["pln_drk_45_03"] = "TRENLERİN TAM ARASINA BAKTINIZ MI?",
["pln_drk_46_01"] = "MİLLET, BÜTÜN BÖLGEYİ TARAMANIZI İSTİYORUM. MANEVRA SAHASININ HER KÖŞESİNE BAKIN DEMEK BU. TAŞ ÜSTÜNDE TAŞ BIRAKMAYIN.",
["pln_drk_46_02"] = "ALAN ÇOK BÜYÜK DEĞİL. DOLAŞIP BÜTÜN TREN SAHASININ HER KÖŞESİNİ ARAYABİLİRSİNİZ.",
["pln_drk_46_03"] = "DÖRT KİŞİSİNİZ MİLLET. GEREKİRSE DAĞILIN, MANEVRA SAHASININ HER KÖŞESİNE BAKIN.",
["pln_drk_47_01"] = "LANET, EMP BU VAGONDA DEĞİL GİBİ. BURADA YİNE DE DEĞERLİ GANİMET OLABİLİR. İSTERSENİZ ŞİMDİ ALIN, İSTERSENİZ SONRA GERİ DÖNÜN. SİZE KALMIŞ.",
["pln_drk_47_02"] = "EMP BURADA DEĞİL GİBİ AMA BAŞKA DEĞERLİ GANİMET OLABİLİR. ŞİMDİ BAKABİLİR YA DA SONRA DÖNEBİLİRSİNİZ.",
["pln_drk_48_01"] = "LANET OLSUN! ALARM BU!",
["pln_drk_brf_01_01"] = "YALAN SÖYLEMEYECEĞİM. AKAN'I KAZIKLAYARAK ÇOK BÜYÜK BİR RİSK ALIYORUZ AMA DOĞRU SEÇİM OLDUĞUNA İNANIYORUM. ÖNCE MURKYWATER'IN TAŞIDIĞI EMP BOMBASINI ALMALIYIZ. PLANLI BİR DURAKLAMA YAPACAKLAR. FIRSATIMIZ BU OLACAK. SESSİZCE GİRİN, EMP'Yİ BULUP ÇIKIN. BU İŞİ GİZLİCE YAPMALISINIZ, ONA GÖRE GİYİNİN.",
["pln_drk_intro_01_01"] = "İSTİHBARATA GÖRE EMP BOMBASI İKİ PARÇA, BİZ DE BUNUN İÇİN BURADAYIZ. AMA YİNE DE BAŞKA DEĞERLİ GANİMET ALMA FIRSATI GÖRÜRSENİZ DEĞERLENDİRİN.",
["pln_drk_intro_01_01a"] = "CEBİMİZE DAHA FAZLA PARA GİRECEK, LOCKE'UN DA GÖZÜNE GİRMİŞ OLURUZ.",
["pln_ed1_01_01"] = "TAMAM, İÇERİ GİRİN. SESSİZ OLUN. ",
["pln_ed1_01_02"] = "ESKİ USUL ZORLA GİRİŞ. GÖZDEN UZAK DURUN.",
["pln_ed1_01_03"] = "RIHTIMA GİRİN. GÜVENLİK OLACAK, GİZLENİN VE SESSİZ KALIN.",
["pln_ed1_02_01"] = "TAMAM. GİRDİNİZ. ŞİMDİ ETRAFI ARAŞTIRIN. OY MAKİNELERİNİ WASHINGTON'A TAŞIYAN KAMYONA DAİR İPUCU OLMALI. KONTEYNERLERİ ARAYIN, BİLGİSAYARLARA BAKIN. DOĞRU KAMYONU BELİRLEMEK İÇİN NE GEREKİYORSA.",
["pln_ed1_02_02"] = "HARİKA. ŞİMDİ RIHTIMI ARAYIN. OY MAKİNELERİNİ TAŞIYIP WASHINGTON'A GİDEN KAMYONU GÖSTERECEK BİR ŞEY ARIYORSUNUZ. KONTEYNER, BİLGİSAYAR, NE VARSA ARAYIN. ÇÖZÜNCE DOĞRU KAMYONU İŞARETLEYİN.",
["pln_ed1_02_03"] = "TAMAM, ŞİMDİ ETRAFA BAKIN. WASHINGTON'A GİDEN KAMYONU İŞARETLEMEMİZ GEREK. İPUCU ARAYIN. KONTEYNERLER, TERMİNALLER, HER TÜRLÜ KAYIT. DOĞRU OLANI BULUP İŞARETLEYİN.",
["pln_ed1_03_01"] = "TAKİP CİHAZI YERLEŞTİRİLDİ. SİNYAL GELİYOR. ŞİMDİ KIÇINIZI KALDIRIN DA UMALIM ELEPHANT'IN MAKİNELERİNİN PEŞİNDE OLALIM.",
["pln_ed1_03_02"] = "GÜZEL, NET BİR SİNYAL ALIYORUM. GİTME VAKTİ, MİLLET. UMARIM DOĞRU KAMYONU İŞARETLEDİNİZ.",
["pln_ed1_03_03"] = "GPS ÇEVRİMİÇİ. DOĞRU KAMYONU İŞARETLEDİYSENİZ HARİKA İŞ. GİTME VAKTİ.",
["pln_ed1_04_01"] = "SİZİ GÖRDÜLER! KAMYONLAR GİDİYOR. TAMAM, B PLANI LAZIM. BİR DÜŞÜNEYİM.",
["pln_ed1_04_02"] = "KAHRETSİN! GÖRÜLDÜNÜZ, KONVOY YOLA ÇIKIYOR. KAMYONUMUZU BULMAK İÇİN BAŞKA YOL LAZIM.",
["pln_ed1_04_03"] = "KAMYONLAR HAREKET EDİYOR. BİRİ SİZİ GÖRDÜ! TAMAM, BAŞKA PLAN VAKTİ.",
["pln_ed1_05_01"] = "TAMAM, ŞUNU DENEYELİM. LİMANIN AĞINA BAĞLI BİR ŞEY BULUN. SEVKİYAT MANİFESTOLARINI AÇABİLİRİM HERHÂLDE. NEREYE GİTTİKLERİNE DAİR İPUCU OLABİLİR.",
["pln_ed1_05_02"] = "BU İŞE YARAYABİLİR. ORADAKİ AĞA BAĞLI BİR TERMİNAL BULUN; MASAÜSTÜ, DİZÜSTÜ, NE OLURSA. VERİ TABANLARINA GİRERSEM BELKİ MANİFESTODAN BİLGİ ÇEKEBİLİRİM.",
["pln_ed1_05_03"] = "TAMAM, BİR FİKRİM VAR. AŞAĞIDA AĞA BAĞLI NE BULURSANIZ HACKLEMENİZİ İSTİYORUM. VERİ TABANLARINA ERİŞEBİLİRSEM KAMYONUMUZUN NEREYE GİTTİĞİNİ BULABİLİRİM.",
["pln_ed1_06_01"] = "TAMAM, VERİ TABANI İKİYE AYRILMIŞ. ŞİMDİ İLKİNİ ALIYORUM.",
["pln_ed1_06_02"] = "VERİ TABANLARI İKİ SUNUCUYA BÖLÜNMÜŞ. ŞİMDİ İLKİNİ İNDİRİYORUM.",
["pln_ed1_07_01"] = "TAMAM, İLK VERİ TABANI İNDİRİLDİ. HARİKA GÖRÜNÜYOR AMA EKSİK. ŞİMDİ SIVIŞABİLİRSİNİZ YA DA KALIP BÜTÜN VERİ TABANINI İNDİREBİLİRSİNİZ. SİZE KALMIŞ.",
["pln_ed1_07_02"] = "VERİ TABANININ İLK YARISINI ALDIM. YETEBİLİR DE YETMEYEBİLİR DE. KARAR SİZİN: ŞİMDİ ÇIKIN YA DA KALIP İKİNCİ YARISINI ALIN.",
["pln_ed1_07_03"] = "İLK VERİ TABANI İNDİRİLDİ. İKİNCİYİ ALIRSAK DOĞRU KAMYONU İZLEME ŞANSIMIZ ARTAR. AMA KARAR SİZİN.",
["pln_ed1_08_01"] = "TAMAMDIR! BÜTÜN VERİ TABANI ELİMİZDE. BU VERİLERİ TARAYIP BELKİ DOĞRU KAMYONUN NEREYE GİTTİĞİNİ BULABİLİRİM. SİZİN İŞİNİZ BİTTİ MİLLET.",
["pln_ed1_08_02"] = "BÜTÜN VERİ TABANINI ALDINIZ. HARİKA İŞ. TAM BİRER BELASINIZ!",
["pln_ed1_08_03"] = "TAMAM. BÜTÜN VERİ TABANI KURTARILDI. OYALANMANIN ANLAMI YOK, TEKNEYE DÖNÜN.",
["pln_ed1_09_01"] = "O TERMİNAL HANGİ KAMYONUN NEREYE GİTTİĞİNİ GÖSTERİYOR. BAKMAYA DEVAM EDİN. BİZİM KAMYONU BELİRLEMEMİZE YARDIMCI OLABİLİR.",
["pln_ed1_09_02"] = "O BİLGİSAYAR HANGİ KAMYONUN NEREYE GİTTİĞİNİ GÖSTERİYOR. BİLMEK DEĞERLİ OLABİLİR.",
["pln_ed1_09_03"] = "BİLGİSAYAR KAMYONLARIN NEREYE GİTTİĞİNİ GÖSTERİYOR. WASHINGTON'A GİDENLERİ KOLLAYIN.",
["pln_ed1_10_01"] = "ELEKTRİĞİ KESTİLER! GERİ GETİRİN, YOKSA İNDİRMEYE DEVAM EDEMEYİZ.",
["pln_ed1_10_02"] = "AĞIN ELEKTRİĞİNİ KESTİLER. GERİ GETİRMENİZ GEREKİYOR.",
["pln_ed1_10_03"] = "ELEKTRİK KESİLDİ. DEVRE KUTUSUNU ARAYIP AÇIN.",
["pln_ed1_11_01"] = "ELEKTRİK GELDİ. TERMİNALE GİDİP İNDİRMEYİ YENİDEN BAŞLATIN!",
["pln_ed1_11_02"] = "HARİKA. ŞİMDİ TERMİNALE DÖNÜP İNDİRMEYİ YENİDEN BAŞLATIN!",
["pln_ed1_11_03"] = "ŞİMDİ TERMİNALE DÖNÜP YENİDEN HIZ VERİN.",
["pln_ed1_12_01"] = "ELEKTRİKLE OYNAMAYI ÇOK SEVİYORLAR. O ŞALTERLERE GÖZ KULAK OLUN. İNDİRMEYİ KESMELERİNİ ENGELLEYİN.",
["pln_ed1_12_02"] = "POLİSLERİN O SİGORTA ŞALTERLERİNE ULAŞMASINI ENGELLEMEYE ÇALIŞIN. ",
["pln_ed1_12_03"] = "POLİSLERİN FİŞİ ÇEKMESİNİ ENGELLERSENİZ O BOKTAN AĞ VERİ TABANLARINI DAHA HIZLI AKTARIR.",
["pln_ed1_13_01"] = "TAMAM, VERİ TABANININ İKİNCİ YARISINI ALIYORUM. TAMAMINI İNDİRİRSEK MAKİNELERİ TAŞIYAN KAMYONU BULMA ŞANSIMIZ GÜÇLÜ.",
["pln_ed1_13_02"] = "VERİ TABANININ İKİNCİ YARISI GELİYOR. ALDIĞIMIZDA OY MAKİNELERİNİ TAŞIYAN KAMYONUN VARIŞ YERİNİ TESPİT EDEBİLİRİM.",
["pln_ed1_13_03"] = "VERİLER ŞİMDİ GELİYOR. DOĞRU KAMYONUN NEREYE GİTTİĞİNİ BULMAM İÇİN YETERLİ OLMALI. GÖNDERMEYE DEVAM EDİN.",
["pln_ed1_14_01"] = "RIHTIMDA MAKİNELERİ WASHINGTON'A TAŞIYAN KAMYONU BULMANIZA YARDIM EDECEK İPUÇLARI OLMALI. GÖZÜNÜZÜ DÖRT AÇIN.",
["pln_ed1_14_02"] = "ETRAFA BAKIN. SİZİ DOĞRU KAMYONA YÖNLENDİRECEK İPUÇLARI OLMALI. BELKİ RENKLERİNİ KONTEYNERLERLE EŞLEŞTİREBİLİRSİNİZ.",
["pln_ed1_14_03"] = "KAMYONU BULMANIZA YARDIMCI OLACAK İPUÇLARI OLMALI. DEDEKTİFLİĞE BAŞLAYIN. AÇIK KONTEYNER ARAYIN, KAMYONLARIN NE TAŞIDIĞINI GÖSTEREBİLİRLER.",
["pln_ed1_15_01"] = "KONTEYNERLERİN İÇİNE BAKIN. NE YÜK TAŞIDIKLARINI ÖĞRENİN. BELKİ DOĞRU KAMYONUN HANGİSİ OLDUĞUNU BULMANIZA YARDIM EDER.",
["pln_ed1_15_02"] = "BELKİ O SEVKİYAT KONTEYNERLERİNİN İÇİNDEKİLER BİZİM KAMYONUN HANGİSİ OLDUĞUNU BULMANIZA YARDIM EDER.",
["pln_ed1_15_03"] = "O KONTEYNERLERDE YÜK VAR. YANLIŞ KAMYONLARI ELEMENİZE YARDIM EDEBİLİR.",
["pln_ed1_16_01"] = "BU KAMYONLARDAN BİRİ ARADIĞIMIZ. İPUÇLARINI ARAMAYI BİTİRİNCE HEDEF SANDIĞINIZ KAMYONA CİHAZI TAKIN. TEK ŞANSINIZ VAR, EMİN OLUN.",
["pln_ed1_16_02"] = "BUNLARDAN BİRİ OY MAKİNELERİNİ WASHINGTON'A TAŞIYAN KAMYON. HANGİSİ OLDUĞUNU ANLADIĞINIZI DÜŞÜNÜYORSANIZ TAKİP CİHAZINI TAKIN DA DEVAM EDELİM.",
["pln_ed1_16_03"] = "KAMYONLAR BUNLAR. İPUCU ARAMAYI BİTİRİNCE OY MAKİNELERİNİ WASHINGTON'A TAŞIDIĞINI DÜŞÜNDÜĞÜNÜZ KAMYONA O GPS'İ TAKIN.",
["pln_ed1_99_01"] = "HADİ MİLLET, DEĞİŞİMİ DEĞİŞTİRELİM!",
["pln_ed1_brf_01"] = "THE ELEPHANT SEÇİM KAYBETMEYİ SEVMİYOR. BÖLGESİNE GİDEN OY MAKİNELERİNE MÜDAHALE ETMEMİZİ İSTİYOR. MAKİNELERİ TAŞIYAN KAMYONA GPS TAKİP CİHAZI KOYMAK İÇİN RIHTIMA GİDİYORUZ. BÖYLECE SEÇİMDEN ÖNCE KAMYONUN YOLUNU KESİP MAKİNELERİ HALLEDEBİLECEĞİZ.",
["pln_ed1_brf_02"] = "THE ELEPHANT'IN HALKLA İLİŞKİLER EKİBİ, İKTİDARA DERİNLİK, LİDERLİK VE DÜRÜSTLÜKLE GELDİĞİNİ İDDİA EDECEK AMA HEPSİ SAÇMALIK. O KAYPAK PİÇ, HİLEYLE SENATO'YA GİRECEK. SİZ DE BURADA DEVREYE GİRİYORSUNUZ. PİER 39'DA KAMYONLAR VAR. BİRİNDE OY MAKİNELERİ BULUNUYOR. KAMYONU BULUN VE BİR GPS TAKİP CİHAZI TAKIN. GERİSİNİ DAHA SONRA HALLEDERİZ. TABİİ THE ELEPHANT, BU İŞİN KENDİSİNE KÖTÜ HABER OLARAK DÖNME İHTİMALİNİN OLABİLDİĞİNCE DÜŞÜK TUTULMASINI İSTİYOR. BU YÜZDEN HATIRI SAYILIR KAMPANYA BÜTÇESİNİN BİR KISMINI ÖZEL BİR GİZLİ OPERASYON PRİMİ İÇİN AYIRDI. SİZ İŞİ SESSİZCE YAPIN, İYİ SİYASETÇİMİZ DE SİZİ CÖMERTÇE ÖDÜLLENDİRSİN.",
["pln_ed1_end_a_01"] = "MÜKEMMEL BİR SESSİZLİK İŞİYDİ. ORADA OLDUĞUNUZU ANLAMADILAR. ŞİMDİ BAKALIM O KAMYON BİZİ NEREYE GÖTÜRECEK.",
["pln_ed1_end_a_02"] = "GÜVENLİKLİ BİR DEPODAN GÜPEGÜNDÜZ NİNJA GİBİ GEÇMEK ÖZEL BECERİ İSTER. HARİKA İŞ. BAKALIM DEĞDİ Mİ.",
["pln_ed1_end_b_01"] = "GÜRÜLTÜLÜ YAPTINIZ, BENİ DE GURURLANDIRDINIZ. ŞİMDİ BAKALIM BUNCA PATIRTIYA DEĞDİ Mİ. YARIM VERİ TABANI HİÇ YOKTAN İYİDİR. BAKALIM ELİMİZDE NE VAR.",
["pln_ed1_end_b_02"] = "İŞİ DOĞRU YAPTIYSANIZ GÜRÜLTÜ ÇIKMASI SORUN DEĞİL. ŞİMDİ VERİLERİ ARAŞTIRIYORUM. YARIM VERİ TABANI BİRAZ PİYANGO GİBİ; UMALIM DA ŞANSIMIZ YAVER GİTSİN.",
["pln_ed1_end_c_01"] = "EFSANE BİR DAYAK ATTINIZ, ÜSTÜNE BÜTÜN VERİ TABANINI ALDINIZ. UMARIM GEREKENİ BULABİLİRİM DE DÖKTÜĞÜNÜZ KANA DEĞER.",
["pln_ed1_end_c_02"] = "SES ÇIKARMANIZ GEREKİYORSA BARİ HAKKINI VERİN. MÜTHİŞ BİR AKSİYONDU. BÜTÜN VERİ TABANINI ALDINIZ. ŞİMDİ BİLGİLERİ TARIYORUM...",
["pln_ed1_intro_a_01"] = "PİER 39. OY MAKİNELERİNİ WASHINGTON'A GÖTÜREN KAMYONU İŞARETLEYİP BURAYA DÖNÜN. TEKRAR SÖYLÜYORUM, SADECE KAMYON İÇİN BURADAYIZ.",
["pln_ed1_intro_a_02"] = "PİER 39. OY MAKİNELERİNİN BULUNDUĞU KAMYONU BULUN. WASHINGTON'A GİDECEK. HANGİSİ OLDUĞUNU ÇÖZÜN, TAKİP CİHAZINI TAKIP DEFOLUN. SESSİZ KALIN.",
["pln_ed1_intro_a_03"] = "KAMYONLAR RIHTIMIN HEMEN ÖBÜR TARAFINDA. DOĞRUSUNU BULUN, TAKİP CİHAZINI TAKIN VE ÇIKIN.",
["pln_ed2_01_01"] = "İLK İŞİNİZ DEPOYA GİRMEK. BÖLGEYİ KEŞFEDİN, KAMERA VE MUHAFIZLARI KONTROL EDİN. SESSİZ KALIN.",
["pln_ed2_01_02"] = "ÖNCE DEPOYA GİRMENİZ GEREKİYOR. SESSİZ KALMAYA ÇALIŞIN. SESSİZ YAPAMIYORSANIZ HIZLI YAPIN.",
["pln_ed2_01_03"] = "ÖNCE DEPOYA GİRMELİSİNİZ. SESSİZ KALABİLİRSENİZ HARİKA OLUR.",
["pln_ed2_01_any_01"] = "AÇILDI, EŞYALARIMIZI GERİ ALIN.",
["pln_ed2_02_01"] = "İÇERİDESİNİZ. HEDEFİMİZ OY MAKİNELERİ. MUHTEMELEN NAKLİYE SANDIKLARINDALAR, ETRAFTA SANDIK ARAYIN.",
["pln_ed2_02_02"] = "TAMAM, İÇERİ GİRDİĞİNİZE GÖRE MAKİNELERİN PEŞİNE DÜŞELİM. MUHTEMELEN KAPALI SANDIKLARDALAR, SANDIKLAR İÇİN GÖZÜNÜZÜ AÇIK TUTUN.",
["pln_ed2_02_03"] = "SONRAKİ HEDEFİNİZ OY MAKİNELERİ. BAHSE GİRERİM KAPALI SANDIKLARDA TUTULUYORLARDIR. SİZ PALYAÇOLAR AÇMAK İÇİN DOĞAÇLAMA YAPMAK ZORUNDASINIZ.",
["pln_ed2_03_01"] = "MAKİNELERE ULAŞMAK İÇİN NAKLİYE SANDIKLARINI BULMALISINIZ.",
["pln_ed2_03_02"] = "NAKLİYE SANDIKLARINI ARAMALISINIZ. MAKİNELER BÜYÜK İHTİMALLE İÇLERİNDE.",
["pln_ed2_03_03"] = "ONLARI AÇACAK BİR ŞEY BULUNCA SANDIKLARI ARAMAYA BAŞLAYIN.",
["pln_ed2_04_01"] = "ŞU NAKLİYE SANDIKLARI SİVRİSİNEĞİN GÖTÜNDEN BİLE SIKI KAPALI. ZORLA AÇACAK BİR ŞEY BULMANIZ GEREKİYOR.",
["pln_ed2_04_02"] = "O SANDIKLARI AÇACAK BİR ŞEY ARAYIN.",
["pln_ed2_05_01"] = "HARİKA! OY MAKİNELERİMİZDEN BİRİ BU! YAKINDA KİMSE YOKKEN SİSTEMİNİ KIRIN. NE YAPTIĞINIZI GÖRÜRLERSE SİLAHLAR KONUŞUR.",
["pln_ed2_05_02"] = "BU KESİN OY MAKİNELERİNDEN BİRİNE BENZİYOR. DEMOKRASİYİ ÖLDÜRMEYE HAZIR OLDUĞUNUZDA SİSTEMİ KIRMAYA BAŞLAYIN. KİMSE GÖRMESİN.",
["pln_ed2_05_03"] = "OY MAKİNELERİNDEN BİRİ BU. AFERİN! TAMAM, ETRAF SAKİNKEN SİSTEMİNİ KIRMAYA BAŞLAYIN. ",
["pln_ed2_06_01"] = "MAKİNELERDEN BİRİ BU. SİSTEMİ KIRMAYA BAŞLAYIN VE POLİSLERİN KÜÇÜK SİYASİ SABOTAJIMIZA KARIŞMASINA İZİN VERMEYİN.",
["pln_ed2_06_02"] = "BİZİM MAKİNELERDEN BİRİNE BENZİYOR. SİSTEMİNİ KIRMAYA BAŞLAYIN, SONRA FEDERALLERİ UZAK TUTUN. ",
["pln_ed2_06_03"] = "HARİKA! BİR MAKİNE BULDUNUZ. TAMAM, HACK İŞLEMİNİ BAŞLATIP BİTMESİNİ BEKLEYİN.",
["pln_ed2_07_01"] = "İLK MAKİNE HACKLENDİ. O SANDIĞI KAPATMAYI UNUTMAYIN. KİMSE ŞÜPHELENMESİN.",
["pln_ed2_07_02"] = "HARİKA, BUNUN SİSTEMİ KIRILDI. O SANDIĞI KAPATIN, SONRA BAŞKA BİR TANE BULUN.",
["pln_ed2_07_03"] = "MAKİNE TAMAM. THE ELEPHANT'I SEVİNDİRİR. ŞİMDİ SANDIĞI KAPATIP DEVAM EDİN.",
["pln_ed2_08_01"] = "TAMAM, İLK MAKİNE HACKLENDİ. DEVAM EDİN.",
["pln_ed2_08_02"] = "MAKİNE TAMAM. DEVAM EDİN. THE ELEPHANT, ADAMININ BÜYÜK FARKLA KAZANDIĞINDAN EMİN OLMAK İSTİYOR.",
["pln_ed2_08_03"] = "ONUN SİSTEMİNİ KIRDIK. GÖZÜNÜZ ÜSTÜNDE OLSUN.",
["pln_ed2_09_01"] = "FARK EDİLDİNİZ! LANET OLSUN, ORTALIK KARIŞACAK. SİZ SİSTEMLERİ KIRMAYA DEVAM EDİN, BEN BİR ŞEY DÜŞÜNÜRÜM.",
["pln_ed2_09_02"] = "İŞTE ALARM. POLİS YOLDA. MAKİNELERİN SİSTEMİNİ KIRMAYA DEVAM EDİN. YENİ BİR PLAN DÜŞÜNECEĞİM.",
["pln_ed2_09_03"] = "ALARM ÇALDI. MPD MÜDAHALE KANALLARI AZ ÖNCE ÇILDIRDI. TAMAM, ÖNEMLİ DEĞİL. O MAKİNELERİ HACKLEMEYE DEVAM EDİN.",
["pln_ed2_10_01"] = "TAMAM, BİR FİKRİM VAR. SIZMAYI DEĞİŞTİRİP BUNU MCKENDRİCK'İN RAKİBİ BELEDİYE BAŞKANI SCHWARTZ İÇİN YAPMIŞIZ GİBİ GÖSTEREBİLİRİM. SUÇU ONUN ÜZERİNE ATABİLİRİZ. SKANDAL ÇIKACAKSA İŞİMİZE YARAYAN BİR SKANDAL OLSUN!",
["pln_ed2_10_02"] = "YENİ PLAN ŞU. HACK İŞLEMİNİ DEĞİŞTİRİP BÜTÜN BU İŞ BELEDİYE BAŞKANI SCHWARTZ İÇİN YAPILIYORMUŞ GİBİ GÖSTERECEĞİM. KİRLİ BİR OYUN AMA SİYASET BÖYLE.",
["pln_ed2_10_03"] = "B PLANI A PLANINA ÇOK BENZİYOR: SIZMAYA DEVAM EDİN. BENİM TARAFTAN BİRAZ KODLA BUNU BELEDİYE BAŞKANI NANCY İÇİN YAPMIŞIZ GİBİ GÖRÜNECEK. O MAKİNELERE SIZMAYA DEVAM!",
["pln_ed2_11_01"] = "MAKİNELERİN SİSTEMİNİ KIRMAYA DEVAM EDİN. SCHWARTZ'A NE KADAR BOK ATARSAK O KADARI TUTAR.",
["pln_ed2_11_02"] = "DAHA FAZLA MAKİNE HACKLEMELİSİNİZ. HER BİRİ SCHWARTZ'IN SKANDALINA SKANDAL KATIYOR.",
["pln_ed2_11_03"] = "MAKİNELERİN SİSTEMİNİ KIRIN MİLLET. BOZULAN HER MAKİNE SCHWARTZ'IN ÜZERİNDEKİ BASKIYI ARTIRACAK.",
["pln_ed2_12_01"] = "ORTALIK KARIŞTIĞI İÇİN BİRAZ TEMİZLİK YAPMALIYIZ. GÜVENLİK ODASINI BULUP KAMERA GÖRÜNTÜLERİNİ ALIN. KAYDETMELERİNİ İSTEMEDİĞİMİZ BİR ŞEY YAKALAMIŞ OLABİLİRLER.",
["pln_ed2_12_02"] = "TAMAM. SIVIŞMADAN ÖNCE BİR İŞ DAHA YAPMANIZI İSTİYORUM. GÜVENLİK ODASINA GİDİP KAMERA GÖRÜNTÜLERİNİ ALIN. ALEYHİMİZE BİR ŞEY KAYDETMİŞLERSE DİYE.",
["pln_ed2_12_03"] = "İŞ NEREDEYSE BİTTİ MİLLET. SON BİR ŞEY KALDI. GÜVENLİK ODASINDAN KAMERA KAYITLARINI ALIN. GÖRMELERİNİ İSTEMEDİĞİMİZ BİR ŞEYİ KAYDETMEDİKLERİNDEN EMİN OLMAK İSTİYORUM.",
["pln_ed2_13_01"] = "O GÜVENLİK ODASINA GİDİP GÖRÜNTÜLERİ ÇALIN! KAYBEDECEK VAKİT YOK.",
["pln_ed2_13_02"] = "GÜVENLİK ODASINI BULUN VE GÖRÜNTÜLERİ ALIN. KIÇINIZI KALDIRIN MİLLET.",
["pln_ed2_13_03"] = "KAMERA KAYITLARININ NEREDE TUTULDUĞUNU BULMALISINIZ. ACELE EDİN MİLLET.",
["pln_ed2_14_01"] = "TAMAM, ŞİMDİ GÖRÜNTÜLERİ MİNİBÜSE GETİRİN. HADİ!",
["pln_ed2_14_02"] = "HARİKA. ŞİMDİ O GÖRÜNTÜLERİ BURAYA GETİRİN, İŞİ BİTİRELİM.",
["pln_ed2_14_03"] = "TAMAM. GÜZEL İŞ PALYAÇOLAR. GÖRÜNTÜLERİ GETİRİN, İŞİ BİTİRELİM.",
["pln_ed2_15_01"] = "GİZLİCE SIVIŞMA VAKTİ! ŞİMDİ ORTALIĞI AYAĞA KALDIRMAYA GEREK YOK.",
["pln_ed2_15_02"] = "İŞ TAMAM MİLLET. ŞİMDİ SESSİZCE MİNİBÜSE DÖNÜN DE BU DOSYAYI KAPATALIM.",
["pln_ed2_15_03"] = "SONUNCUSU DA BU. SESSİZCE MİNİBÜSE DÖNÜN, BUNU İYİ YAPILMIŞ BİR İŞ SAYABİLİRİZ.",
["pln_ed2_16_01"] = "BU KEŞMEKEŞİ GERİDE BIRAKMA VAKTİ! HEMEN ÇIKIN ORADAN!",
["pln_ed2_16_02"] = "SAVAŞARAK MİNİBÜSE ÇEKİLİN MİLLET. ÇIKALIM BURADAN.",
["pln_ed2_16_03"] = "MİNİBÜSE DÖNÜN PALYAÇOLAR. BU KEŞMEKEŞTEN SIVIŞMA VAKTİ.",
["pln_ed2_17_01"] = "UNUTMAYIN, OY MAKİNELERİNİN PEŞİNDEYİZ. SONUCU MCKENDRİCK'İN LEHİNE ÇEVİRMEK İÇİN SİSTEMLERİNİ KIRMAMIZ GEREKİYOR. NAKLİYE SANDIKLARINA BAKIN.",
["pln_ed2_17_02"] = "NAKLİYE SANDIKLARINDA MAKİNELERİ ARAMAYA DEVAM EDİN. BULUNCA SİSTEMLERİNİ KIRMAYA BAŞLAYIN.",
["pln_ed2_17_03"] = "UNUTMAYIN, OY MAKİNELERİNİ ARIYORUZ. BENCE ETRAFA DAĞILMIŞ NAKLİYE SANDIKLARINDALAR.",
["pln_ed2_18_01"] = "GÖRÜNTÜLERİ ALANA KADAR ONLARI OYALAYIN.",
["pln_ed2_18_02"] = "FEDERALLERİ O GÖRÜNTÜLERDEN UZAK TUTUN MİLLET. BURADA NEREDEYSE İŞİMİZ BİTTİ.",
["pln_ed2_18_03"] = "AZ KALDI... AZ KALDI.",
["pln_ed2_19_01"] = "AZ ÖNCE THE ELEPHANT'TAN MESAJ GELDİ. GİZLİ KALDIĞINIZ İÇİN İKRAMİYENİZ BIRAKILMIŞ. KAÇIŞ MİNİBÜSÜNÜN YAKININDA.",
["pln_ed2_20_01"] = "BONUSUNUZ ORADA. MİNİBÜSE GÖTÜRÜN. HAK ETTİNİZ.",
["pln_ed2_99_01"] = "HADİ MİLLET, ŞU DEĞİŞİMİ DEĞİŞTİRELİM!",
["pln_ed2_brf_01"] = "KAMYONUN İZİNİ GOOSE ISLAND YAKINLARINDAKİ BİR DEPOYA KADAR SÜRDÜM. OY MAKİNELERİNİ SON VARIŞ NOKTALARINA GÖNDERMEKLE YÜKÜMLÜ BİR DAĞITIM DEPOSU. BİRAZ TEKNİK SİHİRLE O MAKİNELERİ THE ELEPHANT'IN BELEDİYE BAŞKANI ADAYINA, O KAYPAK MCKENDRİCK'E BİRAZ DAHA YAKINLAŞTIRACAĞIZ. GİRİN, HACKLEYİN, ÇIKIN. BASİT. BİR KEZ DAHA, SESSİZ KALABİLİRSENİZ THE ELEPHANT GİZLİLİK İKRAMİYESİ VERİYOR.",
["pln_ed2_end_a_01"] = "MUHTEŞEM BİR GİZLİLİK GÖSTERİSİYDİ. GÖLGELERDEN YAPILMIŞ GİBİSİNİZ. MAKİNELERİN SİSTEMİ KIRILDI, OYLAR AKIYOR, THE ELEPHANT'IN ADAMI EZİCİ FARKLA KAZANDI. TANRI DEMOKRASİYİ KORUSUN!",
["pln_ed2_end_a_02"] = "MÜKEMMEL İŞ. BU GECE SİZ PALYAÇOLAR YÜKSEK MEVKİDE BİR DOST EDİNDİNİZ. BU ŞEHİRDE BİR DAHA PARK CEZASI ÖDEMEYECEKSİNİZ.",
["pln_ed2_end_b_01"] = "İŞLER KARIŞTI AMA SONUNDA BAŞARDINIZ. SİSTEMLERİ KIRMAK İŞE YARADI. BUNUN ARKASINDA SEVGİLİ BELEDİYE BAŞKANIMIZIN ADAMLARI VARMIŞ GİBİ GÖRÜNÜYOR. BASIN SCHWARTZ İÇİN BIÇAKLARI BİLEMEYE BAŞLADI. THE ELEPHANT'IN HAVALARA UÇTUĞUNU SÖYLEMEYE GEREK YOK. BU GECE ŞEHRİNİZE İYİ HİZMET ETTİNİZ DOSTLARIM.",
["pln_ed2_end_b_02"] = "HARİKA İŞ! SİSTEMİ KIRILAN MAKİNELER, BU İŞİN ARKASINDA BELEDİYE BAŞKANININ ADAMLARI VARMIŞ GİBİ GÖSTERDİ. SORUŞTURMA ONU AKLASA BİLE GAZETELER BAŞKANA O KADAR BOK ATIYOR Kİ ARTIK İŞİ BİTTİ. PEKİ THE ELEPHANT? ONUN ADAMI BELEDİYE BİNASI İÇİN YENİ MOBİLYA SEÇİYOR. HARİKA İŞ EKİP!",
["pln_ed2_intro_a_01"] = "BURADA KENARA ÇEK. DEPO İLERİDE. HADİ YAPALIM ŞU İŞİ.",
["pln_ed2_intro_a_02"] = "MAKİNELERİN TUTULDUĞU DEPO ORASI. HAREKET EDİN PALYAÇOLAR.",
["pln_ed2_intro_a_03"] = "OY MAKİNELERİNİN TUTULDUĞU DEPO ORASI. BİRAZ SİYASET MÜHENDİSLİĞİ YAPMA VAKTİ.",
["pln_ed3_01_01"] = "UNUTMAYIN, BUNA BANKA SOYGUNU SÜSÜ VERMEK İÇİN BURADAYIZ. BU SIRADA BAZI SEÇİM EKİPMANLARI PARÇALANIRSA NE YAZIK. OY SONUÇLARI BİR ŞEKİLDE KULLANILAMAZ HÂLE GELİRSE DE GERÇEKTEN ÇOK YAZIK OLUR...",
["pln_ed3_01_02"] = "ŞİMDİ UNUTMAYIN, BURAYA BANKA SOYMAYA GELDİK. AMA KAZARA BİR İKİ, HATTA ÜÇ OY MAKİNESİNİ KURŞUNLARSANIZ... EH, ŞANSLARINA KÜSSÜNLER. ANLAŞILDI MI?",
["pln_ed3_02_01"] = "ETRAFI KOLAÇAN EDİN MİLLET. BANKAYI VE OY VERME YERİNİ BULUN. SONRA İKİSİNE DE GİRİN.",
["pln_ed3_02_02"] = "ORTALIĞI KARIŞTIRMADAN ÖNCE MEKÂNI KOLAÇAN EDİN. BELKİ DAHA İYİ BİR YOL VARDIR.",
["pln_ed3_02_03"] = "SİLAHLARI KONUŞTURMADAN ÖNCE ETRAFA BAKMAK İYİ FİKİR OLABİLİR. EN İYİ YAKLAŞIMI BULUN.",
["pln_ed3_03_01"] = "SONUÇLARIN BULUNDUĞU SUNUCU BURALARDA BİR YERDE OLMALI. BULUN VE OYLARI KULLANILAMAZ HÂLE GETİRİN.",
["pln_ed3_03_02"] = "YAKINLARDA BİR SUNUCU OLMALI. OYLAR ONUN İÇİNDE. BULUP SİLİN.",
["pln_ed3_03_03"] = "OY SONUÇLARI YAKINDAKİ BİR SUNUCUDA SAKLANIYOR. ONU BULUP VERİLERİ BOZUN.",
["pln_ed3_04_01"] = "TAMAM, SUNUCU BU. KARIŞTIRICIYI TAKIN. ",
["pln_ed3_04_02"] = "ARADIĞIMIZ SUNUCU BU GİBİ. VERİ BOZUCUYU ÇALIŞTIRIN.",
["pln_ed3_05_01"] = "LANET OLSUN, ŞU UCUZ, BOKTAN RUS KARIŞTIRICISI ÇÖKTÜ. YENİDEN ÇALIŞTIRIN.",
["pln_ed3_05_02"] = "VERİ BOZUCU YAZILIM ÇÖKTÜ GALİBA. BOKTAN KOD. YENİDEN BAŞLATIN!",
["pln_ed3_05_03"] = "O VERİ BOZUCULARI VLAD'DAN ALDIM. (VLAD'I TAKLİT EDER) EN İYİ RUS TEKNOLOJİSİ. YALANCI PİÇ.",
["pln_ed3_06_01"] = "LANET SİNYAL BOZUCU YİNE DURDU. TAMİR EDİN!",
["pln_ed3_06_02"] = "BOK PARÇASI YİNE ÇÖKTÜ. VERİ BOZUCUYU YENİDEN BAŞLATIN!",
["pln_ed3_07_01"] = "SANIRIM BİTMEK ÜZERE... DURUN... BEKLEYİN... SİKTİR! YİNE ÇÖKTÜ. YENİDEN BAŞLATIN.",
["pln_ed3_08_01"] = "TAMAM, VERİLERİ BOZDUK. SIRADAN BİR SABİT DİSK ARIZASI GİBİ GÖRÜNECEK. ",
["pln_ed3_08_02"] = "TAMAM, VERİLER KARIŞTI! SIRADAN BİR VERİ HATASI GİBİ GÖRÜNECEK.",
["pln_ed3_08_03"] = "VERİLER KARIŞTI. İYİ İŞ. KASITLI OLDUĞUNU ANLASALAR BİLE SONUÇLAR KULLANILAMAZ. HARİKA İŞ.",
["pln_ed3_09_01"] = "ŞİMDİ O DUVARI PATLATIP AÇIN! PATLAMA OY MAKİNELERİNİ PARÇALAYACAK.",
["pln_ed3_09_02"] = "DUVARI PATLATMAK OY MAKİNELERİNİ MAHVEDECEK. KAZA, DEĞİL Mİ? BİZ SADECE DÜRÜST BİR BANKA SOYGUNU YAPIYORUZ.",
["pln_ed3_09_03"] = "BANKAYA DALMA VAKTİ! PATLAMA OY MAKİNELERİNİN İŞİNİ BİTİRECEK.",
["pln_ed3_10_01"] = "GÜM! DUVAR TARİH OLDU. BİRKAÇ MAKİNEYİ DE GÖTÜRMÜŞ OLMALI.",
["pln_ed3_10_02"] = "DUVAR GİTTİ. BİRKAÇ OY MAKİNESİ DE GÜME GİTTİ GALİBA. ŞİMDİ İLERLEYİN!",
["pln_ed3_10_03"] = "DUVAR GİTTİ. ŞİMDİ İÇERİ GİRİN.",
["pln_ed3_11_01"] = "TAMAM. KÜÇÜK OYUNUMUZUN İKİNCİ PERDESİ: KASA DAİRESİNİ AÇIN.",
["pln_ed3_11_02"] = "VAKİT GEÇİYOR. O KASA DAİRESİNİ AÇMAYA HEMEN BAŞLAYIN!",
["pln_ed3_12_01"] = "HADİ, ŞU KASA DAİRESİNİ AÇIN.",
["pln_ed3_13_01"] = "HADİ MİLLET, PARAYI ALMA VAKTİ.",
["pln_ed3_13_02"] = "KASA DAİRESİ AÇIK. BU NUMARA NEREDEYSE BİTTİ. BİRAZ PARA ÇANTALAYIN!",
["pln_ed3_14_01"] = "KASA DAİRESİNE GİRİN MİLLET. İÇİNDE NE VAR BAKIN!",
["pln_ed3_14_02"] = "KASA DAİRESİ AÇIK. İÇİNDE NE VAR BAKMA VAKTİ.",
["pln_ed3_14_03"] = "AÇIL SUSAM AÇIL AMINA KOYAYIM. BAKALIM NE VARMIŞ ORADA.",
["pln_ed3_15_01"] = "NE GÖRÜYORSUNUZ? BURASI TAMTAKIR. NEYSE, GELDİĞİMİZ İŞİ YAPTIK, ÇIKIN ORADAN.",
["pln_ed3_15_02"] = "GÖRÜNÜŞE GÖRE BOKLU DEĞNEĞİN UCUNU BİZ TUTTUK. KASA DAİRESİ BOŞ! HEMEN ÇIKIN ORADAN!",
["pln_ed3_16_01"] = "NE DERSİNİZ MİLLET? İÇERİSİ OLDUKÇA İYİ GÖRÜNÜYOR. TAŞIYABİLDİĞİNİZİ ALIN!",
["pln_ed3_16_02"] = "KASA DAİRESİ PARA DOLU GİBİ. NE KADARINI ALIP KAÇACAĞINIZ SİZE KALMIŞ.",
["pln_ed3_17_01"] = "HADİ PALYAÇOLAR, KIÇINIZI KALDIRIP ÇIKIN!",
["pln_ed3_17_02"] = "KAÇIŞ ARABASINA GİDİN!",
["pln_ed3_18_01"] = "SİZE KAÇIŞ MİNİBÜSÜ BULDUM, ANA GİRİŞİN HEMEN DIŞINDA!",
["pln_ed3_18_02"] = "FIRLAMA VAKTİ! KAÇIŞ MİNİBÜSÜ ANA GİRİŞİN YAKININDA PARK ETTİ!",
["pln_ed3_19_01"] = "KAMERALAR BAŞINIZA BELA OLUYORSA ETRAFTA BİR KAMERA OPERATÖRÜ VAR. GÜVENLİK OFİSİNDE.",
["pln_ed3_19_02"] = "YAKINDA BİR GÜVENLİK OFİSİ VAR. GÖZETLEME SİSTEMLERİNDEN KURTULMAK İSTERSENİZ DİYE SÖYLÜYORUM.",
["pln_ed3_20_01"] = "O KAMERALAR ARTIK SORUN OLMAYACAK!",
["pln_ed3_20_02"] = "BU, BURNUNU SOKAN PİÇLERİN İŞİMİZİ GÖZETLEMESİNİ ENGELLER. GÜZEL.",
["pln_ed3_20_03"] = "KAMERALARDAN SORUMLU ADAM DEVRE DIŞI. ARTIK O KAMERALAR SİZİ RAHATSIZ ETMEZ!",
["pln_ed3_21_01"] = "BANKANIN KEPENKLERİ GÜVENLİK OFİSİNDEN KAPATILABİLİYOR. POLİSLERİ UZAK TUTMANIZA YARDIM EDERLER!",
["pln_ed3_21_02"] = "BANKADA SOYGUN ÖNLEYİCİ KEPENKLER VAR. GÜVENLİK OFİSİNDEN KAPATIN. POLİSLERİ YOLUNUZDAN UZAK TUTMAYA YARAR.",
["pln_ed3_21_03"] = "GÜVENLİK OFİSİNDE BİR KONTROL ŞALTERİ VAR. BANKANIN KEPENKLERİNİ KAPATIYOR. FEDERALLERİ BANKADAN UZAK TUTMANIZA YARDIM EDER.",
["pln_ed3_22_01"] = "GÖRÜNÜŞE GÖRE YAKINDAKİ ÇATILARA KESKİN NİŞANCI YERLEŞTİRİYORLAR. GÖZÜNÜZÜ DÖRT AÇIN!",
["pln_ed3_22_02"] = "DİKKAT. KESKİN NİŞANCILAR BÖLGEYE YERLEŞİYOR!",
["pln_ed3_22_03"] = "EVET, ÇATILARDA KESKİN NİŞANCI EKİPLERİ GÖRÜYORUM. KENDİNİZE DİKKAT EDİN.",
["pln_ed3_23_01"] = "ŞİMDİLİK HER ŞEY YOLUNDA PALYAÇOLAR.",
["pln_ed3_23_02"] = "SAKİN SAKİN İLERLİYORSUNUZ. SİZİ HENÜZ FARK ETMEDİLER.",
["pln_ed3_23_03"] = "AZ KALDI. ÇOK AZ.",
["pln_ed3_23_04"] = "AYNEN DEVAM EDİN. KİTAPLARA GEÇECEK BİR İŞ ÇIKARIYORSUNUZ.",
["pln_ed3_23_05"] = "HENÜZ SİZİ GÖRMEDİLER. HÂLÂ İYİYİZ.",
["pln_ed3_23_06"] = "HÂLÂ İYİ. HÂLÂ İYİ.",
["pln_ed3_24_01"] = "ASANSÖRDE BİR ŞEY VAR... BEKLEYİN... BİRAZ ZAMAN VERİN.",
["pln_ed3_25_01"] = "NE OLUYOR LAN? YANLIŞ ASANSÖR BU. BEKLEYİN.",
["pln_ed3_26_01"] = "TAMAM, ANLADIM. BAŞLIYORUZ.",
["pln_ed3_27_01"] = "MIZRAĞI ASANSÖRLE YOLLUYORUM. HAZIR OLUN MİLLET.",
["pln_ed3_27_02"] = "GİDİP TERMAL MIZRAĞI ALIN BELALILAR!",
["pln_ed3_99_01"] = "HADİ MİLLET, ŞU DEĞİŞİMİ DEĞİŞTİRELİM!",
["pln_ed3_brf_b_01"] = "SİZİ PİSLİKLER, İŞARETLEDİĞİNİZ KAMYON YANLIŞMIŞ. O OY MAKİNELERİNİN ÖNÜNÜ KESMEYİ UNUTABİLİRİZ. ELEPHANT'I MEMNUN TUTMAK İÇİN BAŞKA BİR ŞEY DENEYECEĞİZ. OY VERME YERİNDEKİ SUNUCUYU BOZARAK SEÇİMİN YENİLENMESİNİ SAĞLAYABİLİRİZ. SPONSORUMUZA ŞÜPHE ÇEKMEMEK İÇİN YANDAKİ BANKAYI SOYUP BUNU KAZARA OLUŞAN BİR HASAR GİBİ GÖSTERECEĞİZ.",
["pln_ed3_brf_c_01"] = "YÜKLEDİĞİNİZ SEVKİYAT VERİLERİNDEN DOĞRU KAMYONU BULAMADIM. OY MAKİNELERİNİN ÖNÜNÜ KESEMEYECEĞİZ. AMA ELEPHANT'I YİNE DE MEMNUN EDEBİLİRİZ. OY VERME YERİNİN YANINDA BİR BANKA VAR. ORAYI SOYACAĞIZ. ASLINDA TAM OLARAK SOYMAYACAĞIZ, ÇÜNKÜ GERÇEK HEDEFİNİZ YAN TARAFTAKİ SEÇİM SONUÇLARININ BULUNDUĞU SUNUCU. BANKAYA GİRİN, KASA DAİRESİ'Nİ AÇIN, BİLDİĞİNİZ ŞEYLERİ YAPIN. AMA ASIL HEDEFİN O OY VERME YERİNİ MAHVETMEK OLDUĞUNU UNUTMAYIN.",
["pln_ed3_end_a_01"] = "HARİKA İŞ! SMOKİNLERİN TOZUNU ALMA VAKTİ EKİP. GÖREVE BAŞLAMA BALOSUNUN DAVETİYELERİ POSTAYA VERİLDİ.",
["pln_ed3_end_a_02"] = "BU UFAK SİYASET MÜHENDİSLİĞİNİ YILLARCA OKUTMALILAR. MUHTEŞEM, EKİP. MUHTEŞEM!",
["pln_ed3_end_a_03"] = "SİZ PALYAÇOLAR WASHINGTON SİYASETİNİN EN HEYECANLI, MUHTEMELEN DE EN DÜRÜST BÖLÜMÜNÜ YAZDINIZ. HARİKA İŞ!",
["pln_ed3_intro_a_01"] = "SİYASET PİSLİK OLABİLİR AMA GÜZEL YANI, DAİMA İKİNCİ BİR ŞANSINIZ OLUR. İÇERİ GİRİP İŞİNİZİ YAPIN.",
["pln_ed3_intro_a_02"] = "BU ŞEHRİN NİXON'DAN BERİ GÖRDÜĞÜ EN BÜYÜK SİYASİ GERİ DÖNÜŞE İMZA ATMA ŞANSIMIZ VAR. GİRİN İÇERİ PALYAÇOLAR.",
["pln_ed3_intro_a_03"] = "THE ELEPHANT'IN ADAMINI MAKAMA GETİRMESİNE YARDIM ETMEK İÇİN SON ŞANSIMIZ. İŞE KOYULUN, EKİP.",
["pln_election_stage1_01_any_01"] = "TAMAM MİLLET, KAMYONLAR HER AN GİDEBİLİR. OY MAKİNELERİ HANGİSİNDEYSE BULUN VE GPS TAKİP CİHAZINI TAKIN. BURALARDA İPUCU VEREBİLECEK BİR ŞEY OLMALI.",
["pln_election_stage1_02_any_01"] = "HANGİSİ OLDUĞUNU BULDUĞUNUZDA TAKİP CİHAZINI KAMYONUN ALTINA YERLEŞTİRİN.",
["pln_election_stage1_03_any_01"] = "İLKİ GİTMEYE HAZIRLANIYOR GİBİ. DOĞRU KAMYONUN O OLDUĞUNU DÜŞÜNÜYORSANIZ ACELE EDİP İŞARETLESENİZ İYİ OLUR.",
["pln_election_stage1_04_any_01"] = "SIRADAKİ DE GİDİYOR. UMARIM DOĞRU OLAN O DEĞİLDİ.",
["pln_election_stage1_05_any_01"] = "ARTIK BİR TANE KALDI, BARİ ONU İŞARETLEYİN...",
["pln_election_stage1_06_any_01"] = "HARİKA, TAMAMDIR. BURADAN ÇIKALIM DA DOĞRU KAMYON MUYMUŞ ÖĞRENELİM.",
["pln_election_stage1_07_any_01"] = "SİKTİR, GİDİYORLAR! KUSURA BAKMAYIN MİLLET, B PLANI GİBİ GÖRÜNÜYOR. BURADAN ÇIKIP BAŞKA YERDE HALLEDELİM.",
["pln_election_stage1_08_any_01"] = "İYİ DÜŞÜNDÜNÜZ. OY MAKİNELERİ 6. BÖLGEDEKİ AVM'YE GİDİYOR. O BÖLGEYE SEVKİYAT YAPAN ŞİRKETİ BULMAYA ÇALIŞIN.",
["pln_election_stage1_brief_01"] = "OY MAKİNELERİ BUGÜN KAMYONLA LİMANA GELİYOR. HANGİ KAMYON OLDUĞUNU BİLMİYORUZ AMA VARIŞ YERİNİN SHIELD MALL OLDUĞUNU BİLİYORUZ.",
["pln_election_stage1_brief_01b"] = "YAPMAMIZ GEREKEN İÇERİ GİRİP KONTEYNERLERİ TAŞIYAN KAMYONA BİR GPS VERİCİSİ YERLEŞTİRMEK VE FARK EDİLMEDEN ÇIKMAK. KOLAY.",
["pln_election_stage1_end_a_01"] = "GPS ÇALIŞIYOR. GÜZERGÂH ELİMDE... ŞİMDİ SADECE PUSUYU HAZIRLAYIP İZLERİ ÖRTMELİYİZ. BİRKAÇ OYU DEĞİŞTİRELİM Mİ?",
["pln_election_stage1_end_a_02"] = "TAMAM, KAMYON YOLA ÇIKIYOR VE GPS ÇALIŞIYOR. GÜZEL İŞ. TARİHİ KENDİ YOLUMUZLA DEĞİŞTİRME VAKTİ.",
["pln_election_stage1_end_b_01"] = "LANET OLSUN... YETERİNCE GİZLİ DEĞİLDİK. O KAMYONDAKİ GPS ARTIK ANLAMSIZ. BUNDAN SONRA ÇOK DİKKATLİ DAVRANIP OY MAKİNELERİNİN ROTASINI FALAN DEĞİŞTİRECEKLER. ONLARA ULAŞMANIN BİR YOLUNU BULMALIYIZ.",
["pln_election_stage1_end_b_02"] = "BU DA BURAYA KADARMIŞ. B PLANI LAZIM. HÂLÂ SEÇİME BİR ŞEKİLDE MÜDAHALE ETMELİYİZ... ALIŞVERİŞ MERKEZİNE GİTME VAKTİ.",
["pln_election_stage1_intro_a_01"] = "TAMAM EKİP, İŞTE BU. KAMYONLAR GİTMEYE HAZIRLANIYOR GİBİ. ACELE EDİP KONTEYNERİ TAŞIYANI BULUN. GPS HAZIR. HAREKETE GEÇİN.",
["pln_election_stage1_intro_a_02"] = "ALIŞVERİŞ MERKEZİNE GİDEN KAMYONU BULUN. GPS'İ YAPIŞTIRIP SIVIŞIN. KAMYONA SONRA PUSU KURACAĞIZ, SÖZ.",
["pln_election_stage1_intro_a_03"] = "OY MAKİNELERİ YOLA ÇIKIYOR, KAMYONLARIN MOTORLARINI ÇALIŞTIRDIĞINI DUYUYORUM. ÇABUCAK DOĞRU KAMYONA GİDİP TAKİP CİHAZINI TAKIN, SONRA DA ORADAN DEFOLUN. MÜMKÜNSE GİZLİCE.",
["pln_election_stage2_01_any_01"] = "DOĞRU KAMYONU İŞARETLEMİŞİZ! İYİ İŞ, GİDİP AÇALIM.",
["pln_election_stage2_02_any_01"] = "UNUTMAYIN, DİĞER KAMYONLAR BİZİM! AMA GANİMETİMİZİ GERİ İSTİYORUZ. POLİSLERİN DİKKATİNİ OY MAKİNELERİNDEN UZAKLAŞTIRMAK İÇİN ONLARI KULLANIN.",
["pln_election_stage2_03_any_01"] = "CİHAZI ÇALIŞTIRDIĞIMIZDA SIZMA CİHAZINI GÖRMELERİNE SAKIN İZİN VERMEYİN!",
["pln_election_stage2_04_any_01"] = "KONVOYDAKİ POLİSLERİ HALLEDİN DE KAMYONLARI AÇALIM!",
["pln_election_stage2_05_any_01"] = "POLİS VE SWAT EKİPLERİ OLAY YERİNE GELİYOR, DİKKATLİ OLUN.",
["pln_election_stage2_06_any_01"] = "GÜZEL, KAMYON AÇILDI. GİRİP HACK CİHAZINI OY MAKİNELERİNE TAKIN.",
["pln_election_stage2_07_any_01"] = "HİÇBİR POLİS YA DA SWAT'IN SIZMA CİHAZINI GÖRMESİNE İZİN VERMEYİN. ONLARI OY MAKİNELERİNİN BULUNDUĞU KAMYONA YAKLAŞTIRMAYIN!",
["pln_election_stage2_08_any_01"] = "DEVAM ETMEK İÇİN SİSTEM KIRMA CİHAZININ YENİDEN BAŞLATILMASI GEREKİYOR.",
["pln_election_stage2_08_any_02"] = "CİHAZI YENİDEN BAŞLATMANIZ GEREK...",
["pln_election_stage2_08_any_03"] = "SÖZDE TAMİR ETTİĞİNİZ SİSTEM KIRMA CİHAZI YİNE SIKIŞTI. YENİDEN BAŞLATMANIZ GEREKİYOR.",
["pln_election_stage2_09_any_01"] = "GÜZEL, MAKİNELERİN SİSTEMLERİ KIRILDI. DİĞER KAMYONLARDAN İSTEDİKLERİNİZİ ALIN DA ÇIKALIM BURADAN.",
["pln_election_stage2_10_any_01"] = "UNUTMAYIN, O KAMYONLARDAKİ HER ŞEY SİZİN. GERİ GÖTÜRMEZSENİZ PARA KAYBEDERSİNİZ.",
["pln_election_stage2_11_any_01"] = "HAZIR OLDUĞUNUZDA MİNİBÜSE DÖNÜN DE BURADAN GİDELİM.",
["pln_election_stage2_12_any_01"] = "AH HAYIR! SİSTEM KIRMA CİHAZINI GÖRÜP HABER VERDİLER. B PLANI MİLLET!",
["pln_election_stage2_13_any_01"] = "KAMYONA GİDİP BENZİNİ ALIN. ARTIK TEK ÇARE KAMYONU YAKIP DELİLLERDEN KURTULMAK.",
["pln_election_stage2_14_any_01"] = "ŞİMDİ ÖDEME OLABİLECEĞİNDEN DAHA DÜŞÜK. BİR DAHAKİ SEFERE ONLARI UZAK TUTUP MAKİNELERE SIZMAYA ÇALIŞIN.",
["pln_election_stage2_15_any_01"] = "GÜZEL, YANIYOR. DİĞER KAMYONLARDAN İSTEDİKLERİNİZİ HENÜZ ALMADIYSANIZ ALIN DA GİDELİM.",
["pln_election_stage2_16_any_01"] = "AFERİN MİLLET. THE ELEPHANT MEMNUN OLACAK, KİMSE BİR ŞEYDEN ŞÜPHELENMİYOR.",
["pln_election_stage2_17_any_01"] = "BAŞARDINIZ AMA KAMYONU YAKMASAYDINIZ BİZİM İÇİN DAHA İYİ OLURDU. BİR DAHAKİ SEFERE BİRAZ DAHA İNCELİKLİ OLUN.",
["pln_election_stage2_brief_01"] = "GPS'İ KAMYONA YERLEŞTİREREK İYİ İŞ ÇIKARDINIZ. SONRAKİ İŞİ GÜNDÜZ VAKTİ YAPACAĞIZ. BASKIN GİBİ GÖRÜNECEK.",
["pln_election_stage2_brief_01b"] = "VİCDANSIZ BİRKAÇ GENSEC GÖREVLİSİNE RÜŞVET VERİP HEDEF KAMYONUMUZUN ÖNÜNDEN DEĞERLİ YÜK TAŞIYAN BİR ŞAŞIRTMACA ARACI GÖNDERTTİM. HEDEFİMİZ GİBİ GÖRÜNECEK AMA ELBETTE O DEĞİL.",
["pln_election_stage2_brief_01c"] = "YATIRIMIMIZI GERİ ALIN VE MAKİNELERİ DEĞİŞTİRİN.",
["pln_election_stage2_end_a_01"] = "İYİ İŞ. BÜTÜN MAKİNELER YENİDEN AYARLANDI. THE ELEPHANT BU BÖLGEDE ALIŞILMADIK DERECEDE GÜÇLÜ BİR SONUÇ ALACAK.",
["pln_election_stage2_end_a_02"] = "DEMOKRASİ KORUNDU, KENDİSİNDEN. THE ELEPHANT İSTEDİĞİNİ ALACAK. MAKİNELER HAYATINI GÜZELLEŞTİRECEK. İTİRAZ EDİLSE BİLE ONUN İŞİNE GELİR. HER TÜRLÜ KAZANIYOR.",
["pln_election_stage2_end_a_03"] = "KARGO DOLANDIRICILIĞINA YATIRIM YAPMADIĞIMIZ İÇİN ŞAŞIRTMACAMIZ YOKTU. AMA EN AZINDAN OY MAKİNELERİNİ YENİDEN PROGRAMLADIK, KİMSE DE GÖRMEDİ... UMARIM TUTAR.",
["pln_election_stage2_end_b_01"] = "EH, BU İKİNCİ TERCİH BİR ÇÖZÜMDÜ. AÇIKÇASI BEN TERCİH ETMEZDİM. AMA EN AZINDAN O MAKİNELERDE OY KULLANILAMAYACAK. ÖDEME VAKTİ.",
["pln_election_stage2_end_b_02"] = "EH, İDEAL DEĞİL AMA SEÇİMİ BİRAZ YÖNLENDİRİP İNSANLARI SONUCUN MEŞRULUĞUNDAN ŞÜPHEYE DÜŞÜREBİLDİK. BENCE THE ELEPHANT İSTEDİĞİNİ ALACAK. ŞİMDİ PARA ALMA VAKTİ.",
["pln_election_stage2_intro_a_01"] = "TAMAM. GİRİN, DOĞRU KAMYONU VE OY MAKİNELERİNİ BULUN. BULUNCA OYLARI DEĞİŞTİRECEK ŞEKİLDE YENİDEN PROGRAMLAYIN, SONRA GENSEC GANİMETİYLE DÖNÜN. TEK İŞTE İKİ SOYGUN. TADINI ÇIKARIN.",
["pln_election_stage2_intro_a_02"] = "LİMANDAN GELEN KAMYONU BULUP İÇERİ GİRİN. KİMSEYE GÖRÜNMEDEN MAKİNELERİ YENİDEN PROGRAMLAYIN. OLANLARI ÖRTMEK İÇİN GENSEC MİNİBÜSÜNÜ VURUN. BU ŞEHRİN POLİSLERİ SONUÇTA PEK ZEKİ DEĞİL.",
["pln_election_stage3_01_any_01"] = "UNUTMAYIN, BANKA SOYMAYA GELDİK. BU SIRADA BAZI SEÇİM EKİPMANLARI YOK OLURSA NE YAZIK. OY SONUÇLARI DA BİR ŞEKİLDE KULLANILAMAZ OLSA GERÇEKTEN ÇOK YAZIK OLUR...",
["pln_election_stage3_02_any_01"] = "BU ÇETREFİLLİ BİR İŞ ÇOCUKLAR. NASIL YAKLAŞACAĞINIZ SİZE KALMIŞ.",
["pln_election_stage3_02_any_02"] = "GÜRÜLTÜ KOPARMADAN ÖNCE ETRAFA BAKMAK İYİ FİKİR OLABİLİR. BELKİ DAHA İYİ BİR YAKLAŞIM BULURSUNUZ.",
["pln_election_stage3_03_any_01"] = "YAKINLARDA OY SONUÇLARININ BULUNDUĞU BİR SUNUCU OLMALI. SUNUCUYU BULUN VE VERİLERİ KULLANILAMAZ HÂLE GETİRİN.",
["pln_election_stage3_03_any_02"] = "SEÇİM SONUÇLARI YAKINDAKİ BİR SUNUCUDA KAYITLI. SUNUCUYU BULUP VERİLERİ BOZUN.",
["pln_election_stage3_04_any_01"] = "VERİ KARIŞTIRICI ÇÖKTÜ. SUNUCUYA GİDİP TEKRAR ÇALIŞTIRIN.",
["pln_election_stage3_04_any_02"] = "GÖRÜNÜŞE GÖRE SİNYAL BOZUCU YAZILIM ÇÖKTÜ. YENİDEN BAŞLATMANIZ GEREKECEK!",
["pln_election_stage3_05_any_01"] = "KARIŞTIRICI YİNE ÇÖKTÜ. DÜZELTİN!",
["pln_election_stage3_05_any_02"] = "KAHRETSİN, YİNE ÇÖKTÜ. VERİLERİ KARIŞTIRMA İŞLEMİNİ YENİDEN BAŞLATIN!",
["pln_election_stage3_06_any_01"] = "TAMAM, VERİLER KARIŞTIRILDI. BASİT BİR SABİT DİSK ARIZASI GİBİ GÖRÜNECEK. ",
["pln_election_stage3_06_any_02"] = "TAMAM, VERİLER KARIŞTI! SIRADAN BİR SABİT DİSK ARIZASI GİBİ GÖRÜNECEK.",
["pln_election_stage3_07_any_01"] = "ŞİMDİ O DUVARI AÇIN! PATLAMA OY MAKİNELERİNİ PARAMPARÇA EDECEK.",
["pln_election_stage3_07_any_02"] = "BANKAYA DALMA VAKTİ! PATLAMA OY MAKİNELERİNİN İŞİNİ BİTİRECEK.",
["pln_election_stage3_08_any_01"] = "DUVAR TARİH OLDU. İLERLEYİN!",
["pln_election_stage3_08_any_02"] = "DUVAR YIKILDI, İLERLEYİN!",
["pln_election_stage3_09_any_01"] = "TAMAM, KASA DAİRESİNİ AÇMA VAKTİ!",
["pln_election_stage3_09_any_02"] = "KAYBEDECEK VAKİT YOK! O KASA DAİRESİNİN KAPISINI AÇIN!",
["pln_election_stage3_10_any_01"] = "PARAYI ALMA VAKTİ, MİLLET!",
["pln_election_stage3_10_any_02"] = "KASA DAİRESİ AÇIK, PARAYI ÇANTALAMA VAKTİ!",
["pln_election_stage3_11_any_01"] = "KASA DAİRESİNE GİRİP İÇİNDE NE VAR BAKIN!",
["pln_election_stage3_11_any_02"] = "KASA DAİRESİ AÇILDI, İÇİNDE NE VAR BAKMA VAKTİ!",
["pln_election_stage3_12_any_01"] = "HAYIR! KASA DAİRESİ NEREDEYSE BOMBOŞ! ÇIKIN ORADAN!",
["pln_election_stage3_12_any_02"] = "GÖRÜNÜŞE GÖRE BU İŞİN KAZIĞINI BİZ YEDİK. KASA DAİRESİ BOŞ! HEMEN ÇIKIN ORADAN!",
["pln_election_stage3_13_any_01"] = "BU KASA DAİRESİ NAKİTLE DOLU! ALTINDAN KALKABİLİRSENİZ HEPSİNİ ALABİLİRSİNİZ!",
["pln_election_stage3_13_any_02"] = "BU KASA DAİRESİ PARA DOLU! NE KADARINI ALIP KAÇABİLECEĞİNİZE KARAR VERMENİZ GEREK.",
["pln_election_stage3_14_any_01"] = "KAÇIŞ ARACI GARAJDA BEKLİYOR.",
["pln_election_stage3_14_any_02"] = "TAMAM, KAÇIŞ ARACI GARAJDA SİZİ BEKLİYOR.",
["pln_election_stage3_15_any_01"] = "KAÇIŞ ARACI ANA GİRİŞİN HEMEN DIŞINDA BEKLİYOR!",
["pln_election_stage3_15_any_02"] = "YÜRÜME VAKTİ! KAÇIŞ ARACI ANA GİRİŞİN YAKININDA PARK ETTİ!",
["pln_election_stage3_16_any_01"] = "KAMERALAR BAŞINIZA BELA OLUYORSA KAMERA OPERATÖRÜNÜ DEVRE DIŞI BIRAKABİLİRSİNİZ. ÜST KATTAKİ GÜVENLİK OFİSİNDE...",
["pln_election_stage3_16_any_02"] = "KAMERA GÖZETİMİNDEN KURTULMAK İSTERSENİZ ÜST KATTA GÜVENLİK OFİSİ VAR.",
["pln_election_stage3_17_any_01"] = "O KAMERALAR ARTIK SORUN OLMAYACAK!",
["pln_election_stage3_17_any_02"] = "GÖZETLEME GÖREVLİSİ İNDİRİLDİ, KAMERALAR ARTIK SİZİ RAHATSIZ ETMEZ!",
["pln_election_stage3_18_any_01"] = "BANKANIN, GÜVENLİK OFİSİNDEN KAPATILABİLEN KEPENKLERİ VAR. POLİSİ UZAK TUTMANIZA YARDIMCI OLURLAR!",
["pln_election_stage3_18_any_02"] = "GÜVENLİK OFİSİNDE BANKANIN KEPENKLERİNİ KAPATAN BİR KONTROL VAR. POLİSLERİ BANKADAN UZAK TUTMANIZA YARDIM EDEBİLİR.",
["pln_election_stage3_19_any_01"] = "YAKINDAKİ ÇATILARA KESKİN NİŞANCI YERLEŞTİRİYORLAR GİBİ. GÖZÜNÜZ AÇIK OLSUN!",
["pln_election_stage3_19_any_02"] = "DİKKAT, BÖLGEYE KESKİN NİŞANCILAR YERLEŞİYOR!",
["pln_election_stage3_brief_01"] = "BELKİ OYLARI DEĞİŞTİREMEYİZ AMA KULLANILMALARINI ENGELLEYEBİLİRİZ. AVM'DEKİ OY MAKİNELERİNİ VURACAĞIZ.",
["pln_election_stage3_brief_01b"] = "AMA SADECE BUNU YAPAMAYIZ. ÇOK DAHA BÜYÜK BİR SUÇLA ÜZERİNİ ÖRTMEMİZ GEREK. O YÜZDEN BU ARADA BANKAYI SOYUN. BİLİYORUM, BİRAZ AŞIRI AMA AŞIRILIK BİZİM İŞİMİZ.",
["pln_election_stage3_end_a_01"] = "SEÇİMİ KİM KAZANACAK BİLMİYORUM AMA ŞUNU SÖYLEYEYİM: BENİM OYUM SİZE. İYİ TOPARLADINIZ. NAKİT İÇİN KASA DAİRESİNİ VURMANIN DA EPEY FAYDASI VAR. ARKAMI KOLLADIĞINIZ İÇİN SAĞ OLUN.",
["pln_election_stage3_end_a_02"] = "TAMAM, İÇİMİZ RAHAT OLABİLİR. BUGÜN OY VERİLMEYECEK. ÜSTÜNE PARA DA ALDIK. GÜZEL ZAFER, GÜZEL GÜNLER.",
["pln_election_stage3_end_b_01"] = "OYLAR SİLİNDİ. KIÇIMIZI KURTARDIK. UFAK BİR SOYGUN KAZASI GİBİ GÖRÜNÜYOR. GANİMETİ ALAMADIK AMA BİR DAHAKİNE DAHA İYİ YAPARIZ.",
["pln_election_stage3_end_b_02"] = "EH, BU İŞTE ZENGİN OLMADIK AMA ELEPHANT İÇİN SORUN DEĞİL. SONRAKİ İŞTE DAHA İYİSİNİ YAPARIZ.",
["pln_election_stage3_intro_a_01"] = "İÇERİ GİRİN, OY MAKİNELERİ BANKANIN YAKININDA. BANKAYI VURUN, KASA DAİRESİNİ AÇIN VE KIYAMETİ KOPARIN. MEKÂNI KURŞUN YAĞMURUNA TUTUN. OY MAKİNELERİ DE TALİHSİZ BİR YAN HASAR OLARAK YOK OLSUN.",
["pln_election_stage3_intro_a_02"] = "TEK YAPMANIZ GEREKEN BANKAYI VURUP KASA DAİRESİNİ AÇMAK. KARGAŞADA OY MAKİNELERİNİ YOK EDİN.",
["pln_election_stage3_intro_a_02b"] = "YENİLERİNİ GETİRENE KADAR ÇOK GEÇ OLACAK VE BU BÖLGEDE OY KULLANILAMAYACAK. ",
["pln_esc_01_to_arrival_heli"] = "HELİKOPTER BİR DAKİKA UZAKTA.",
["pln_esc_01_to_arrival_van"] = "MİNİBÜS HEMEN KÖŞEDE. BİR DAKİKA İÇİNDE ORADA OLACAK.",
["pln_esc_01_to_departure_heli"] = "ACELE EDİN! KALKIŞA SADECE BİR DAKİKA VAR!",
["pln_esc_01_to_departure_van"] = "MİNİBÜS BİR DAKİKA SONRA GİDİYOR. TOPARLANIN!",
["pln_esc_02_to_arrival"] = "ORADAN DEFOLUP GİDEBİLMENİZE İKİ DAKİKA VAR.",
["pln_esc_02_to_departure"] = "KAÇIŞ ARACI İKİ DAKİKAYA GİDİYOR, SİZİNLE YA DA SİZSİZ.",
["pln_esc_03_to_arrival"] = "TAHMİNİ VARIŞ ÜÇ DAKİKA.",
["pln_esc_03_to_departure"] = "ALABİLDİĞİNİZ KADAR GANİMETİ GÜVENE ALIN. KAÇIŞ ARACI ÜÇ DAKİKA SONRA GİDİYOR.",
